  /** Cartão fechado há mais de N dias sai do Kanban. `null` = nunca. */
  archive_after_days: number | null;
  /** Arquivado em (RFC 3339). `null` = ativo. */
  archived_at: string | null;
  /** Cartões vivos no quadro. */
