  /** Snowflake. */
  id: string;
  /** Aceita lançamento (analítica). */
  is_analytic: boolean;
  /** Nome. */
  name: string;
  /** Natureza (`asset`, `liability`, `equity`, `revenue`, `expense`, `result`). */
  nature: PayChartNature;
  /** Organização dona (vazio = escopo tenant). */
  organization_id: string;
  /** Conta pai (vazio = raiz da árvore). */
