/** A resposta do assistente: uma sugestão, nunca enviada. */
export interface ChatAssist {
  /** As mensagens citadas (pergunta e busca), sempre entre as que quem pede lê. */
  citations: ChatAssistCitation[];
  /** O modelo que respondeu. */
  model: string;
  /** O texto. Vazio só na busca sem nenhum trecho achado. */
  text: string;
}

/** Uma pergunta sobre a conversa. */
export interface ChatAssistAskBody {
  /** A pergunta (até 4000 caracteres). */
  question: string;
  /** Opcional: a raiz de uma thread, em vez da linha principal. */
  thread_id?: string;
}

/** Uma mensagem que sustenta a resposta. */
export interface ChatAssistCitation {
  /** Quando (RFC 3339). */
  at: string;
  /** Nome do autor. */
  author_name: string;
  /** A conversa dela. */
  conversation_id: string;
  /** O começo do texto. */
  excerpt: string;
  /** A mensagem. */
  message_id: string;
  /** A raiz, quando a mensagem está numa thread. */
  parent_id: string | null;
}

/** O rascunho a reescrever. */
export interface ChatAssistRewriteBody {
  /** O rascunho (até 4000 caracteres). */
  draft: string;
  /** O tom (padrão `fix`). */
  tone?: ChatAssistTone;
}

/** O recorte da conversa que o assistente lê. */
export interface ChatAssistScopeBody {
  /** Opcional: a raiz de uma thread, em vez da linha principal. */
  thread_id?: string;
}

/** Uma pergunta sobre o chat inteiro de quem pede. */
export interface ChatAssistSearchBody {
  /** A pergunta (até 4000 caracteres). */
  question: string;
}

/** O tom da reescrita. */
export type ChatAssistTone = "shorter" | "formal" | "friendly" | "fix";

/** Um anexo. */
export interface ChatAttachmentDto {
  /** Tipo declarado. */
  content_type: string;
  /** Id. */
  id: string;
  /** Nome do arquivo. */
  name: string;
  /** Tamanho. */
  size_bytes: number;
}

/** Uma lista de transmissão nova. */
export interface ChatBroadcastBody {
  /** Título. */
  title: string;
  /** De 1 a 256 pessoas além de quem cria. */
  user_ids: string[];
}

/** Entregas e leituras de uma mensagem de lista de transmissão. */
export interface ChatBroadcastStats {
  /** Cópias que o destinatário já leu. */
  read: number;
  /** Cópias entregues nas conversas diretas. */
  sent: number;
}

/** Um canal novo. */
export interface ChatChannelBody {
  /** Descrição. */
  description?: string | null;
  /** Título. */
  title: string;
  /** Unidade do IAM. */
  unit_id?: string | null;
  /** `open` ou `private`. */
  visibility: CommunityChatVisibility;
}

/** A conversa e os participantes. */
export interface ChatConversationDetail {
  /** A conversa. */
  conversation: ChatConversationSummary;
  /** Participantes ativos. */
  members: ChatMemberDto[];
}

/** A conversa de um item de lista pessoal (salvas, threads, busca). */
export interface ChatConversationLabel {
  /** Id. */
  id: string;
  /** `direct`, `group`, `channel` ou `broadcast`. */
  kind: CommunityChatKind;
  peer: ChatUserDto | null;
  /** `null` na direta (a tela mostra `peer`). */
  title: string | null;
}

/** Uma página de conversas. */
export interface ChatConversationPage {
  /** Itens. */
  items: ChatConversationSummary[];
  /** Cursor da próxima página (`null` = fim). */
  next_cursor: string | null;
}

/** O que muda numa conversa. */
export interface ChatConversationPatch {
  /** Arquivar ou desarquivar. */
  archived?: boolean | null;
  /** Nova descrição. */
  description?: string | null;
  /** Novo título. */
  title?: string | null;
}

/** Uma conversa na lista. */
export interface ChatConversationSummary {
  /** Arquivada. */
  archived: boolean;
  /** Descrição. */
  description: string | null;
  /** Id. */
  id: string;
  /**
   * `direct`, `group`, `channel` ou `broadcast` (lista de transmissão, que
   * só o dono vê; `members_count` conta os destinatários).
   */
  kind: CommunityChatKind;
  last_message: ChatLastMessageDto | null;
  /** Instante da última mensagem. */
  last_message_at: string | null;
  /** Participantes ativos. */
  members_count: number;
  /** Menções não lidas. */
  mentions: number;
  /**
   * Silenciada por quem pede: sem sininho, nem de menção. Não lidas e
   * menções seguem contando.
   */
  muted: boolean;
  /** Até quando (`null` com `muted` = para sempre). */
  muted_until: string | null;
  /** Só no canal. */
  organization_id: string | null;
  peer: ChatUserDto | null;
  role: CommunityChatRole | null;
  /** Só no canal: o agrupamento (`null` = solto). */
  section_id: string | null;
  /** Só no canal: a ordem dentro do agrupamento (empate cai no id). */
  section_position: number;
  /** `null` na direta (a tela mostra `peer`). */
  title: string | null;
  /** Canal ligado a uma unidade do IAM. */
  unit_id: string | null;
  /** Não lidas (teto 999). */
  unread: number;
  visibility: CommunityChatVisibility | null;
}

