/** Um aviso do stream (o `data:` da linha SSE). */
export interface ChatStreamEvent {
  /** Conversa. */
  conversation_id: string;
  /**
   * Em `thread.replied`: quem recebe segue a thread (conta nas não lidas
   * de "Threads").
   */
  following: boolean;
  /**
   * `message.created`, `message.updated`, `message.deleted`,
   * `thread.replied`, `conversation.updated`, `membership.changed`, `read`
   * (com `parent_id`: a leitura da thread), `reaction.added`,
   * `reaction.removed`, `pin.added`, `pin.removed`, `typing` (efêmero: o
   * cliente apaga depois de 6 s sem outro), `thread.followed`,
   * `thread.unfollowed`, `saved.changed`, `mute.changed` ou
   * `scheduled.changed` (os cinco últimos só para quem fez), e
   * `meeting.ringing` (efêmero: alguém abriu a reunião da conversa, leia
   * por `GET.../conversations/{id}/meeting`; nunca para quem chamou).
   * `resync` só como primeiro aviso de uma reconexão cujo `Last-Event-ID`
   * não retomou (sem ids): releia pela rota normal.
   */
  kind: CommunityChatEventKind;
  /** Mensagem (`null` quando o aviso não é de mensagem). */
  message_id: string | null;
  /** Raiz (`thread.replied` e avisos de resposta). */
  parent_id: string | null;
  /**
   * Quem fez, em `reaction.*`, `pin.*`, `typing` e `meeting.ringing`
   * (`null` nos demais).
   */
  user_id: string | null;
}

