  /** `VEVENT` recusados. */
  failed: number;
  /** Havia mais erros que os listados. */
  more_errors: boolean;
  /** O arquivo passou do teto de eventos: o resto ficou de fora. */
  truncated: boolean;
  /** Eventos que já existiam iguais. */
