  /** Código IBGE do município, 7 dígitos (vazio = ausente). */
  municipality_code: string;
  /** Nome do município (vazio = ausente). */
  municipality_name: string;
  /** Número (vazio = ausente). */
  number: string;
  /** Organização dona do emitente (vazio = cadastro manual, sem vínculo). */
