/** Operação financeira (resposta canônica). */
export interface FinancialOperationDto {
  /** Criação (RFC3339). */
  created_at: string;
  /** Descrição livre. */
  description: string;
  /** Snowflake da operação. */
  id: string;
  /** Chave idempotente reconhecida. */
  idempotency_key: string;
  /** Tipo (`deposit`/`payout`/`reversal`/…). */
  operation_type: PayOperationType;
  /** Organização dona (vazio = escopo tenant). */
  organization_id: string;
  /**
   * ID da entidade de origem, Snowflake decimal em texto; `null` = sem
   * origem. Texto porque passa de 2^53 e o `JSON.parse` comum arredondaria.
   */
  reference_id: string | null;
  /** Origem (`accounts_receivable`/…) ou vazio. */
  reference_kind: string;
  /**
   * Descrição legível do documento de origem (vazio = não resolvido).
   *
   * MA09 - a tela mostrava só `<reference_kind> #<reference_id>`
   * (`psp_charge #23578224365928448`), um id técnico que não diz nada ao
   * operador. Resolvido no mesmo SELECT da operação, sem dinheiro
   * formatado: a formatação é do front, que conhece o locale.
   */
  reference_label: string;
  /** Operação original estornada (vazio se `operation_type != reversal`). */
  reversal_of: string;
  /** Estado (`pending`/`processing`/`success`/`failed`/`reversed`). */
  status: PayOperationStatus;
  /** Última transição de status (RFC3339, `null` se nunca alterada). */
  updated_at: string | null;
}

/** Snapshot da posição financeira (Grupo A). */
