/** Sentido da operação do documento fiscal (`tpNF`): só documenta os valores, o fio é texto. */
export type FiscalDocumentDirection = "outgoing" | "incoming";

/** Documento fiscal (resposta). Campos vazios = ausente. */
export interface FiscalDocumentDto {
  /** Chave de acesso (44 dígitos; presente a partir de `generated`). */
  access_key: string;
  /** Autorização (RFC3339; `null` enquanto não autorizado). */
  authorized_at: string | null;
  /** Criação (RFC3339). */
  created_at: string;
  /** Link do DANFE em PDF (re-hospedado no `archive`; presente após autorização). */
  danfe_url: string;
  /** Sentido (`tpNF`): `outgoing` (saída) | `incoming` (entrada). */
  direction: FiscalDocumentDirection;
  /** CNPJ do emitente. */
  emitter_cnpj: string;
  /** Ambiente (`production` | `homologation`). */
  environment: string;
  /** Snowflake do documento. */
  id: string;
  /** Modelo (`nfe` | `nfce`). */
  model: string;
  /** Número (`nNF`). */
  number: number;
  /** Protocolo (`nProt`; após autorização). */
  protocol: string;
  /** Finalidade (`finNFe`): `normal` | `return` (devolução). */
  purpose: string;
  /** Referência financeira externa (se informada na emissão). */
  receivable_ref: string;
  /** Como emitir de novo: `same_number` | `new_number`; vazio quando não pode. */
  reissue_mode: string;
  /** A nota rejeitada que esta substitui. */
  reissue_of: string;
  /** Série. */
  series: number;
  /**
   * Estado no ciclo de vida: `draft`, `generated`, `signed`, `validated`,
   * `transmitting`, `authorized`, `rejected`, `denied`, `cancelled` ou
   * `contingency`.
   */
  status: FiscalDocumentStatus;
  /** O que fazer a seguir (vazio quando não há ação). */
  status_action: string;
  /** `cStat` da SEFAZ. */
  status_code: number;
  /**
   * Categoria do `cStat`: `success` | `fixable` | `registration` |
   * `unavailable` | `denied` | `already_at_sefaz` | `unknown`.
   */
  status_outcome: string;
  /** `xMotivo` da SEFAZ. */
  status_reason: string;
  /** O `cStat` em palavras de quem opera (vazio sem `cStat`). */
  status_title: string;
  /** A nota que substituiu esta. */
  superseded_by: string;
}

/** Estado do documento fiscal no ciclo de vida: só documenta os valores, o fio é texto. */
export type FiscalDocumentStatus = "draft" | "generated" | "signed" | "validated" | "transmitting" | "authorized" | "rejected" | "denied" | "cancelled" | "contingency";

