/** Resultado da baixa. */
export interface FixedAssetDisposeDto {
  /** O bem baixado. */
  asset: FixedAssetDto;
  /** Meses que faltavam e entraram antes da baixa. */
  catch_up: FixedAssetRunDto;
}

/** Um bem com a posição de depreciação. */
export interface FixedAssetDto {
  /** Depreciação lançada até agora. */
  accumulated: DecimalText;
  /** Depreciação acumulada. */
  accumulated_account_id: string;
  /** Aquisição `AAAA-MM-DD`. */
  acquisition_date: string;
  /** Conta do bem. */
  asset_account_id: string;
  /** Custo menos a acumulada. */
  book_value: DecimalText;
  /** Código. */
  code: string;
  /** Custo. */
  cost: DecimalText;
  /** Centro de custo. */
  cost_center_id: string | null;
  /** Criação (RFC 3339). */
  created_at: string;
  /** Moeda. */
  currency: string;
  /** Conta da perda na baixa. */
  disposal_account_id: string | null;
  /** Operação da baixa no razão. */
  disposal_operation_id: string | null;
  /** Motivo da baixa. */
  disposal_reason: string | null;
  /** Data da baixa `AAAA-MM-DD`. */
  disposed_on: string | null;
  /** Despesa de depreciação. */
  expense_account_id: string;
  /** Bem (Snowflake decimal). */
  id: string;
  /** Início de uso `AAAA-MM-DD`. */
  in_service_date: string;
  /** Último mês lançado `AAAA-MM`. */
  last_period: string | null;
  /** Parcela mensal (o último mês leva o resto). */
  monthly_installment: DecimalText;
  /** Meses lançados. */
  months_posted: number;
  /** Nome. */
  name: string;
  /** Organização dona, `null` = tenant. */
  organization_id: string | null;
  /** Valor residual. */
  residual_value: DecimalText;
  /** `active` ou `disposed`. */
  status: PayFixedAssetStatus;
  /** Última alteração (RFC 3339). */
  updated_at: string;
  /** Vida útil em meses. */
  useful_life_months: number;
}

/** Página de bens. */
export interface FixedAssetListDto {
  /** Bens, mais novos primeiro. */
  items: FixedAssetDto[];
  /** Cursor da próxima página; vazio na última. */
  next_page_token: string;
}

/** Um mês lançado pela rodada. */
export interface FixedAssetPostingDto {
  /** Valor. */
  amount: DecimalText;
  /** Bem. */
  asset_id: string;
  /** Código do bem. */
  code: string;
  /** Operação no razão. */
  operation_id: string;
  /** Mês `AAAA-MM`. */
  period: string;
}

/** Corpo da rodada de depreciação. */
export interface FixedAssetRunBody {
  org_scope?: PayOrgScope | null;
  /** Organização. Ausente = a da sessão. */
  organization_id?: string | null;
  /**
   * Último mês a lançar `AAAA-MM`, incluso. Ausente = mês corrente; futuro
   * é recusado.
   */
  up_to_month?: string | null;
}

/** Resultado da rodada. */
export interface FixedAssetRunDto {
  /** `true` quando o teto da rodada parou antes do fim; rode de novo. */
  more_pending: boolean;
  /** Meses lançados. */
  posted: FixedAssetPostingDto[];
  /** Meses pulados. */
  skipped: FixedAssetSkipDto[];
  /** Soma lançada. */
  total: DecimalText;
}

/** Um mês que a rodada não lançou, com o motivo. */
export interface FixedAssetSkipDto {
  /** Bem. */
  asset_id: string;
  /** Código do bem. */
  code: string;
  /** Mês `AAAA-MM`. */
  period: string;
  /** Motivo (período fechado, conflito). */
  reason: string;
}

/**
 * Corpo da edição. Campo ausente fica como está. Cronograma (datas, custo,
 * residual, vida, contas) só muda antes do primeiro mês lançado.
 */
export interface FixedAssetUpdateBody {
  /** Depreciação acumulada. */
  accumulated_account_id?: string | null;
  /** Data de aquisição `AAAA-MM-DD`. */
  acquisition_date?: string | null;
  /** Conta do bem. */
  asset_account_id?: string | null;
  /** `true` tira o centro de custo; ganha de `cost_center_id`. */
  clear_cost_center?: boolean;
  /** Código. */
  code?: string | null;
  /** Custo. */
  cost?: string | null;
  /** Centro de custo novo. */
  cost_center_id?: string | null;
  /** Moeda ISO 4217. */
  currency?: string | null;
  /** Despesa de depreciação. */
  expense_account_id?: string | null;
  /** Início de uso `AAAA-MM-DD`. */
  in_service_date?: string | null;
  /** Nome. */
  name?: string | null;
  /** Valor residual. */
  residual_value?: string | null;
  /** Vida útil em meses. */
  useful_life_months?: number | null;
}

/** Tipo de uma conexão de banco anunciada pelo servidor: só documenta os valores, o fio é texto. */
export type FleetConnectionEngine = "postgres" | "mysql" | "mariadb" | "sqlserver" | "oracle";

/**
 * Resposta de `POST /v1/fleet/agent/handshake`, como o `fleet` a escreve.
 *
 * Só documenta o formato: o gateway repassa os bytes sem ler.
 */
export interface FleetHandshakeAcceptDto {
  /** Pública X25519 efêmera da frota (base64url). */
  eph: string;
  /** Fim da sessão, segundos Unix. */
  expires_at: number;
  /** Id da sessão, que vai no cabeçalho `X-Fz-Session` de cada chamada (base64url). */
  session_id: string;
  /** Assinatura Ed25519 da frota sobre o transcrito (base64url). */
  sig: string;
}

/**
 * Resposta de `POST /v1/fleet/join`, como o `fleet` a escreve.
 *
 * Só documenta o formato: o gateway repassa os bytes sem ler.
 */
export interface FleetJoinAcceptDto {
  /** Id, nome e camada do servidor, assinados pela frota e cifrados para a efêmera do agente (base64url). */
  ct: string;
}

/** Um fluxo gravado. */
export interface FlowDto {
  /** Criação (RFC3339). */
  created_at: string;
  /**
   * Versão do desenho **em vigor**.
   *
   * Começa em 1 e só avança quando o grafo muda: renomear ou desativar não
   * produz versão nova, porque nenhuma das duas coisas muda o que
   * aconteceria com um fato.
   */
  current_version: number;
  graph_json: string;
  /**
   * Id do fluxo (snowflake como string - `u64` não sobrevive ao JSON de
   * cliente JS sem perda de precisão).
   */
  id: string;
  /** Fluxo desativado não dispara, mas continua visível e editável. */
  is_active: boolean;
  /** Nome dado pela pessoa. */
  name: string;
  /** Escopo. Vazio = vale para o tenant inteiro. */
  organization_id: string;
  /** `event_type` do gatilho, **derivado do desenho** pelo serviço. */
  trigger_event_type: string;
  /** Última edição (RFC3339); `null` se nunca foi editado. */
  updated_at: string | null;
}

/**
 * Situação da promessa feita a um executor externo, vazia quando o
 * passo não prometeu nada. Só documenta os valores, o fio é texto.
 */
export type FlowHandoffStatus = "published" | "not_delivered" | "";

/**
 * Onde está um disparo à mão: só documenta os valores, o fio é
 * texto.
 */
export type FlowManualRunStatus = "pending" | "running" | "done" | "dropped" | "dead";

/** Um modelo pronto e a situação de cada fluxo dele. */
export interface FlowPresetDto {
  /** Os fluxos, na ordem do modelo. */
  entries: FlowPresetEntryDto[];
  /** Nome do modelo. */
  label: string;
  /** Chave do modelo (ex.: `subscription_reminders`). */
  preset_key: string;
}

/** Um fluxo de modelo pronto e a situação dele na organização da sessão. */
export interface FlowPresetEntryDto {
  /**
   * Id do fluxo instalado (`GET /v1/flow/flows/{id}`); vazio quando não
   * instalado.
   */
  flow_id: string;
  /** `true` quando o fluxo deste modelo existe na organização. */
  installed: boolean;
  /** Nome do fluxo que o modelo cria. */
  name: string;
  /**
   * Por que não foi instalado nesta chamada (nome já usado por outro
   * fluxo, por exemplo); vazio na leitura e quando instalou.
   */
  reason: string;
  /** O fato que dispara o fluxo (ex.: `pay.subscription.due_soon`). */
  trigger_event_type: string;
}

/** Uma volta: um fluxo sobre um fato. */
export interface FlowRunDto {
  /** Quantas vezes a volta foi retomada depois de parar pela metade. */
  attempts: number;
  /** Id do evento que originou a volta. */
  event_id: string;
  /**
   * O fato como chegou, em JSON. Só vem no detalhe
   * (`GET /v1/flow/runs/{id}`); `null` nas listagens e nas voltas que não
   * guardaram o fato.
   */
  event_payload: Record<string, unknown> | null;
  /** `event_type` do evento. */
  event_type: string;
  /** Preenchido quando o desfecho é `failed`. */
  failure_reason: string;
  /** Fim da volta (RFC3339); `null` enquanto ela não terminou. */
  finished_at: string | null;
  /** Fluxo que rodou. */
  flow_id: string;
  /**
   * Versão do desenho que rodou.
   *
   * ⚠️ `0` é **volta anterior ao **, e não "primeira versão":
   * afirmar a v1 diria algo que ninguém sabe.
   */
  flow_version: number;
  /** Id da volta. */
  id: string;
  /** Quando a próxima retomada está agendada (RFC3339); `null` quando não há. */
  next_attempt_at: string | null;
  /** Organização **do fato**, nunca a da sessão. Vazio = fato do tenant. */
  organization_id: string;
  /** `started`, `executed`, `filtered`, `suppressed`, `failed` ou `waiting`. */
  outcome: string;
  /**
   * Quem disparou a volta pela tela; vazio na volta do fato, da agenda e
   * da chamada recebida.
   */
  requested_by: string;
  /** Início da volta (RFC3339). */
  started_at: string;
  /** Passos percorridos, na ordem. */
  steps: FlowRunStepDto[];
  /**
   * Volta de TESTE: nada saiu, salvo o bloco marcado "chamar de
   * verdade". Fica fora dos totais de `GET /v1/flow/runs/stats`.
   */
  test: boolean;
}

/** Voltas de um fluxo numa janela de dias, por desfecho. */
export interface FlowRunStatDto {
  /** Voltas que executaram as ações. */
  executed: number;
  /** Voltas que falharam. */
  failed: number;
  /** Voltas paradas por uma condição. */
  filtered: number;
  /** Fluxo contado. */
  flow_id: string;
  /** Desfecho da volta mais recente. */
  last_outcome: string;
  /** Início da volta mais recente (RFC3339). */
  last_run_at: string;
  /** Voltas reivindicadas e ainda não concluídas. */
  started: number;
  /** Voltas sem corpo do fato (o domínio pediu para não seguir). */
  suppressed: number;
  /** Todas as voltas da janela. */
  total: number;
  /** Voltas paradas num bloco de espera. */
  waiting: number;
}

/** Contagem de voltas por fluxo. */
export interface FlowRunStatsDto {
  /** Um item por fluxo que rodou na janela, o mais recente primeiro. */
  items: FlowRunStatDto[];
}

/** Um passo percorrido numa volta. */
export interface FlowRunStepDto {
  /**
   * Quando o passo aconteceu (RFC3339). Vazio nas voltas gravadas antes
   * deste campo.
   */
  at: string;
  /**
   * A chamada do bloco "Chamar API": `method`, `path`, `status`, `ok`,
   * `elapsed_ms`, `error` e `body` (a resposta JSON, com valores de chaves
   * sensíveis em `***`). `null` em todo passo que não é a resposta de uma
   * chamada.
   */
  call: Record<string, unknown> | null;
  /** O que aconteceu, na língua de quem opera. */
  detail: string;
  /**
   * Chave da promessa feita a um executor externo (e-mail, sininho,
   * webhook); vazia quando o passo não entregou nada a ninguém.
   */
  handoff_key: string;
  /**
   * `published` (entregue ao executor, desfecho ainda não voltou) ou
   * `not_delivered`; vazio quando não há promessa.
   */
  handoff_status: FlowHandoffStatus;
  /** A chave daquele nó (o `event_type` do gatilho, o efeito da ação). */
  key: string;
  /**
   * Família do passo: `trigger`, `condition`, `action` e `wait` são nós do
   * desenho; `reply` é a resposta de um ensaio, `delivery` a entrega a um
   * executor, `resume` a retomada de uma espera e `join` o encontro de ramos.
   */
  kind: FlowRunStepKind;
  /** Nó do desenho a que o passo corresponde; `0` é o gatilho. */
  node_id: number;
  /** `false` marca o passo em que a volta parou. */
  ok: boolean;
}

/**
 * Família de um passo da volta: só documenta os valores, o fio é
 * texto.
 */
export type FlowRunStepKind = "trigger" | "condition" | "action" | "wait" | "reply" | "delivery" | "resume" | "join";

/** Página de voltas. */
export interface FlowRunsPageDto {
  /** Voltas, mais recentes primeiro. */
  items: FlowRunDto[];
  /** Cursor da próxima página; vazio quando acabou. */
  next_page_token: string;
}

/** Um desenho **congelado**. */
export interface FlowVersionDto {
  /** Quando esta versão foi congelada (RFC3339). */
  created_at: string;
  /** Id do fluxo a que a versão pertence. */
  flow_id: string;
  /** O desenho de então, como JSON. */
  graph_json: string;
  /** Nome que o fluxo tinha quando esta versão nasceu. */
  name: string;
  /** Gatilho daquele desenho. */
  trigger_event_type: string;
  /** Número da versão, monotônico por fluxo a partir de 1. */
  version: number;
}

/** Página de versões. */
export interface FlowVersionsPageDto {
  /** Versões, da mais nova para a mais velha. */
  items: FlowVersionDto[];
  /** Cursor da próxima página; vazio quando acabou. */
  next_page_token: string;
}

/** Página de fluxos. */
export interface FlowsPageDto {
  /** Fluxos, mais recentes primeiro. Inclui os desativados. */
  items: FlowDto[];
  /** Cursor da próxima página; vazio quando acabou. */
  next_page_token: string;
}

/** Pasta do cofre (hierarquia - Fase C). */
export interface FolderDto {
  /** Criação (RFC 3339). */
  created_at: string;
  /** Arquivos que quem pede vê na pasta e nas subpastas. */
  files: number;
  /** Snowflake da pasta. */
  id: string;
  /** Gerenciada pelo sistema (não-deletável por usuário comum). */
  managed: boolean;
  /** Nome da pasta. */
  name: string;
  /** Pasta-mãe (vazio = raiz do cofre). */
  parent_id: string;
  /** Bytes que quem pede vê na pasta e nas subpastas, lixeira fora. Só a listagem preenche; a criação devolve 0. */
  size_bytes: number;
}

/** Lista de pastas. */
export interface FoldersListDto {
  /** Pastas. */
  items: FolderDto[];
}

/** O cardápio da loja. */
export interface FoodMenuDto {
  /** As seções, na ordem. */
  sections: FoodMenuSectionDto[];
  /** O envio. */
  state: FoodMenuStateDto;
}

/** Corpo de criar ou trocar uma seção. */
export interface FoodMenuSectionBody {
  /** O que o cliente lê ("Pizzas"). */
  name: string;
  /**
   * Os pratos seguem o saldo do estoque: o esgotado (disponível zero, ou
   * no estoque mínimo da conta) vai indisponível ao provider e volta
   * sozinho com o saldo. Ausente = não seguem; ligue só onde há saldo
   * lançado ("Bebidas"), porque o prato feito na hora não tem.
   */
  pause_by_stock?: boolean;
  /** Ordem no cardápio, da menor para a maior. */
  position?: number;
  /** Escondida ou não. */
  status?: FoodMenuSectionStatusDto;
  /**
   * Pratos comuns ou pizza. Ausente = comuns; o `PUT` troca o corpo
   * inteiro, então quem troca uma seção de pizza manda `pizza` de novo.
   */
  template?: FoodMenuSectionTemplateDto;
}

/** Uma seção do cardápio. */
export interface FoodMenuSectionDto {
  /** Conta (a loja). */
  account_id: string;
  /** Quando nasceu (RFC 3339). */
  created_at: string;
  /** Nome, ordem ou status mudaram e ainda não foram ao provider. */
  dirty: boolean;
  /** Id. */
  id: string;
  /** Nome. */
  name: string;
  /** Os pratos seguem o saldo do estoque. */
  pause_by_stock: boolean;
  /** Ordem. */
  position: number;
  /** Quando foi ao provider pela última vez (RFC 3339); `null` = nunca. */
  pushed_at: string | null;
  /** Escondida ou não. */
  status: FoodMenuSectionStatusDto;
  /** Pratos comuns ou pizza. */
  template: FoodMenuSectionTemplateDto;
  /** Última alteração (RFC 3339); `null` = nenhuma. */
  updated_at: string | null;
  /** As variantes, na ordem. */
  variant_ids: string[];
}

/** Corpo de `PUT.../menu/sections/{section_id}/items`. */
export interface FoodMenuSectionItemsBody {
  /**
   * As variantes do catálogo, na ordem em que o cliente vê (até 100).
   * Variante noutra seção da mesma loja é recusada (`409`).
   */
  variant_ids: string[];
}

/** Se a seção aparece para o cliente. */
export type FoodMenuSectionStatusDto = "active" | "paused";

/** O modelo da seção. */
export type FoodMenuSectionTemplateDto = "default" | "pizza";

/** Onde está o envio do cardápio da loja. */
export interface FoodMenuStateDto {
  /** Por que a última rodada falhou; vazio quando deu certo. */
  error: string;
  /** Pratos recusados na última tentativa. */
  items_failed: number;
  /** Pratos novos ou mudados por enviar. */
  items_pending: number;
  /** Pratos aceitos pelo provider com o conteúdo atual. */
  items_synced: number;
  /** Próxima rodada (RFC 3339); `null` = a loja não tem cardápio. */
  next_push_at: string | null;
  /** Última rodada que terminou sem erro. */
  pushed_at: string | null;
}

/** Um dia agregado no fluxo previsto. */
export interface ForecastDayDto {
  /** Data de vencimento (`YYYY-MM-DD`). */
  due_date: string;
  /** Σ AR vencendo no dia. */
  expected_in: DecimalText;
  /** Σ AP vencendo no dia. */
  expected_out: DecimalText;
  /**
   * Σ previsto das assinaturas de valor apurado cujo ciclo vence no dia e
   * ainda não virou título. Estimativa de quem apura, fora de `expected_in`.
   */
  expected_recurring_in: DecimalText;
  /** `expected_in + expected_recurring_in − expected_out`. */
  net: DecimalText;
}

/** Como se cobra a pizza de vários sabores (só no grupo `topping`). */
export type FractionPricingDto = "highest" | "average" | "proportional";

/** Detalhe completo de uma operação (operação + transações + lançamentos). */
export interface FullOperationDto {
  /** Os dados da operação: o fato financeiro que originou os lançamentos. */
  operation: FinancialOperationDto;
  /** As transações da operação, cada uma com as próprias pernas. */
  transactions: OperationTransactionDto[];
}

/**
 * Faturamento de uma venda.
 *
 * ⚠️ **Não há número de parcelas nem periodicidade**: a venda gera UM título, e
 * parcelar é função futura. Aceitar os campos e ignorá-los seria
 * pior que não tê-los - a tela pediria 3x, a API responderia `200` e o cliente
 * receberia um título do valor inteiro.
 */
export interface GenerateReceivablesBody {
  /**
   * Sacado do título quando **não** é o cliente do pedido: a venda de
   * marketplace é sacada contra a pessoa do marketplace no `iam`, porque
   * é ele quem deve o líquido ao tenant. Ausente = o cliente do pedido;
   * pedido sem cliente e sem sacado é recusado com `412`.
   */
  drawee_person_id?: string | null;
  /**
   * Chave de idempotência do título no `pay`. Ausente = `fz:sale-{id}`.
   * O marketplace manda `mkt:{provider}:{account_id}:{external_order_id}`,
   * a mesma referência que o repasse vai citar.
   */
  external_ref?: string | null;
  /**
   * Vencimento do título (`YYYY-MM-DD`). Ausente usa o prazo padrão da
   * configuração, contado de hoje.
   */
  first_due_date?: string | null;
  settlement_mode?: SalesSettlementMode | null;
}

/**
 * Corpo da geração combinatória de variantes.
 *
 * Gera o produto cartesiano dos eixos, menos as combinações excluídas. Existe
 * porque um catálogo de roupa com cinco cores e seis tamanhos são trinta SKUs, e
 * digitá-los à mão é onde nascem os duplicados.
 */
export interface GenerateVariantsBody {
  /** Os eixos a combinar (até 50). */
  axes: AxisSelectionBody[];
  /**
   * `true` devolve o que **seria** criado sem criar nada.
   *
   * É a defesa contra a geração acidental de centenas de SKUs: conferir antes é
   * barato, desfazer depois não é.
   */
  dry_run?: boolean;
  /**
   * Combinações que não devem nascer, cada uma descrita pelos pares atributo/valor
   * que a identificam. É o que cobre a cor que não sai naquele tamanho.
   */
  exclude?: AssignmentBody[][];
  /**
   * Molde do SKU gerado. Ausente, o serviço deriva um a partir do código do produto
   * e dos valores de eixo.
   */
  sku_pattern?: string | null;
}

/** Query de `GET /v1/checkout/checkouts/{id}`. */
export interface GetCheckoutQuery {
  /** Organização dona (vazio = escopo tenant). */
  organization_id?: string | null;
}

/** Resultado da consulta de Configuração financeira (resolução org→tenant). */
export interface GetFinancialSettingsDto {
  /** `true` se existe configuração no escopo consultado. */
  found: boolean;
  settings: FinancialSettingsDto | null;
}

/** Resultado da consulta de remetente (escopo pode não ter nenhum). */
export interface GetSenderConfigDto {
  config: SenderConfigDto | null;
  /** `true` se existe configuração no escopo (org ou tenant). */
  found: boolean;
}

/** Corpo de `POST /v1/auth/ghost/redeem`. */
export interface GhostRedeemBody {
  /** Ticket de uso único assinado pelo painel admin (`auth_core::verify_ghost_ticket`). */
  ticket: string;
}

/** Resposta de `POST /v1/auth/ghost/redeem`: a sessão fantasma nasceu. */
export interface GhostRedeemResponse {
  /** Prazo fixo da sessão, em segundos: ela não desliza. */
  expires_in: number;
  /** Tenant desse usuário, snowflake em texto decimal. */
  tenant_id: string;
  /** Token opaco da sessão. */
  token: string;
  /** Usuário em nome de quem o operador entrou, snowflake em texto decimal. */
  user_id: string;
}

/** Corpo de concessão de exceção (grant) a uma org ou pessoa. */
export interface GrantBody {
  /**
   * Organização (quando `subject_type=organization`). Tem de ser a da
   * requisição, senão 404 com `code = organization_not_allowed`.
   */
  organization_id?: string | null;
  /** `organization` | `person`. */
  subject_type: GrantSubjectInput;
  /**
   * Usuário (`user_id`, quando `subject_type=person`): quem faz login. O id
   * do cadastro de pessoas não serve: a concessão era gravada com
   * ele, o cofre comparava com o usuário da sessão e nada casava.
   */
  user_id?: string | null;
}

/** Concessão de exceção (grant) de um arquivo. */
export interface GrantDto {
  /** Snowflake do grant. */
  id: string;
  /** Organização (vazio se `subject_type=person`). */
  organization_id: string;
  /** Permissão concedida (`view`). */
  permission: ArchivePermission;
  /** `organization` | `person`. */
  subject_type: ArchiveGrantSubject;
  /** Usuário concedido (vazio se `subject_type=organization`). */
  user_id: string;
}

/**
 * Body de `POST /v1/roles/{role_id}/permissions`.
 *
 * Concede uma permissão RBAC+ABAC ao role. A combinação `(role_id, action)`
 * deve ser única - o backend rejeita duplicatas (ou substitui, dependendo da
 * implementação).
 */
export interface GrantPermissionBody {
  /**
   * Código da ação que esta permissão autoriza.
   *
   * Um código do catálogo `GET /v1/permissions` (ex.: `"member.read"`,
   * `"pay.contas-receber.titulo.read"`). Máximo 100 chars.
   * Este valor é usado como identificador na revogação (`DELETE.../permissions/{action}`).
   */
  action: string;
  /**
   * Condições ABAC opcionais como objeto JSON livre.
   *
   * Exemplos: `{"amount_limit": 10000}`, `{"allowed_hours": "08-18"}`.
   * Ausente ou `null` = sem condições (permissão incondicional).
   * Serializado para string JSON ao ser enviado ao backend.
   */
  conditions?: unknown;
  /**
   * Nível de escopo no qual a permissão se aplica.
   *
   * Um de três valores: `"own"` (só o que é do próprio membro), `"team"`
   * (a subárvore de unidades dele) ou `"all"` (toda a organização ativa). Outro valor
   * é 422.
   */
  scope: IamPermissionScope;
}

/** Sujeito de uma concessão de exceção. */
export type GrantSubjectInput = "organization" | "person";

/** Lista de grants (`{ items }`). */
export interface GrantsListDto {
  /** As concessões de exceção em vigor no arquivo. */
  items: GrantDto[];
}

/** Uma opção no corpo do grupo. */
export interface GroupOptionBody {
  /** Grupos que escolher esta opção abre ("Combo" abre "Escolha a bebida"). */
  child_group_ids?: string[];
  /** Preço por escolha de outra opção. */
  conditional_prices?: ConditionalPriceDto[];
  /** Descrição (até 500 caracteres). */
  description?: string | null;
  /**
   * Id da opção que já existe neste grupo; ausente = opção nova. Opção do
   * grupo que não vier no corpo é arquivada.
   */
  id?: string | null;
  /** Desligada, some do cardápio sem apagar o cadastro. */
  is_available?: boolean;
  /** Quantas vezes a mesma opção cabe numa escolha (1 a 100). */
  max_quantity?: number;
  /** O que o cliente lê (até 100 caracteres). */
  name: string;
  /** Acréscimo sobre o item, decimal em texto. Zero é legítimo. */
  price: string;
  /**
   * A opção que é SKU (o refrigerante do combo): baixa estoque e vai na
   * nota como item próprio.
   */
  variant_id?: string | null;
}

/** Uma opção gravada. */
