/** Estado do chamado: só documenta os valores, o fio é texto. */
export type HelpdeskTicketStatus = "open" | "pending" | "resolved" | "closed";

/**
 * Body do re-disparo. `idempotency_key` (Snowflake do cliente) torna o pedido
 * idempotente: repetir com a mesma chave NÃO re-dispara.
 */
export interface HookDeliveryReplayBody {
  /**
   * Snowflake gerado pelo cliente. Repetir a mesma chave **não** re-dispara: é o que
   * impede que um clique duplo na tela mande o mesmo evento duas vezes ao sistema do
   * cliente.
   */
  idempotency_key: string;
}

/**
 * Header secreto que o destino manda em toda chamada (credencial do sistema
 * de quem recebe). Só entra: nenhuma leitura devolve o valor.
 */
export interface HookDestinationHeaderBody {
  /** Nome do header, como vai no fio (ex.: `Authorization`). */
  name: string;
  /** Valor (segredo). Cifrado em repouso. */
  value: string;
}

/** Uma chave pública Ed25519 no formato JWK/OKP (RFC 8037). */
export interface HookJwk {
  /** Algoritmo: sempre `EdDSA`. */
  alg: string;
  /** Curva: sempre `Ed25519`. */
  crv: string;
  /** Papel na janela: `future`, `current` ou `previous`. Apenas informativo. */
  fz_role: HooksSigningKeyRole;
  /**
   * Identificador da chave. É o valor do header `X-Ferrazio-Key-Id` das entregas
   * que ela assina: case a chave por ele.
   */
  kid: string;
  /** Tipo da chave: sempre `OKP`. */
  kty: string;
  /** Uso: sempre `sig`. */
  use: string;
  /** Chave pública (32 bytes) em base64url sem padding. */
  x: string;
}

/** JSON Web Key Set com as chaves públicas de assinatura dos webhooks. */
export interface HookJwks {
  /** Até três chaves, da mais nova para a mais velha. */
  keys: HookJwk[];
}

/** Body de criação. */
export interface HookSubscriptionCreateBody {
  /** Headers secretos que o destino manda em toda chamada (opcional). */
  headers?: HookDestinationHeaderBody[];
  /** Nome do destino, como aparece na lista do desenho do fluxo. */
  name: string;
  /** Escopo org (opcional; vazio = tenant-wide). */
  organization_id?: string | null;
  /** Endpoint HTTPS de destino. */
  url: string;
}

/**
 * Um destino de webhook do tenant.
 *
 * O nome do schema no `openapi.json` é `HookSubscriptionDto`, e não
 * `SubscriptionDto`: o `pay` tem o próprio `SubscriptionDto` (assinatura de
 * recorrência, outro domínio e outra forma). Nomes iguais colidem em
 * `components/schemas` e o último registrado sobrescreve o primeiro em
 * silêncio: a rota de recorrência chegou a apontar para ESTA forma, com `url`
 * obrigatório, num corpo que nunca o teve.
 */
export interface HookSubscriptionDto {
  /** RFC3339. */
  created_at: string;
  /** Ativo/pausado. */
  enabled: boolean;
  /** Nomes dos headers secretos gravados no destino. Os valores nunca saem. */
  header_names: string[];
  /** Nome do destino, como aparece na lista do desenho do fluxo. */
  name: string;
  /** Escopo org (vazio = tenant-wide). */
  organization_id: string;
  /** Snowflake (string). */
  subscription_id: string;
  /** RFC3339. */
  updated_at: string;
  /** Endpoint HTTPS de destino. */
  url: string;
}

/** Body de atualização parcial (campos ausentes não alteram). */
export interface HookSubscriptionUpdateBody {
  /** Pausar/reativar (opcional). */
  enabled?: boolean | null;
  /**
   * Nova lista de headers secretos, que SUBSTITUI a anterior inteira
   * (`[]` remove todos). Ausente = os gravados ficam como estão.
   */
  headers?: HookDestinationHeaderBody[] | null;
  /** Novo nome (opcional). */
  name?: string | null;
  /** Novo endpoint (opcional). */
  url?: string | null;
}

/**
 * Lista paginada.
 *
 * Renomeada no schema pelo mesmo motivo de `SubscriptionDto`.
 */
export interface HookSubscriptionsListDto {
  /** As assinaturas desta página. */
  items: HookSubscriptionDto[];
  /** Cursor da próxima página (vazio = fim). */
  next_page_token: string;
}

/** Desfecho de uma tentativa de entrega: só documenta os valores, o fio é texto. */
export type HooksAttemptOutcome = "succeeded" | "retry_scheduled" | "failed";

/**
 * Método HTTP da chamada de uma entrega: só documenta os valores,
 * o fio é texto. `GET` só no bloco "Chamar API" do Flow.
 */
export type HooksDeliveryMethod = "GET" | "POST" | "PUT" | "PATCH" | "DELETE";

/** Situação de uma entrega de webhook: só documenta os valores, o fio é texto. */
export type HooksDeliveryStatus = "pending" | "delivering" | "succeeded" | "failed";

/** Papel de uma chave na janela de assinatura: só documenta os valores, o fio é texto. */
export type HooksSigningKeyRole = "future" | "current" | "previous";

