/** Uma ação do PDI. */
export interface HrDevelopmentAction {
  /** Competência do catálogo (`GET /v1/hr/competencies`). `null` = nenhuma. */
  competency_id: string | null;
  /** Criação (RFC 3339). */
  created_at: string;
  /** Membro que pôs a ação no plano. */
  created_by_member_id: string;
  /** Conclusão (RFC 3339). `null` = não concluída. */
  done_at: string | null;
  /** Prazo (`AAAA-MM-DD`), dentro do período do plano. */
  due_date: string;
  /** Meta da mesma pessoa a que a ação serve. `null` = nenhuma. */
  goal_id: string | null;
  /** Id (Snowflake). */
  id: string;
  /** `course`, `reading`, `mentoring`, `project`, `practice` ou `other`. */
  kind: HrDevelopmentActionKind;
  /** Nota da última mudança de situação. */
  note: string;
  /** O plano. */
  plan_id: string;
  /** A competência que a ação desenvolve. Vazio = não informada. */
  skill: string;
  /** `planned`, `in_progress`, `done` ou `cancelled`. */
  status: HrDevelopmentActionStatus;
  /** Título. */
  title: string;
  /** Versão para a edição concorrente. */
  version: number;
}

/** Uma ação (criação ou edição). A edição manda o registro inteiro. */
export interface HrDevelopmentActionInput {
  /** Competência do catálogo, ativa. Vazio = nenhuma. */
  competency_id?: string;
  /** Prazo (`AAAA-MM-DD`), dentro do período do plano. */
  due_date: string;
  /** Meta da mesma pessoa. Vazio = nenhuma. */
  goal_id?: string;
  /**
   * `course`, `reading`, `mentoring`, `project`, `practice` ou `other`
   * (padrão).
   */
  kind?: HrDevelopmentActionKind;
  /** A competência que a ação desenvolve (até 120 caracteres). */
  skill?: string;
  /** Título. */
  title: string;
  /** Na edição, a versão lida da ação (velha = `409`). Ignorada na criação. */
  version?: number;
}

/** Tipo de ação do PDI: só documenta os valores, o fio é texto. */
export type HrDevelopmentActionKind = "course" | "reading" | "mentoring" | "project" | "practice" | "other";

/** Situação da ação do PDI: só documenta os valores, o fio é texto. */
export type HrDevelopmentActionStatus = "planned" | "in_progress" | "done" | "cancelled";

/** A mudança de situação de uma ação. */
export interface HrDevelopmentActionStatusInput {
  /** Nota (até 1000 caracteres): o que foi feito, por que parou. */
  note?: string;
  /** `planned`, `in_progress`, `done` ou `cancelled`. */
  status: HrDevelopmentActionStatus;
  /** A versão lida da ação. Velha = `409`. */
  version: number;
}

/** Um PDI. */
export interface HrDevelopmentPlan {
  /** As ações, por prazo. Vazio na lista; só o detalhe traz. */
  actions: HrDevelopmentAction[];
  /** Ações concluídas. */
  actions_done: number;
  /** Ações não canceladas. */
  actions_total: number;
  /** Nota do encerramento. */
  close_note: string;
  /** Encerramento (RFC 3339). `null` = ativo. */
  closed_at: string | null;
  /** Criação (RFC 3339). */
  created_at: string;
  /** Membro que abriu o plano. */
  created_by_member_id: string;
  /** Vínculo do dono. */
  employment_id: string;
  /** Fim (`AAAA-MM-DD`), até 2 anos depois do início. */
  end_date: string;
  /** Id (Snowflake). */
  id: string;
  /** Aonde a pessoa quer chegar. */
  objective: string;
  /** Nome do dono. */
  owner_name: string;
  /** Progresso de 0 a 100: concluídas sobre as não canceladas. */
  progress: number;
  /** `true` quando o dono abriu o plano para si. */
  self_assigned: boolean;
  /** Início (`AAAA-MM-DD`). */
  start_date: string;
  /** `active`, `completed` ou `cancelled`. */
  status: HrDevelopmentPlanStatus;
  /** Título. */
  title: string;
  /** Versão para a edição concorrente. */
  version: number;
}

/** O encerramento de um plano. */
export interface HrDevelopmentPlanCloseInput {
  /** Nota (até 1000 caracteres). */
  note?: string;
  /** `completed` ou `cancelled`. */
  outcome: HrDevelopmentPlanOutcome;
  /** A versão lida. Velha = `409`. */
  version: number;
}

/** Um plano (criação ou edição). A edição manda o registro inteiro. */
export interface HrDevelopmentPlanInput {
  /**
   * O dono. Obrigatório em `/v1/hr/development-plans`; ignorado no portal
   * e na edição.
   */
  employment_id?: string;
  /** Fim (`AAAA-MM-DD`), até 2 anos depois do início. */
  end_date: string;
  /** Aonde a pessoa quer chegar (até 2000 caracteres). */
  objective?: string;
  /** Início (`AAAA-MM-DD`). Vazio = hoje na criação, o mesmo na edição. */
  start_date?: string;
  /** Título. */
  title: string;
  /** Na edição, a versão lida (velha = `409`). Ignorada na criação. */
  version?: number;
}

/** Como o PDI fecha: só documenta os valores, o fio é texto. */
export type HrDevelopmentPlanOutcome = "completed" | "cancelled";

/** Situação do PDI: só documenta os valores, o fio é texto. */
export type HrDevelopmentPlanStatus = "active" | "completed" | "cancelled";

/** Página de planos. */
export interface HrDevelopmentPlansPage {
  /** Os planos, do mais novo ao mais velho, sem as ações. */
  items: HrDevelopmentPlan[];
  /** Cursor da próxima página; vazio na última. */
  next_page_token: string;
}

