  /** Nome de quem ativou. Vazio quando a trilha não identifica quem fez. */
  activated_by_name: string;
  /** RFC 3339. `null` = segue ativa. */
  deactivated_at: string | null;
  /** Quem desativou. Vazio enquanto ativa ou quando a trilha não identifica. */
  deactivated_by: string;
  /**
   * Nome de quem desativou. Vazio enquanto ativa ou quando a trilha não
   * identifica.
   */
  deactivated_by_name: string;
  /** Id da ativação. */
  id: string;
  /** `users` | `members` | `marketing_members`. */
  metric: string;
  /** Vazio na licença de usuário (é do tenant). */
