  /**
   * Decididos por pessoa no escopo que a rodada deixa como estão sem
   * `include_manual`.
   */
  manual: number;
  /** `false` enquanto o preço não existe: a rodada é recusada (412). */
  price_defined: boolean;
  /** Preço de 1.000 tokens em reais, decimal em texto (vazio sem preço). */
  price_per_1k: DecimalTextOrEmpty;
  /** Tokens estimados. */
