export interface PayablesListDto {
  /** Títulos. */
  items: AccountsPayableDto[];
  /** Cursor opaco da próxima página (vazio = última página). */
  next_page_token: string;
}

/**
 * O cadastro que o pagador **digita** na cesta aberta.
 *
 * ⚠️ Isto é dado do pagador sobre ELE MESMO, e é a única exceção ao princípio
 * de que nada vindo do caller anônimo decide coisa alguma. Ele não escolhe
 * valor, moeda, carteira nem destino: escolhe quem ele é, para o instrumento
 * sair no nome certo.
 *
 * ⚠️ Numa cesta **nominal** é ignorado pelo serviço, e a razão é a invariante
 * `CH7` da ("cria, NUNCA atualiza"): aceitar cadastro de quem só tem
 * o token, numa cesta que já tem dono, deixaria qualquer um com o link
 * reescrever cadastro alheio.
 */
export interface PayerRegistrationBody {
  /** Cidade. */
  city?: string;
  /** Complemento. */
  complement?: string;
  /** País ISO 3166-1 (vazio = BRA). */
  country?: string;
  /**
   * CPF/CNPJ (pontuação é aceita e descartada).
   *
   * ⚠️ Vazio é aceito aqui pelo motivo do `name`. E há um caso em que
   * **precisa** ser: a ficha montável do lojista não é obrigada a pedir
   * documento, e uma cesta nominal ignora o cadastro digitado inteiro
   * (`CH7`). Exigir documento no corpo recusaria, no schema, uma cobrança
   * que o serviço emitiria sem ele.
   */
  document?: string;
  /**
   * E-mail: é por onde o instrumento chega.
   *
   * ⚠️ Vazio é aceito aqui pelo motivo do `name`. Quem exige e-mail é o
   * método: o boleto exige, e `missing_for` diz isso nomeando `email`.
   */
  email?: string;
  /**
   * Nome como consta no documento.
   *
   * ⚠️ **Vazio é aceito AQUI, e a exigência é do serviço.** Ela existe: sem
   * nome não sai cobrança nenhuma. Mas quem cobra é `missing_for`, que
   * recusa com `payer_data_missing` e **nomeia** o campo em `details`. Uma
   * segunda exigência neste struct devolveria
   * `{"error":"payer.name: length is lower than 1"}`, sem `code` e sem
   * `details`: a página não teria como traduzir a frase nem em que caixa
   * pousar o foco, e a pessoa leria "não deu" sem saber o que digitar.
   * Mesmo raciocínio do corpo do `lead`, que já nasceu assim.
   */
  name?: string;
  /** Bairro. */
  neighborhood?: string;
  /** Número. */
  number?: string;
  /** Código do país do telefone (ex.: `+55`). */
  phone_country_code?: string;
  /** Telefone (pontuação é aceita e descartada). */
  phone_number?: string;
  /** UF. */
  state?: string;
  /** Logradouro. Exigido pelo boleto registrado. */
  street?: string;
  /** CEP (pontuação é aceita e descartada). */
  zip_code?: string;
}

/** Condição de pagamento (DTO de resposta). */
export interface PaymentConditionDto {
  /** `true` se a condição está ativa. */
  active: boolean;
  /** Criação (RFC3339). */
  created_at: string;
  /** Snowflake. */
  id: string;
  /** Parcelas (`d+N` × % do total). */
  installments: PaymentConditionInstallmentDto[];
  /** Nome da condição (ex.: `"30/60/90"`). */
  name: string;
  /** Observação (vazio = sem). */
  note: string;
  /** Organização dona (vazio = escopo tenant). */
  organization_id: string;
  /** Última atualização (`null` = nunca). */
  updated_at: string | null;
}

/** Parcela de uma Condição de pagamento (item do corpo de criação). */
export interface PaymentConditionInstallmentBody {
  /** Offset em dias a partir da emissão (`d+N`). */
  day_offset: number;
  /** Percentual do total (decimal string, ex.: `"33.33"`). */
  percent: string;
}

/** Parcela de uma Condição de pagamento (DTO de resposta). */
export interface PaymentConditionInstallmentDto {
  /** Offset em dias a partir da emissão (`d+N`). */
  day_offset: number;
  /** Percentual do total (decimal string); a soma das parcelas é 100. */
  percent: DecimalText;
}

/** Lista paginada de Condições de pagamento. */
export interface PaymentConditionsListDto {
  /** Condições de pagamento da página atual. */
  items: PaymentConditionDto[];
  /** Cursor opaco da próxima página (vazio = última página). */
  next_page_token: string;
}

/** O link como o **lojista** o vê. */
export interface PaymentLinkDto {
  /** Título que este link cobra. */
  accounts_receivable_id: string;
  /** Métodos oferecidos ao pagador. */
  allowed_methods: PayAcquiringMethod[];
  /** Criação (RFC3339). */
  created_at: string;
  /** Prazo próprio do link (RFC3339; `null` = sem prazo próprio). */
  expires_at: string | null;
  /** Snowflake do link. */
  id: string;
  /**
   * Teto de parcelas do cartão neste link (ausente = só a política do
   * lojista manda).
   */
  max_installments?: number | null;
  /** Organização dona (vazio = escopo tenant). */
  organization_id: string;
  /** Nome de quem cobra, congelado na criação (vazio = não resolvido). */
  payee_display_name: string;
  /** Instante da revogação (RFC3339; `null` = no ar). */
  revoked_at: string | null;
  /**
   * Token opaco publicado ao pagador.
   *
   * Sai aqui porque quem cria o link precisa montar a URL para enviar. É a
   * única resposta da API que o devolve: nenhuma leitura posterior o repete.
   */
  token: string;
}

/** O que o cliente manda para escolher como paga as faturas. */
export interface PaymentMethodBody {
  /**
   * Token de uso único do cartão, criado no navegador com a chave de
   * `GET /v1/billing/card-key`. Obrigatório em `card`, recusado em `pix`.
   */
  card_token?: string | null;
  /** `pix` (um Pix por fatura) ou `card` (débito automático). */
  method: BillingInstantMethod;
  payer?: PurchasePayerBody | null;
}

/** Resposta da troca de meio de pagamento. */
export interface PaymentMethodResponseDto {
  /** A conta depois da troca. */
  account: BillingAccountDto;
  /**
   * Segredo do desafio 3-D Secure, quando o emissor exigiu. Com ele
   * presente a conta **não** mudou: conclua o desafio e repita o pedido.
   */
  card_authentication?: string;
}

/** Saque consolidado. */
export interface PayoutDto {
  /** Valor pedido (decimal string). */
  amount: DecimalText;
  /** RFC3339. */
  created_at: string;
  /** Moeda ISO-4217. */
  currency: string;
  /** Conta (Snowflake decimal). */
  financial_account_id: string;
  /** Saque (Snowflake decimal). */
  id: string;
  /** Chave de idempotência do pedido. */
  idempotency_key: string;
  /** Uma perna por adquirente. */
  legs: PayoutLegDto[];
  /** Adquirente fixado. */
  pinned_provider_id: string | null;
  /** Quem pediu (user id). */
  requested_by: string | null;
  /** `processing`, `completed`, `partially_failed` ou `failed`. */
  status: PayPayoutStatus;
}

/** Uma perna do saque. */
export interface PayoutLegDto {
  /** Valor (decimal string). */
  amount: DecimalText;
  /** Id no adquirente. */
  external_id: string | null;
  /** Estado cru no adquirente. */
  external_status: string | null;
  fee: DecimalText | null;
  /** Perna (Snowflake decimal). */
  id: string;
  /** Código do adquirente. */
  provider_code: string;
  /** Adquirente (Snowflake decimal). */
  provider_id: string;
  /** Nome do adquirente. */
  provider_name: string;
  /** `connected_account`, `platform_account` ou `pooled`. */
  route: PayPayoutRoute;
  /**
   * `reserved`, `submitted`, `awaiting_transfer`, `paid`, `failed`,
   * `stuck` ou `canceled`.
   */
  status: PayPayoutLegStatus;
  /** Referência do repasse do bolsão. */
  transfer_reference: string | null;
  /** RFC3339. */
  updated_at: string;
  /** Carteira (Snowflake decimal). */
  wallet_id: string;
}

/** Página de saques. */
export interface PayoutPageDto {
  /** Mais novos primeiro. */
  items: PayoutDto[];
  /** Token da próxima página (vazio = fim). */
  next_page_token: string;
}

/** Cotação do saque. */
export interface PayoutQuoteDto {
  /** Soma do que pode sair agora (decimal string). */
  available: DecimalText;
  /** O plano para o valor pedido (vazio quando não cabe ou sem valor). */
  legs: PlannedPayoutLegDto[];
  refusal: PayPayoutRefusal | null;
  /** As carteiras da conta na moeda. */
  sources: PayoutSourceDto[];
}

/** Uma carteira da conta, sacável ou com o motivo. */
export interface PayoutSourceDto {
  /** Saldo da carteira (decimal string). */
  balance: DecimalText;
  /** Por que não saca, quando não saca. */
  blocked_reason: string | null;
  /** Código do adquirente. */
  provider_code: string;
  /** Adquirente (Snowflake decimal). */
  provider_id: string;
  /** Nome do adquirente. */
  provider_name: string;
  route: PayPayoutRoute | null;
  /** Carteira (Snowflake decimal). */
  wallet_id: string;
}

/** Servidor que o suporte preparou e ainda não entrou. */
export interface PendingRunnerDto {
  /** Os agentes que ele recebe ao entrar. */
  agents: RunnerAgentDto[];
  /** Quando o suporte preparou (RFC 3339, UTC). */
  created_at: string;
  /** Validade do convite (RFC 3339, UTC): depois disso o suporte gera outro. */
  expires_at: string;
  /** Nome que o servidor terá. */
  name: string;
}

/**
 * Body de `PUT /v1/persons/{id}/additional-data`.
 *
 * Os dados adicionais são um objeto JSON livre que quem opera o cadastro
 * preenche (o id da pessoa no sistema do cliente, o plano, a turma). A
 * plataforma não interpreta o conteúdo: ela o guarda, o devolve, e o Flow o
 * entrega junto com os fatos que nomeiam a pessoa (`subject.additional_data` e
 * `actor.additional_data` na condição, no template e no webhook).
 */
export interface PersonAdditionalDataBody {
  /**
   * O objeto inteiro. A gravação SUBSTITUI o anterior; `{}` limpa tudo.
   *
   * Limites (conferidos pelo `iam`): 16 KiB serializado, seis níveis de
   * aninhamento, 100 chaves na raiz e chaves de 1 a 64 caracteres.
   */
  additional_data: Record<string, unknown>;
}

/** Dados adicionais (campos livres) de uma pessoa. */
export interface PersonAdditionalDataDto {
  /** Objeto livre com os dados adicionais; vazio quando nada foi preenchido. */
  additional_data: Record<string, unknown>;
}

/** Endereços da pessoa. */
export interface PersonAddressListDto {
  /** Endereços da pessoa. */
  addresses: PersonAddressRecordDto[];
}

/** ── Endereços ── */
export interface PersonAddressRecordDto {
  /**
   * Tipo de endereço.
   *
   * Valores: `residential`, `commercial`, `billing`, `delivery`, `other`, `unspecified`.
   */
  address_type: IamAddressTypeOrUnspecified;
  /** Cidade. */
  city: string;
  /** Complemento (opcional). */
  complement: string;
  /** País (ISO 3166-1 alpha-2). */
  country: string;
  /** Snowflake do endereço (decimal string). */
  id: string;
  /** Endereço principal da pessoa para este tipo. */
  is_main: boolean;
  /** Bairro. */
  neighborhood: string;
  /** Número. */
  number: string;
  /** Snowflake da pessoa (decimal string). Tabela-filha sem tenant_id próprio. */
  person_id: string;
  /** CEP (sem formatação). */
  postal_code: string;
  /** Estado (sigla UF). */
  state: string;
  /** Logradouro. */
  street: string;
}

/** Apelidos de uma pessoa: os cadastros fundidos nela. */
export interface PersonAliasesDto {
  /** Os cadastros fundidos nesta pessoa. */
  aliases: PersonSummaryDto[];
  /**
   * A pessoa que respondeu (a sobrevivente, quando se pergunta por um id já
   * fundido).
   */
  person_id: string;
}

/** Uma conta bancária como o cliente a vê. */
export interface PersonBankAccount {
  /** Só os dois últimos dígitos e o dígito: `******78-9`. */
  account_number_masked: string;
  /** `checking` ou `savings`. */
  account_type: IamBankAccountType;
  /** Código COMPE do banco. */
  bank_code: string;
  /** Agência. */
  branch_number: string;
  /** RFC 3339. */
  created_at: string;
  /** Nome do titular. */
  holder_name: string;
  /** Snowflake da conta. */
  id: string;
  /** A conta de liquidação da pessoa. */
  is_default: boolean;
  /** Snowflake da pessoa. */
  person_id: string;
}

/**
 * Body de `POST /v1/persons/{person_id}/bank-accounts`. O documento do
 * titular não vem no corpo: é sempre o CPF ou CNPJ do cadastro da pessoa.
 */
export interface PersonBankAccountAddBody {
  /** Dígito da conta (1 ou 2, `0-9` ou `X`). */
  account_check_digit: string;
  /** Número da conta, sem dígito (1 a 13 dígitos). */
  account_number: string;
  /** `checking` ou `savings`. */
  account_type: IamBankAccountType;
  /** Código COMPE do banco, três dígitos (`001`). */
  bank_code: string;
  /** Dígito da agência, quando o banco usa (`0-9` ou `X`). */
  branch_check_digit?: string | null;
  /** Agência, sem dígito (1 a 5 dígitos). */
  branch_number: string;
  /** Nome do titular; ausente usa o nome do cadastro. */
  holder_name?: string | null;
  /** Torna esta a conta de liquidação. A primeira conta já nasce padrão. */
  is_default?: boolean;
}

/** As contas bancárias da pessoa, a padrão primeiro. */
export interface PersonBankAccountList {
  /** Contas ativas. */
  items: PersonBankAccount[];
}

/**
 * Body de `POST /v1/persons`.
 *
 * Cria uma nova pessoa (física ou jurídica) no domínio de cadastro.
 * O `tenant_id` e o `organization_id` vêm da sessão - não são aceitos aqui.
 */
export interface PersonCreateBody {
  /**
   * Nome de exibição público da pessoa.
   *
   * Para PF: nome completo ou apelido (ex.: `"João da Silva"`).
   * Para PJ: razão social curta ou nome fantasia (ex.: `"Acme Ltda"`).
   * Mínimo 1 caractere; máximo 255.
   */
  display_name: string;
  /**
   * Documento da pessoa (CPF/CNPJ/estrangeiro). Opcional; reservado para
   * fins fiscais futuros. Formato livre; máximo 63 caracteres.
   */
  document?: string | null;
  /**
   * Discriminador do tipo de pessoa.
   *
   * Valores aceitos: `"individual"` (pessoa física) ou `"legal"` (pessoa jurídica).
   * Qualquer outro valor retorna `422` no envelope.
   */
  person_type: IamPersonType;
}

/** Cadastro completo de uma pessoa: o resumo, os contatos e os detalhes PF ou PJ. */
export interface PersonDetailsDto {
  /** Endereços. */
  addresses: PersonAddressRecordDto[];
  /** E-mails. */
  emails: PersonEmailRecordDto[];
  individual_details: PersonIndividualDetailsDto | null;
  legal_details: PersonLegalDetailsDto | null;
  /** A pessoa. */
  person: PersonSummaryDto;
  /** Telefones. */
  phones: PersonPhoneRecordDto[];
  /** Chaves Pix. */
  pix_keys: PersonPixKeyRecordDto[];
}

/** Grupo de pessoas suspeitas de serem a mesma. */
export interface PersonDuplicateGroupDto {
  /**
   * Critério que juntou estas pessoas.
   *
   * Valores: `document`, `email`, `unspecified`.
   */
  match_kind: IamDuplicateMatchKind;
  /** O valor que casou, normalizado (dígitos do documento, ou e-mail minúsculo). */
  match_value: string;
  /**
   * As pessoas do grupo, da mais antiga para a mais nova. A mais antiga é a
   * sugestão natural de sobrevivente, nunca uma imposição.
   */
  persons: PersonSummaryDto[];
}

/** Página de grupos suspeitos de duplicata. */
export interface PersonDuplicateGroupPageDto {
  /** Os grupos desta página. */
  groups: PersonDuplicateGroupDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** E-mails da pessoa. */
export interface PersonEmailListDto {
  /** E-mails da pessoa. */
  emails: PersonEmailRecordDto[];
}

/** ── Emails ── */
export interface PersonEmailRecordDto {
  /** Endereço de email. */
  email_address: string;
  /** Snowflake do email (decimal string). */
  id: string;
  /** Email principal da pessoa. */
  is_main: boolean;
  /** Email verificado. */
  is_verified: boolean;
  /** Snowflake da pessoa (decimal string). Tabela-filha sem tenant_id próprio. */
  person_id: string;
}

/**
 * Body de `PUT /v1/persons/{id}/individual-details`.
 *
 * Detalha uma pessoa física (nascimento, estado civil, PEP, gênero).
 * Operação upsert: cria os detalhes se não existirem; atualiza se já existirem.
 * O `person_id` é extraído da URL - não deve aparecer no corpo.
 */
export interface PersonIndividualBody {
  /**
   * Data de nascimento no formato ISO 8601 (`YYYY-MM-DD`, ex.: `"1990-06-15"`).
   * Campo obrigatório. Data que não parseia dá 422.
   */
  birth_date: string;
  /**
   * Identidade de gênero autodeclarada (texto livre).
   *
   * Distinto de `sex`: reflete a identidade social, não o registro oficial.
   * Opcional. Máximo 100 chars.
   */
  gender?: string | null;
  /**
   * Indica se a pessoa é Politicamente Exposta (PEP), conforme legislação
   * de compliance financeiro (BACEN/COAF). Obrigatório para KYC completo.
   */
  is_pep?: boolean;
  marital_status?: IamMaritalStatus | null;
  /**
   * Descrição do vínculo com cargo político que justifica o status PEP.
   *
   * Opcional. Relevante apenas quando `is_pep = true`. Máximo 500 chars.
   */
  pep_description?: string | null;
  /**
   * Sexo biológico da pessoa para fins de documentação oficial.
   *
   * Valores esperados: `"male"` ou `"female"`. Opcional. Máximo 10 chars.
   */
  sex?: string | null;
  /**
   * Nome social da pessoa (nome pelo qual é reconhecida socialmente).
   *
   * Opcional. Quando ausente ou `null`, o backend preserva o valor anterior
   * (no upsert) ou armazena string vazia (na criação inicial).
   */
  social_name?: string | null;
}

/** ── Detalhes PF ── */
export interface PersonIndividualDetailsDto {
  /** Data de nascimento (ISO 8601: YYYY-MM-DD); `null` quando não informada. */
  birth_date: string | null;
  /** Identidade de gênero (texto livre, opcional). */
  gender: string;
  /** Pessoa Politicamente Exposta. */
  is_pep: boolean;
  /**
   * Estado civil.
   *
   * Valores: `unspecified`, `single`, `married`, `divorced`, `widowed`, `stable_union`.
   */
  marital_status: IamMaritalStatusOrUnspecified;
  /** Descrição do vínculo PEP, se is_pep=true. */
  pep_description: string;
  /** Snowflake da pessoa (decimal string). Tabela-filha sem tenant_id próprio. */
  person_id: string;
  /** Sexo biológico: "male" | "female" | "" (não informado). */
  sex: string;
  /** Nome social (opcional). */
  social_name: string;
}

/**
 * Body de `PUT /v1/persons/{id}/legal-details`.
 *
 * Detalha uma pessoa jurídica (razão social, tipo societário, representante).
 * Operação upsert: cria os detalhes se não existirem; atualiza se já existirem.
 * O `person_id` é extraído da URL - não deve aparecer no corpo.
 */
export interface PersonLegalBody {
  company_type?: IamCompanyType | null;
  /**
   * Data de fundação/registro no formato ISO 8601 (`YYYY-MM-DD`). Opcional.
   * Data que não parseia dá 422.
   */
  founding_date?: string | null;
  /**
   * Razão social oficial da empresa (ex.: `"Acme Comércio e Serviços Ltda"`).
   * Campo obrigatório. Máximo 255 chars.
   */
  legal_name: string;
  /**
   * ID Snowflake (decimal string) da `Person` que atua como representante
   * legal da empresa. Deve ser uma `Person` do tipo `"individual"` já
   * cadastrada no mesmo tenant. Opcional. Máximo 32 chars.
   */
  legal_representative_id?: string | null;
  /**
   * Capital social em centavos (ex.: `10000000` para R$ 100.000,00).
   * Opcional; ausente apaga o valor gravado, como os demais campos.
   */
  share_capital_cents?: number | null;
  /** Nome fantasia ou nome comercial (ex.: `"Acme Store"`). Opcional. */
  trade_name?: string | null;
}

/** ── Detalhes PJ ── */
export interface PersonLegalDetailsDto {
  /**
   * Tipo de empresa.
   *
   * Valores: `unspecified`, `mei`, `me`, `epp`, `eireli`, `ltda`, `sa`, `other`.
   */
  company_type: IamCompanyTypeOrUnspecified;
  /** Data de fundação (ISO 8601: YYYY-MM-DD); `null` quando não informada. */
  founding_date: string | null;
  /** Razão social. */
  legal_name: string;
  /** Snowflake do representante legal (decimal string, opcional). */
  legal_representative_id: string;
  /** Snowflake da pessoa (decimal string). Tabela-filha sem tenant_id próprio. */
  person_id: string;
  /** Capital social em centavos; `null` quando não informado. */
  share_capital_cents: number | null;
  /** Nome fantasia (opcional). */
  trade_name: string;
}

/** Um vínculo como a tela o vê, com o nome das duas pessoas. */
export interface PersonLink {
  /** Nome da empresa no cadastro. */
  company_name: string;
  /** A empresa (pessoa jurídica do cadastro). */
  company_person_id: string;
  /** Quando o vínculo foi gravado. */
  created_at: string;
  /** Só quando `role` é `custom`. */
  custom_role_id: string | null;
  /** Nome do papel criado pelo tenant, só quando `role` é `custom`. */
  custom_role_name: string | null;
  /** ID do vínculo. */
  id: string;
  /** Nome do membro no cadastro. */
  member_name: string;
  /** O membro (pessoa física ou jurídica do cadastro). */
  member_person_id: string;
  /** `individual` ou `legal`. */
  member_type: string;
  /** Observação livre, ausente quando vazia. */
  note: string | null;
  /** Papel do membro na empresa. */
  role: PersonLinkRoleKind;
  /** Participação no capital em pontos-base (10000 = 100%), ausente quando não se aplica. */
  share_basis_points: number | null;
  /** Início do vínculo (`YYYY-MM-DD`), ausente quando não informado. */
  since: string | null;
  /** Fim do vínculo (`YYYY-MM-DD`), ausente enquanto vigente. */
  until: string | null;
}

/** Body de `POST /v1/persons/links`. */
export interface PersonLinkAddBody {
  /** A empresa (sempre pessoa jurídica). */
  company_person_id: string;
  /** Obrigatório quando `role` é `custom`, e só então. */
  custom_role_id?: string | null;
  /** O membro (pessoa física ou jurídica). */
  member_person_id: string;
  /** Observação livre, até 500 caracteres. */
  note?: string | null;
  /** Papel do membro na empresa; `custom` usa um papel criado pelo tenant. */
  role: PersonLinkRoleKind;
  /** Participação no capital em pontos-base (10000 = 100%). */
  share_basis_points?: number | null;
  /** `YYYY-MM-DD`. */
  since?: string | null;
  /** `YYYY-MM-DD`. */
  until?: string | null;
}

/** Vínculos em que a pessoa é a empresa ou o membro. */
