/**
 * `icms_json` do perfil: o objeto, ou o mesmo objeto como texto JSON (forma
 * antiga, ainda aceita).
 */
export type ProfileIcmsGroup = ProfileIcmsTemplate | string;

/** ICMS do perfil: tratamento e alíquota, sem valor (a base é da linha). */
export type ProfileIcmsTemplate = {
  /** CSOSN. */
  csosn: number;
  /** Origem da mercadoria. */
  origin: number;
  type: "simples_nacional";
} | {
  fcp_rate?: DecimalText | null;
  /** Origem da mercadoria. */
  origin: number;
  rate?: DecimalText | null;
  type: "fully_taxed";
} | {
  /** CST. */
  cst: number;
  /** Origem da mercadoria. */
  origin: number;
  type: "not_taxed";
} | {
  /** MVA original por UF de destino (`{"SP": "40.00"}`). */
  mva: Record<string, DecimalText>;
  /** Origem da mercadoria. */
  origin: number;
  type: "substitution";
} | {
  /** Origem da mercadoria. */
  origin: number;
  type: "substitution_charged";
};

/**
 * `ipi_json` do perfil: o objeto, ou o mesmo objeto como texto JSON (forma
 * antiga, ainda aceita).
 */
export type ProfileIpiGroup = ProfileIpiTemplate | string;

/** IPI do perfil: tratamento, enquadramento e alíquota. */
export type ProfileIpiTemplate = {
  /** CST. */
  cst: string;
  /** Enquadramento (`cEnq`, 3 dígitos). */
  enq: string;
  /** Alíquota, em percentual. */
  rate: DecimalText;
  type: "taxed";
} | {
  /** CST. */
  cst: string;
  /** Enquadramento (`cEnq`, 3 dígitos). */
  enq: string;
  type: "not_taxed";
};

/**
 * `pis_json`/`cofins_json` do perfil: o objeto, ou o mesmo objeto como texto
 * JSON (forma antiga, ainda aceita).
 */
export type ProfileTaxGroup = ProfileTaxTemplate | string;

/** PIS ou COFINS do perfil: só a alíquota. */
export type ProfileTaxTemplate = {
  /** CST. */
  cst: string;
  /** Alíquota, em percentual. */
  rate: DecimalText;
  type: "rate";
} | {
  /** CST. */
  cst: string;
  type: "not_taxed";
};

/** Receita, despesa (valor absoluto) e resultado. */
