  /** Endereço do DANFE; `null` enquanto não autorizada. */
  danfe_url: string | null;
  /** Modelo do documento fiscal (55 = NF-e, 65 = NFC-e). */
  document_model: number;
  /** Documento fiscal vinculado; `null` enquanto não há. */
  fiscal_document_id: string;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Número sequencial do documento na organização. */
  number: number;
  /** Pedido de venda de origem. */
  order_id: string;
  /** Devolução de origem. */
  return_id: string;
  /** Série do documento fiscal. */
  series: number;
  status: SalesFiscalDocumentStatus | null;
  /** Código de status da SEFAZ; `null` quando não há. */
  status_code: number | null;
  /** Motivo do status da SEFAZ; `null` quando não há. */
  status_reason: string | null;
