/** Lista completa de `SalesOrderReturnDocumentDto` (sem paginação). */
export interface SalesOrderReturnDocumentListDto {
  /** Os itens. */
  items: SalesOrderReturnDocumentDto[];
}

/** Devolução (total ou parcial) de uma venda, com as linhas devolvidas. */
export interface SalesOrderReturnDto {
  /** Quando foi registrado (RFC 3339). */
  created_at: string;
  /** Membro que registrou a devolução; `null` quando foi o sistema. */
  created_by_member_id: string | null;
  /** Valor creditado ao cliente pela devolução, em string decimal. */
  credit_amount: DecimalText;
  /** Chave da nota de devolução que o próprio cliente emitiu; `null` quando não há. */
  customer_note_key: string | null;
  /** Orçamento aberto pela troca; `null` fora da troca. */
  exchange_order_id: string | null;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Chave de idempotência enviada no registro. */
  idempotency_key: string;
  /** Linhas do documento. */
  lines: SalesOrderReturnLineDto[];
  /** Pedido de venda devolvido. */
  order_id: string;
  /** Motivo informado. */
  reason: string;
  /** Motivo da falha no reembolso; `null` quando não houve falha. */
  refund_error: string | null;
  /** `pending|completed|not_applicable`. */
  refund_status: SalesReturnRefundStatus;
  /** `refund|exchange|none`. */
  resolution: SalesReturnResolution;
  /** 1, 2, 3 dentro do pedido. */
  return_number: number;
  /** Lote de movimentos de estoque gerado; `null` enquanto não lançado. */
  stock_batch_id: string | null;
  /** Motivo da falha no `stock`; `null` quando não houve falha. */
  stock_error: string | null;
  /**
   * `pending` com erro = o vizinho recusou ou não respondeu, e repetir o
   * registro completa. A tela mostra o erro e o botão de repetir.
   */
  stock_status: SalesReturnStockStatus;
  /** Última alteração (RFC 3339). */
  updated_at: string;
  /** Depósito que recebe a mercadoria de volta; `null` quando nada volta ao estoque. */
  warehouse_id: string | null;
}

/** Linha devolvida de uma devolução. */
export interface SalesOrderReturnLineDto {
  /** Parte do total efetivo da venda que esta linha devolve. */
  credit_amount: DecimalText;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Linha do pedido de venda que está sendo devolvida. */
  order_item_id: string;
  /** Quantidade, em string decimal (nunca float). */
  quantity: DecimalText;
  /** Saída do `stock` que a linha desfaz; `null` quando a linha não saiu do estoque, e então a devolução dela não mexe em saldo. */
  sale_movement_id: string | null;
}

/** Lista completa de `SalesOrderReturnDto` (sem paginação). */
