/** Corpo de `PUT /v1/checkout/appearance`. */
export interface SetCheckoutAppearanceBody {
  /**
   * A cor da marca, `#rrggbb`. Ausente ou `null`: sem cor própria, vale a
   * paleta.
   */
  brand_color?: string | null;
  corners?: CheckoutCorners | null;
  font?: CheckoutFont | null;
  /** `bilhete`, `vitrine` ou `direto`. */
  layout: CheckoutLayout;
  mode?: CheckoutMode | null;
  /** `floresta`, `oceano`, `ameixa`, `ambar` ou `grafite`. */
  palette: CheckoutPalette;
}

/** Corpo de `PUT /v1/checkout/appearance/logo`. */
export interface SetCheckoutLogoBody {
  /**
   * A imagem em base64 (padrão). O tipo não é declarado: o serviço o lê
   * dos primeiros bytes e aceita PNG, JPEG ou WebP, até 64 KiB.
   */
  data_base64: string;
}

/** Corpo de `PUT /v1/checkout/appearance/tracking`. */
export interface SetCheckoutTrackingBody {
  /**
   * `G-` seguido de 4 a 16 letras ou dígitos. Ausente, `null` ou vazio:
   * sem GA4.
   */
  ga4_measurement_id?: string | null;
  /** De 5 a 20 dígitos. Ausente, `null` ou vazio: sem Pixel. */
  meta_pixel_id?: string | null;
}

/** Corpo de `PUT /v1/checkout/code-channel`. */
export interface SetCodeChannelBody {
  /**
   * `email` ou `whatsapp`.
   *
   * ⚠️ `sms` é recusado **pelo nome**: é a palavra que o integrador vai
   * tentar, e um erro genérico o faria procurar erro de digitação num canal
   * que a plataforma decidiu não ter.
   */
  channel: CheckoutCodeChannel;
  /** Template aprovado no provider, obrigatório quando o canal é `whatsapp`. */
  whatsapp_template_id?: string;
}

/** Regra de comissão de um papel num nível. */
export interface SetCommissionRuleBody {
  basis?: SalesRevenueBasis | null;
  distribution?: SalesCommissionDistribution | null;
  line_scope?: SalesCommissionLineScope | null;
  /** Em `member`. */
  member_id?: string | null;
  mode?: SalesAdjustMode | null;
  /** `seller` (quem vendeu) ou `executor` (quem executou o serviço). */
  participant_role: SalesParticipantRole;
  payout?: SalesCommissionPayout | null;
  /** Percentual de 0 a 100 no `set`, ou o ajuste; até 4 casas, string decimal. */
  percentage: string;
  /** Em `role`. */
  role_id?: string | null;
  /** `tenant` (padrão), `role` (cargo) ou `member` (pessoa). */
  scope: SalesRuleScope;
}

/**
 * Corpo dos tetos do cliente.
 *
 * ⚠️ É **substituição inteira**, não remendo: campo ausente remove aquele
 * teto. Por isso é `PUT`. O limite (topo da escala) é regra do serviço, não
 * desta camada.
 */
export interface SetConnectionCapsBody {
  /**
   * A escala sobe sozinha até o teto, um degrau por dia trabalhado.
   * Ausente = ligada. Desligar é aceitar o risco de o provider restringir o
   * número cedo.
   */
  auto_warmup?: boolean | null;
  /**
   * Teto de abordagem fria, no mesmo sentido. Zero mantém o atendimento e
   * para a prospecção.
   */
  cold_cap_override?: number | null;
  /**
   * Teto total do dia. Com a escala ligada é o máximo até onde ela sobe;
   * desligada, vale desde o primeiro dia. Ausente = sem máximo (ligada) ou
   * o degrau (desligada).
   */
  daily_cap_override?: number | null;
}

/**
 * Corpo do modo de atendimento da conexão.
 *
 * ⚠️ É **substituição inteira**, como o dos tetos: campo opcional ausente
 * remove a configuração. Faixas e a regra "encerramento só em `attendance`"
 * são do serviço, não desta camada.
 */
export interface SetConnectionServiceBody {
  /** Meta de primeira resposta em minutos (1-1440). Ausente = padrão. */
  first_response_target_minutes?: number | null;
  /**
   * Minutos sem mensagem para resolver a conversa sozinha (5-43200).
   * Ausente = nunca. Recusado fora de `attendance`.
   */
  idle_close_minutes?: number | null;
  /** `simple` ou `attendance`. */
  service_mode: SocialServiceMode;
}

/**
 * Corpo da troca dos usos da conexão.
 *
 * ⚠️ É **substituição inteira**: a lista mandada vira a lista da conexão.
 */
export interface SetConnectionUsagesBody {
  /** Ao menos um, e só os que o provider oferece (`offered_usages`). */
  usages: SocialConnectionUsage[];
}

/** Corpo da troca de etiquetas. */
export interface SetConversationLabelsBody {
  /**
   * O conjunto INTEIRO de etiquetas da conversa. Lista vazia tira todas.
   *
   * ⚠️ Substitui, não acrescenta: com dois atendentes na mesma conversa, um
   * par adicionar/remover converge para um conjunto que nenhum dos dois
   * pediu, e ninguém consegue dizer quem mudou o quê.
   */
  label_ids: string[];
}

/** Corpo do encerramento ou da reabertura. */
export interface SetConversationStatusBody {
  /** `open` ou `resolved`. */
  status: SocialConversationStatus;
}

/**
 * Corpo da configuração do método de custeio.
 *
 * Sem `product_id` vale para o tenant inteiro; com ele, só para aquele produto.
 * É a exceção deliberada em que a chave é o produto, e não a variante: método de
 * custeio é decisão contábil do item, não do SKU.
 */
export interface SetCostingBody {
  /** `average` (padrão) ou `fifo` (PEPS). */
  method: StockCostingMethod;
  /** Produto a que o método se aplica. Ausente, define o padrão do tenant. */
  product_id?: string | null;
}

/**
 * Corpo de definição (upsert) da Política de crédito do escopo.
 * Limiar ausente = regra desligada; `amount_for_days_*` andam juntos.
 */
export interface SetCreditPolicyBody {
  /** Piso de valor da regra combinada (decimal string). */
  amount_for_days_floor?: string | null;
  /** Dias da regra combinada. */
  amount_for_days_over_days?: number | null;
  /** Teto de valor em aberto (decimal string, ex.: `"10000.00"`). */
  max_open_amount?: string | null;
  /** Atraso máximo tolerado (dias). */
  max_overdue_days?: number | null;
  /** Organização dona (Snowflake decimal). Ausente = escopo tenant. */
  organization_id?: string | null;
}

/**
 * Corpo da adesão à entrada automática por DF-e.
 *
 * Adesão da **organização**, não do tenant: depósito pertence à organização, e é o CNPJ do destinatário que diz de qual empresa do grupo é a
 * nota que chegou.
 */
export interface SetDfeIngestionBody {
  /**
   * Liga ou desliga a abertura automática de recebimento a partir das notas
   * recebidas pela distribuição DF-e.
   *
   * ⚠️ Automático é "a nota já está montada esperando conferência", nunca "a
   * mercadoria entrou": só a efetivação do recebimento vira saldo.
   */
  is_enabled: boolean;
  /**
   * CNPJ interessado na distribuição DF-e (14 dígitos, só números).
   * **Obrigatório** quando `is_enabled`.
   */
  recipient_cnpj?: string | null;
  /**
   * Depósito de destino. Ausente = o Depósito Principal da organização,
   * resolvido no momento em que a nota chega.
   */
  warehouse_id?: string | null;
}

/** Corpo de `PUT /v1/fiscal/dfe/sync` - liga/desliga o poll do AN para um CNPJ. */
export interface SetDfeSyncBody {
  /**
   * CNPJ interessado - precisa ser um emitente cadastrado do tenant (é o A1
   * dele que autentica a consulta no Ambiente Nacional).
   */
  cnpj: string;
  /** Liga (`true`) ou desliga (`false`) o poll (sem perder a posição do cursor). */
  enabled: boolean;
  /** Ambiente: `production` | `homologation`. */
  environment: string;
}

/** Corpo de upsert de Configuração financeira de atraso. */
export interface SetFinancialSettingsBody {
  /**
   * - adquirente escolhido. **Ausente preserva** a escolha atual
   * (salvar multa/juros não apaga o adquirente); `""` limpa; id define.
   */
  acquiring_provider_id?: string | null;
  charge_accounts?: ChargeAccountsBody | null;
  commission_on_return?: string | null;
  /** Dias de carência antes de aplicar multa/juros. */
  grace_days: number;
  late_charge_policy?: PayLateChargePolicy | null;
  /** Multa única em % (decimal string, ex.: `"2"`). */
  late_fine_percent: string;
  /** Juros de mora em %/mês (decimal string, ex.: `"1"`). */
  late_interest_monthly_percent: string;
  /** Organização dona (Snowflake decimal). Ausente = escopo tenant. */
  organization_id?: string | null;
}

/** Body de `PUT /v1/fiscal-period-policy`. */
export interface SetFiscalPeriodPolicyBody {
  /**
   * Prazo máximo de manutenção pós-fechamento em dias. `0` = sem janela.
   *
   * O limite (`0..=366`) é **regra de negócio** e mora no domínio do `iam`
   * (`MAX_MAINTENANCE_DAYS_LIMIT`). O gateway não duplica esse bound: valores fora da faixa retornam `INVALID_ARGUMENT` do `iam`,
   * que `status_to_response` mapeia para 4xx.
   */
  max_maintenance_days: number;
  /** Escopo opcional por organização. Vazio/omitido = escopo tenant. */
  organization_id?: string;
}

/** Corpo do `PUT /v1/pay/financial-settings/installments`. */
export interface SetInstallmentPolicyBody {
  /** Escopo (Snowflake decimal). Ausente = organização da sessão, ou tenant. */
  organization_id?: string | null;
  /** A política. */
  policy: InstallmentPolicyDto;
}

/** Corpo do formulário personalizado de um lote. */
export interface SetLotCustomValuesBody {
  /**
   * Substitui o conjunto: campo ausente é campo **apagado**. Com merge não
   * existe forma de remover um valor digitado errado.
   */
  values: LotCustomValueBody[];
}

/** Trocar como a loja aceita o pedido. */
export interface SetMarketplaceFoodStoreConfirmMethodBody {
  /** O modo. */
  confirm_method: MarketplaceFoodConfirmMethod;
}

/** A semana inteira da loja. Substitui a anterior. */
export interface SetMarketplaceFoodStoreHoursBody {
  /** Os turnos, até 21. Vazio fecha a loja a semana toda. */
  shifts: MarketplaceFoodStoreShiftDto[];
}

/** Ligar ou desligar a presença da loja. */
export interface SetMarketplaceFoodStorePresenceBody {
  /**
   * `true`: a Ferrazio declara a loja online ao provider (a loja abre no
   * horário dela). `false`: a loja fecha no provider em poucos minutos.
   */
  enabled: boolean;
  event_channel?: MarketplaceFoodEventChannel | null;
}

/** A folga de uma variante. */
export interface SetMarketplaceVariantPolicyBody {
  /**
   * Estoque mínimo desta variante nesta conta (decimal em texto, zero ou
   * mais). Ausente ou vazio = vale o da política da conta; `0` = esta
   * variante nunca pausa nesta conta.
   */
  pause_at_stock?: string;
  /** Decimal em texto, zero ou mais. */
  safety_stock: string;
}

/** Corpo do `PUT /v1/pay/financial-settings/method-discounts`. */
export interface SetMethodDiscountBody {
  /** Escopo (Snowflake decimal). Ausente = organização da sessão, ou tenant. */
  organization_id?: string | null;
  /** A regra. */
  policy: MethodDiscountDto;
}

/** Os participantes de um papel. */
export interface SetParticipantsBody {
  /** Membros, sem repetição, no máximo 20. Vazio tira todos. */
  member_ids: string[];
}

/** A escolha da empresa para uma métrica do plano. */
export interface SetPlanPolicyBody {
  /** `block` ou `overage`. */
  mode: string;
  /**
   * Obrigatório em `overage`: quanto a mais aceitar na janela da métrica.
   * Ignorado em `block`.
   */
  overage_cap?: number;
}

/**
 * Corpo de `PATCH /v1/pay/recurrence/plans/{id}/reminders`: a régua de
 * aviso do plano. Campo ausente mantém o valor; lista vazia
 * mantém a lista.
 */
export interface SetPlanRemindersBody {
  /** Avisos antes do vencimento (nos dias de `remind_days_before`). */
  notify_due_soon?: boolean | null;
  /** Aviso no dia do vencimento. */
  notify_due_today?: boolean | null;
  /** Aviso na emissão do ciclo. */
  notify_on_emission?: boolean | null;
  /**
   * Avisos depois do vencimento, se não pago (nos dias de
   * `remind_days_after`).
   */
  notify_overdue?: boolean | null;
  /** Organização dona (vazio = escopo tenant). */
  organization_id?: string | null;
  /** Dias depois do vencimento: de 1 a 5 dias, cada um entre 1 e 30. */
  remind_days_after?: number[];
  /** Dias antes do vencimento: de 1 a 5 dias, cada um entre 1 e 30. */
  remind_days_before?: number[];
}

/** Corpo do `PUT` de preferência. */
export interface SetPreferenceBody {
  /** `true` silencia; `false` reativa. */
  muted: boolean;
}

/** Preço de uma variante numa tabela. */
export interface SetPriceBody {
  /**
   * Valor unitário como **string decimal**. Zero é preço
   * legítimo (brinde); negativo é recusado. Pode ter mais casas que a moeda:
   * preço unitário é taxa, não quantia.
   */
  unit_price: string;
}

/**
 * Corpo que define quais atributos variam naquele produto.
 *
 * Substitui o conjunto inteiro: os atributos enviados passam a ser os eixos de
 * variação do produto.
 */
export interface SetProductAttributesBody {
  /**
   * Ordem de exibição na tela. A posição sai daqui; a assinatura da variante
   * **não** depende dela (ordena por id), então reordenar não reescreve
   * variante já gravada. Até 50, o mesmo teto dos eixos da migração.
   */
  attribute_ids: string[];
  /**
   * O valor que as variantes que **já existem** recebem em cada eixo NOVO
   * da lista acima, o mesmo para todas ("a regata que já está no estoque é
   * de que cor?"). Obrigatório quando o modelo tem variante a preencher:
   * falta dá 412. Valor de eixo que não é novo, ou que não é do eixo, dá
   * 422. Ausente vale lista vazia.
   */
  fill_values?: AssignmentBody[];
}

/**
 * Corpo da despesa acessória informada **no total da nota** (F14).
 *
 * É o caminho de quem tem o frete no cabeçalho da NF-e e não por item: o total
 * fica aqui e o rateio o distribui na efetivação.
 */
export interface SetReceiptExpensesBody {
  /** Moeda dos valores acima. */
  currency?: string | null;
  /** Desconto incondicional, no total. */
  discount_amount?: string | null;
  expense_allocation?: StockExpenseAllocation | null;
  /** Frete total da nota, string decimal. */
  freight_amount?: string | null;
  /** Seguro total. */
  insurance_amount?: string | null;
  /** Outras despesas acessórias, no total. */
  other_amount?: string | null;
}

/**
 * Corpo da política de reposição (F13).
 *
 * ⚠️ **Ausente e vazio são coisas diferentes** em todo campo nulável: ausente
 * é "não mexe", string vazia é "apaga". Sem a distinção, salvar pela tela do
 * ponto de pedido apagaria o mínimo e o máximo que outra tela gravou.
 */
export interface SetReplenishmentPolicyBody {
  /** Janela de apuração da demanda, em dias. Default 90. */
  demand_window_days?: number | null;
  /** Política suspensa continua existindo. */
  is_active?: boolean | null;
  /**
   * Prazo de entrega em dias. ⚠️ É do par fornecedor × item na vida real;
   * aqui é do item enquanto não houver fornecedor por item.
   */
  lead_time_days?: number | null;
  /** Teto: acima disso é capital parado e risco de validade. */
  max_quantity?: string | null;
  /** Piso operacional: o que não pode faltar na gôndola. */
  min_quantity?: string | null;
  /**
   * Ponto de pedido informado. Com `source = computed` ele é reescrito pela
   * apuração diária.
   */
  reorder_point?: string | null;
  /** Lote de compra: a sugestão é arredondada para cima a um múltiplo dele. */
  reorder_quantity?: string | null;
  /** Estoque de segurança em dias de cobertura. Exclusivo com `service_level`. */
  safety_days?: string | null;
  /** Estoque de segurança por nível de serviço, entre 0 e 1 exclusive. */
  service_level?: string | null;
  source?: StockPolicySource | null;
  /** SKU (variante do `catalog`). */
  variant_id: string;
  /**
   * Depósito. Ausente grava o **default do tenant**, que vale para todo
   * depósito sem política própria.
   */
  warehouse_id?: string | null;
}

/** Corpo de definição (upsert) de alçada de pagamento de um cargo. */
export interface SetRolePaymentLimitBody {
  max_amount: DecimalTextOrEmpty | null;
  /** Organização dona (Snowflake decimal). Ausente = escopo tenant. */
  organization_id?: string | null;
  /** Cargo no `iam` (Snowflake decimal). Chave do upsert no escopo. */
  role_id: string;
  /** Nome do cargo (denormalizado para exibição). */
  role_name: string;
}

/**
 * Corpo de configuração (PUT) de um remetente.
 *
 * Grava sempre no escopo exato da sessão corrente (organização, se houver
 * uma selecionada; senão tenant) - sem cascata na escrita. Com `provider`
 * `smtp` (ou ausente) valem `host`, `port`, `username`, `password` e `tls`;
 * com `mailgun`, `mailgun_domain`, `mailgun_region` e `api_key`. Os campos
 * do outro provedor são ignorados e a linha os grava vazios.
 *
 * O `Debug` é escrito à mão e nunca mostra `password` nem `api_key`
 * : um `?body` num `tracing` futuro não vaza o segredo.
 */
export interface SetSenderConfigBody {
  /**
   * API key do Mailgun. **Ausente preserva** a key já gravada neste escopo;
   * a primeira gravação Mailgun do escopo exige a key.
   */
  api_key?: string | null;
  /**
   * Endereço de e-mail do remetente. Deve ser um e-mail próprio do
   * tenant/org - nunca um endereço da Ferrazio.
   */
  from_email: string;
  /** Nome de exibição do remetente (cabeçalho `From`). */
  from_name: string;
  /** Host SMTP (obrigatório com `smtp`). */
  host?: string;
  /**
   * Domínio de envio verificado na conta Mailgun, ex.: `mg.lojadaana.com.br`
   * (obrigatório com `mailgun`).
   */
  mailgun_domain?: string;
  /** Região da conta Mailgun: `us` (padrão) ou `eu`. */
  mailgun_region?: string;
  /**
   * Senha SMTP. **Ausente preserva** a senha já gravada neste escopo;
   * primeira gravação do escopo exige senha (não há o que preservar).
   */
  password?: string | null;
  /** Porta SMTP, 1..=65535 (obrigatória com `smtp`). */
  port?: number;
  /** `smtp` (padrão) ou `mailgun`. */
  provider?: string;
  /**
   * `starttls` (porta 587, upgrade) ou `implicit` (porta 465, "smtps"/SSL
   * desde a conexão). Obrigatório com `smtp`.
   */
  tls?: string;
  /** Usuário SMTP (obrigatório com `smtp`). */
  username?: string;
}

/** Body de `PUT /v1/persons/settings`. */
export interface SetSettingsBody {
  /** Escopo opcional por organização. Vazio/omitido = escopo tenant. */
  organization_id?: string;
  /** `true` = recusar criar pessoa com documento já cadastrado no escopo. */
  require_unique_document: boolean;
}

/**
 * Corpo de `POST /v1/pay/split-profiles/{id}/active` - alterna o estado de uma
 * versão específica.
 */
export interface SetSplitProfileActiveBody {
  /** Novo estado: `true` ativa, `false` desativa. */
  is_active: boolean;
  /** Versão alvo (≥ 1). */
  version: number;
}

/** Corpo de `PATCH /v1/pay/recurrence/subscriptions/{id}/payment-method`. */
export interface SetSubscriptionPaymentMethodBody {
  /** Método novo: `pix` | `boleto` | `card`, entre os do plano. */
  method: PayAcquiringMethod;
  /** Organização dona (vazio = escopo tenant). */
  organization_id?: string | null;
  /**
   * Cartão salvo que passa a pagar (Snowflake decimal), só em `card`.
   *
   * Ausente mantém o cartão que a assinatura já tem. Tem de estar `active`
   * e ser do mesmo pagador; em `pix` ou `boleto` informá-lo é recusa. Quem
   * valida é o `pay`: o gateway não conhece o dono do cartão (regra
   * dura 3).
   */
  saved_card_id?: string | null;
}

/**
 * Corpo de `PATCH /v1/pay/recurrence/subscriptions/{id}/reminders`: os
 * canais em que o assinante aceita lembrete. Ausente mantém.
 */
export interface SetSubscriptionRemindersBody {
  /** Organização dona (vazio = escopo tenant). */
  organization_id?: string | null;
  /** Aceita lembrete por e-mail. */
  remind_email?: boolean | null;
  /** Aceita lembrete por WhatsApp. */
  remind_whatsapp?: boolean | null;
}

/** Corpo de `PATCH /v1/pay/recurrence/subscriptions/{id}/status`. */
export interface SetSubscriptionStatusBody {
  /** Organização dona (vazio = escopo tenant). */
  organization_id?: string | null;
  /**
   * Novo status: `active` (retomar), `paused` ou `canceled`.
   *
   * `past_due` **não** é aceito - quem o define é o motor de cobrança, ao
   * constatar inadimplência. O serviço recusa com 422.
   */
  status: PaySubscriptionStatusChange;
}

/**
 * Corpo de baixa (pagamento) de Conta a Pagar.
 *
 * A baixa cria uma `FinancialOperation` no ledger: débito na `source_wallet`
 * (definida na criação do AP) e crédito na `destination_wallet`.
 * Pagamentos parciais são suportados - o título transita para `partial`.
 */
export interface SettlePayableBody {
  /** Valor pago na baixa como string decimal. */
  amount: string;
  /** Descrição para auditoria. */
  description?: string | null;
  /**
   * Wallet que recebe o crédito na saída - geralmente uma wallet com papel
   * `external` (representando o banco/PSP do credor).
   */
  destination_wallet_id: string;
  /**
   * Desconto obtido nesta baixa (decimal; vazio/`"0"` = nenhum). Reduz a
   * despesa reconhecida, na conta de desconto configurada.
   */
  discount_amount?: string | null;
  /**
   * Chave de idempotência da operação financeira gerada na baixa.
   * Permite retentar com segurança sem criar lançamento duplo.
   */
  idempotency_key: string;
  /**
   * Juros pagos nesta baixa (decimal; vazio/`"0"` = nenhum).
   *
   * Vai para a conta contábil de juros configurada em vez de somar na conta
   * de despesa: é dinheiro ALÉM da dívida, então não amortiza o título. A
   * perna contábil sempre existiu no `pay`, e só este corpo não a
   * oferecia, enquanto a baixa de Contas a Receber já oferecia as duas.
   */
  interest_amount?: string | null;
  payment_method?: PayPayableMethod | null;
}

/**
 * Corpo de baixa (pagamento) de Conta a Receber.
 *
 * A baixa cria uma `FinancialOperation` no ledger: crédito na
 * `destination_wallet` e débito na `source_wallet`. Pagamentos parciais são
 * suportados - o título transita para `partial` até quitar o `amount` total.
 * tenant_id é injetado pelo gateway via `RequestContext`.
 */
export interface SettleReceivableBody {
  /** Valor pago na baixa como string decimal. */
  amount: string;
  /** Descrição para auditoria. */
  description?: string | null;
  /**
   * Banco/carteira onde o dinheiro entrou nesta baixa (sobrepõe o do
   * título). Vazio = usa o do título.
   */
  destination_wallet_id?: string | null;
  /**
   * Desconto concedido nesta baixa (decimal; vazio/"0" = nenhum). Reduz a
   * receita reconhecida, na conta de desconto configurada (C12b).
   */
  discount_amount?: string | null;
  /**
   * Chave de idempotência da operação financeira gerada na baixa.
   * Permite retentar com segurança sem criar lançamento duplo.
   */
  idempotency_key: string;
  /**
   * Juros cobrados nesta baixa (decimal; vazio/"0" = nenhum).
   *
   * Vai para a conta contábil de juros configurada (C12b) em vez de somar na
   * conta de venda; sem configuração, entra no principal como antes. É
   * dinheiro ALÉM da dívida, então não amortiza o título.
   */
  interest_amount?: string | null;
  /**
   * Wallet de onde sai o dinheiro - geralmente uma wallet com papel
   * `external` (representando o banco/PSP de entrada).
   */
  source_wallet_id: string;
}

/** Corpo de criação de link de compartilhamento. */
export interface ShareLinkBody {
  /** Expiração (RFC 3339, ex.: `2026-10-25T14:00:00Z`; vazio/ausente = sem expiração). */
  expires_at?: string | null;
  kind?: ShareLinkKindInput | null;
}

/** Link de compartilhamento criado. */
export interface ShareLinkDto {
  /** Expiração (RFC 3339; `null` = sem expiração). */
  expires_at: string | null;
  /** Snowflake do link. */
  id: string;
  /** `public` | `self`. */
  kind: ArchiveShareLinkKind;
  /** Token opaco (compõe a URL pública). */
  token: string;
}

/** Tipo do link de compartilhamento pedido. */
export type ShareLinkKindInput = "public" | "self";

/** Lista de links de compartilhamento (`{ items }`). */
export interface ShareLinksListDto {
  /** Os links de compartilhamento ativos do arquivo. */
  items: ShareLinkDto[];
}

/** Corpo de toda rota de importação de planilha. */
export interface SheetImportBody {
  /**
   * O texto do arquivo CSV (`,` `;` ou TAB; a primeira linha preenchida é o
   * cabeçalho). Até 5 MiB e 5 mil linhas.
   */
  csv: string;
  /** `true` = só confere: valida cada linha e diz o que criaria, sem gravar. */
  dry_run?: boolean;
}

/** A chave que uma linha ganhou ou já tinha. */
export interface SheetImportKeyDto {
  /** A chave (o SKU, no catálogo). */
  key: string;
  /** Linha no arquivo, contando o cabeçalho como 1. */
  line: number;
}

/** Uma linha recusada. */
export interface SheetImportRejectionDto {
  /** Detalhe em texto. */
  detail: string;
  /** Linha no arquivo, contando o cabeçalho como 1. */
  line: number;
  /** Motivo em código (`document_invalid`, `sku_not_found`...). */
  reason: string;
}

/** O relatório de uma importação (ou da conferência, com `dry_run`). */
export interface SheetImportReportDto {
  /** Linhas que criaram registro (na conferência: que criariam). */
  created: number;
  /** `true` quando nada foi gravado. */
  dry_run: boolean;
  /** Cabeçalhos que não são do modelo e foram ignorados. */
  ignored_columns: string[];
  /**
   * A chave natural de cada linha gravada ou já existente, quando o dono do
   * dado a cria (o SKU que o catálogo deu a uma linha sem SKU). Vazio na
   * conferência. Serve para encadear o saldo inicial sobre a planilha de
   * produtos.
   */
  keys: SheetImportKeyDto[];
  /** Linhas recusadas (total). */
  rejected: number;
  /** As primeiras 200 recusas, na ordem do arquivo. */
  rejections: SheetImportRejectionDto[];
  /** Linhas de dado lidas. */
  rows: number;
  /** Linhas que já existiam e ficaram como estavam. */
  unchanged: number;
}

/**
 * Peso e dimensões da variante: o que a torna despachável.
 *
 * Sem medida não há pacote, e sem pacote transportadora nenhuma cota frete. É
 * por isso que este bloco mora no cadastro e não num campo personalizado: base
 * de cálculo não pode depender de alguém ter escolhido o nome certo.
 *
 * ⚠️ **Inteiro em grama e em milímetro**, e não decimal com casas: é medida
 * física, não dinheiro. A unidade menor dispensa a pergunta "quantas casas?"
 * em cada fronteira.
 */
export interface ShippingBody {
  /** Altura da embalagem, em milímetros, de 1 a 10 000. */
  height_mm?: number | null;
  /**
   * Embalagem fora do formato de caixa (rolo, tubo, peça sem embalagem).
   * Não é medida: vale com ou sem as arestas. Ausente: `false`.
   */
  irregular_shape?: boolean;
  /**
   * Maior aresta da embalagem, em **milímetros**, de 1 a 10 000.
   *
   * As três arestas andam juntas: informar uma exige as outras duas, porque
   * comprimento sem altura não produz cubagem nenhuma. E dimensão exige
   * peso, porque a transportadora cobra pelo **maior** entre o peso real e o
   * cubado: volume sem peso real deixaria a conta sair pela metade. Zero
   * vale como não medido, nesta e nas outras duas arestas.
   */
  length_mm?: number | null;
  /**
   * Peso bruto da unidade base, em **gramas**, de 1 a 2 000 000 (2 toneladas).
   * Zero vale como não medido.
   */
  weight_grams?: number | null;
  /** Largura da embalagem, em milímetros, de 1 a 10 000. */
  width_mm?: number | null;
}

/**
 * Situação da conexão com a transportadora: só documenta os
 * valores, o fio é texto.
 */
export type ShippingCarrierStatus = "not_connected" | "active" | "reauth_required";

/**
 * Uma opção de frete: o que a cotação oferece e o que a escolha congela.
 *
 * ⚠️ O `id` **não é identificador interno** (`CH4`): é o que a própria página
 * devolve no passo seguinte, não serve fora desta cotação, e a cotação morre no
 * prazo dela.
 */
export interface ShippingOptionDto {
  /** Transportadora, por extenso. */
  carrier_name: string;
  /** O que a página devolve ao escolher. */
  id: string;
  /** Quanto custa (decimal em texto). */
  price: DecimalText;
  /** Serviço, por extenso. */
  service_name: string;
  /** Prazo em dias úteis. */
  transit_days: number;
}

/** A lista de opções, como a tela do comprador a lê. */
export interface ShippingQuoteDto {
  /** Moeda da **cesta**: o frete é cobrado junto com ela. */
  currency: string;
  /** Para onde foi cotado, normalizado. */
  destination_postal_code: string;
  /**
   * ⚠️ **Vazio é desfecho, não erro**: "ninguém entrega nesse CEP" é uma
   * resposta que a página precisa poder dar.
   */
  options: ShippingOptionDto[];
}

/**
 * Corpo de `POST /v1/sign/public/invite/marks`: o grupo, sempre
 * `initials`.
 */
export interface SignAcceptMarksBody {
  /** O grupo aceito de uma vez. */
  group: SignMarksGroup;
}

/** A resposta do agente a uma escrita. */
export interface SignAgentAckDto {
  /** Quantos certificados ficaram, na oferta. */
  accepted: number;
  /** O passo do pareamento depois da escrita. */
  state: SignIcpAgentStep;
}

/** Corpo de `POST /v1/sign/public/agent/certificates`. */
export interface SignAgentCertificatesBody {
  /**
   * Os certificados achados. Ficam só os de assinatura que valem agora,
   * até oito.
   */
  certificates: SignAgentOfferedCertificateDto[];
}

/** O que o agente tem a assinar. */
export interface SignAgentJobDto {
  /** `rsa-pkcs1-sha256` ou `ecdsa-p256-sha256`. */
  algorithm: string;
  /** SHA-256 do certificado escolhido, em hex. */
  certificate_sha256: string;
  /** O nome do arquivo. */
  document_name: string;
  /** SHA-256 do PDF original, em hex. */
  document_sha256: string;
  /** Quanto tempo resta ao pareamento. */
  expires_in_seconds: number;
  /** A preparação; vazia quando não há o que assinar. */
  preparation_id: string;
  /** O SET dos atributos assinados, em DER, em base64. */
  signed_attrs: string;
  /** O passo do pareamento. */
  state: SignIcpAgentStep;
  /** O título do envelope. */
  title: string;
}

/** Um certificado que o agente achou no token. */
export interface SignAgentOfferedCertificateDto {
  /** O certificado, em DER, em base64. */
  certificate: string;
  /** As ACs que estavam no token, em DER, em base64. Até seis. */
  chain?: string[];
}

/** Corpo de `POST /v1/sign/public/agent/pair`. */
export interface SignAgentPairBody {
  /** O que o agente diz de si (programa, versão, sistema). */
  agent?: string;
  /** O código que a página mostrou, com ou sem hífen. */
  code: string;
}

/** O agente pareado. */
export interface SignAgentPairedDto {
  /** O token do agente, a mandar em `x-sign-agent-token`. Só sai aqui. */
  agent_token: string;
  /** Quanto tempo resta ao pareamento. */
  expires_in_seconds: number;
  /** A organização de quem enviou. */
  organization_name: string;
  /** Quem enviou. */
  sender_name: string;
  /** Quem assina, como o envelope chama. */
  signer_name: string;
  /** O título do envelope, para a pessoa conferir que entrou no certo. */
  title: string;
}

/** Corpo de `POST /v1/sign/public/agent/signature`. */
export interface SignAgentSignatureBody {
  /** A preparação do pedido. */
  preparation_id: string;
  /**
   * A assinatura dos `signed_attrs`, em base64: PKCS#1 v1.5 (RSA) ou
   * ECDSA P-256 em DER.
   */
  signature: string;
}

/** Âncora de hora do envelope ou do dia: só documenta os valores, o fio é texto. */
export type SignAnchorState = "none" | "queued" | "pending" | "confirmed" | "dead";

/** Política de autenticação de quem assina: só documenta os valores, o fio é texto. */
export type SignAuthPolicy = "fz-link-v1" | "fz-email-otp-v1" | "fz-passkey-v1" | "fz-icp-v1";

/**
 * Corpo de `POST /v1/sign/batches`: o modelo, o que as linhas dividem e as
 * linhas.
 */
export interface SignBatchBody {
  /** Nome do arquivo. Vazio usa o nome do modelo. */
  document_name?: string;
  /** Dias até vencer, de 1 a 90. Zero usa o dos ajustes. */
  expires_in_days?: number;
  /**
   * Por qual e-mail saem convite, lembrete, código e cópia final:
   * `platform` (o da Ferrazio) ou `own` (o remetente da organização no
   * Mailer). Vazio usa o dos ajustes. `own` sem remetente cadastrado é
   * `412` com `sign_mail_sender_not_configured`.
   */
  mail_sender?: SignMailSender;
  /** Mensagem que vai em cada convite. Opcional. */
  message?: string;
  /** `parallel` (padrão) ou `sequential`. */
  order?: SignSigningOrder;
  /**
   * `fz-link-v1`, `fz-email-otp-v1`, `fz-passkey-v1` ou `fz-icp-v1`.
   * Vazio usa a dos ajustes.
   */
  policy?: SignAuthPolicy;
  /** Uma por destinatário, até 200. */
  rows: SignBatchRowBody[];
  /**
   * Quem cria declara que os documentos não são dos tipos que o serviço
   * não cobre. Sem isto o serviço recusa (`sign_scope_not_confirmed`).
   */
  scope_confirmed?: boolean;
  /**
   * `true` envia cada envelope assim que ele nasce; `false` deixa em
   * rascunho.
   */
  send?: boolean;
  /** Quem pede a assinatura. Vazio usa o dos ajustes da organização. */
  sender_name?: string;
  /** O modelo (Snowflake). */
  template_id: string;
  /**
   * A versão que a pessoa viu. Outra em vigor é `409` com
   * `sign_template_changed`. Ausente aceita a versão em vigor. Todas as
   * linhas saem desta versão, mesmo que o modelo mude no meio.
   */
  template_version?: number | null;
  /**
   * Título de cada envelope. Vazio usa o título do modelo preenchido com
   * os valores de cada linha.
   */
  title?: string;
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id?: string;
}

/** O lote com as linhas. */
export interface SignBatchDetailDto {
  /** O lote. */
  batch: SignBatchDto;
  /** As linhas, na ordem. */
  rows: SignBatchRowDto[];
}

/** Um lote de envelopes. */
export interface SignBatchDto {
  /** Linhas canceladas antes de sair. */
  cancelled: number;
  /** Quando foi cancelado. `null` enquanto não foi. */
  cancelled_at: string | null;
  /** Linhas com envelope. */
  created: number;
  /** Quando (RFC 3339). */
  created_at: string;
  /** Quem criou: os envelopes nascem em nome desta pessoa. */
  created_by: string;
  /** Nome do arquivo. Vazio: o do modelo. */
  document_name: string;
  /** Dias para assinar. Zero: o dos ajustes. */
  expires_in_days: number;
  /** Linhas recusadas. */
  failed: number;
  /** ID (Snowflake). */
  id: string;
  /** Remetente dos e-mails. Vazio: o dos ajustes. */
  mail_sender: string;
  /** Mensagem dos convites. */
  message: string;
  /** Ordem. Vazia: `parallel`. */
  order: string;
  /** Política. Vazia: a dos ajustes. */
  policy: string;
  /** Linhas esperando. */
  queued: number;
  /** Quantas linhas. */
  row_count: number;
  /** Cada envelope é enviado assim que nasce. */
  send: boolean;
  /** Quem pede. Vazio: o dos ajustes. */
  sender_name: string;
  /** O modelo. */
  template_id: string;
  /** O nome do modelo quando o lote foi criado. */
  template_name: string;
  /** SHA-256 (hex) do conteúdo dessa versão. */
  template_sha256: string;
  /** A versão de que todas as linhas saem. */
  template_version: number;
  /** Título de cada envelope. Vazio: o do modelo, preenchido. */
  title: string;
  /** O cofre de todos os envelopes do lote. Vazio é o padrão. */
  vault_id: string;
}

/** Uma linha do lote: os valores dos campos e quem assina. */
export interface SignBatchRowBody {
  /** Quem assina, na ordem. */
  signers: SignBatchSignerDto[];
  /** Valor de cada campo, pela chave. */
  values?: Record<string, string>;
}

/** Uma linha do lote. */
export interface SignBatchRowDto {
  /** Quantas vezes o serviço tentou. */
  attempts: number;
  /** O envelope, quando `created`. */
  envelope_id: string;
  /** Os nomes de quem assina. */
  label: string;
  /** A posição no lote, a partir de 1. */
  n: number;
  /** O código da recusa, quando `failed`. */
  reason: string;
  /** `queued`, `created`, `failed` ou `cancelled`. */
  status: SignBatchRowStatus;
  /** Última mudança (RFC 3339). */
  updated_at: string;
}

/** Estado de uma linha do lote: só documenta os valores, o fio é texto. */
export type SignBatchRowStatus = "queued" | "created" | "failed" | "cancelled";

/**
 * Uma pessoa de uma linha do lote. Sem quadro de selo: o lugar sai da vaga
 * que o modelo desenha para cada pessoa.
 */
export interface SignBatchSignerDto {
  /** E-mail que recebe o convite e o código. */
  email: string;
  /** Opcional. Quando vem, quem assina precisa digitar o mesmo CPF. */
  expected_cpf?: string;
  /** Nome de quem assina, como aparece no convite. */
  name: string;
  /**
   * Opcional: celular com DDI, ou com DDD para o Brasil.
   * Com ele o convite e os lembretes saem também por WhatsApp.
   */
  phone?: string;
  /** `signer` (padrão), `witness`, `approver` ou `copy` (só acompanha). */
  role?: SignSignerRole;
}

/** Página de lotes. */
export interface SignBatchesPageDto {
  /** Os lotes da página, do mais novo para o mais antigo. */
  batches: SignBatchDto[];
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
}

/** Corpo de `POST /v1/sign/envelopes/{id}/cancel`. */
export interface SignCancelBody {
  /** Por que o envelope foi cancelado. Entra na cadeia de eventos. */
  reason?: string;
}

/** Resposta do pedido de código. */
export interface SignCodeSentDto {
  /** O e-mail que recebeu o código, mascarado. */
  email_masked: string;
  /** Segundos de validade do código. */
  expires_in_seconds: number;
  /** Segundos até poder pedir outro. */
  retry_after_seconds: number;
}

/**
 * Corpo de `POST /v1/sign/public/verify`. Os dois campos chegam
 * como vierem: nada aqui recusa, porque a resposta não pode dizer o que
 * estava errado.
 */
export interface SignCopyRequestBody {
  /** O código do relatório (XXXX-XXXX-XXXX-XXXX). */
  code?: string;
  /** O e-mail de quem participou do envelope. */
  email?: string;
}

/** A resposta de `POST /v1/sign/public/verify`: sempre esta. */
export interface SignCopyRequestedDto {
  /** O aviso, igual para todo pedido. */
  message: string;
}

/**
 * O registro de um dia (UTC): a raiz Merkle de todos os manifestos selados
 * nele, selada pela chave de selo e ligada ao registro do dia anterior.
 */
export interface SignDayDto {
  /** Quando o dia foi fechado (RFC 3339). */
  closed_at: string;
  /** O dia, `AAAA-MM-DD` (UTC). */
  day: string;
  /** SHA-256 da chave pública que selou, em hex. */
  key_fingerprint: string;
  /** Identificador da chave que selou o registro. */
  kid: string;
  /** SHA-256 do registro do dia anterior, em hex. Vazio só no primeiro dia. */
  previous_sha256: string;
  /** A raiz da árvore, em hex. */
  root: string;
  /** A assinatura Ed25519 do registro: 64 bytes em base64. */
  signature: string;
  /** O registro em JSON canônico, como foi assinado. */
  statement: string;
  /**
   * SHA-256 do registro (`dia.json`), em hex. É o que se compara com o
   * pacote.
   */
  statement_sha256: string;
  /** Altura do bloco da âncora. Zero sem âncora confirmada. */
  timestamp_height: number;
  /**
   * A prova de data do registro (OpenTimestamps), em base64. Vazia
   * enquanto não existe.
   */
  timestamp_proof: string;
  /** `none`, `queued`, `pending`, `confirmed` ou `dead`. */
  timestamp_state: SignAnchorState;
}

/** Página de registros do dia, do mais novo para o mais antigo. */
export interface SignDaysPageDto {
  /** Os registros da página. */
  days: SignDayDto[];
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
}

/** Corpo de `POST /v1/sign/public/invite/decline`. */
export interface SignDeclineBody {
  /** Por que a pessoa recusa. Entra na cadeia de eventos e o remetente lê. */
  reason?: string;
}

/** Corpo de `POST /v1/sign/envelopes/{id}/discard`. */
export interface SignDiscardBody {
  /**
   * `retention_ended`, `holder_request`, `sent_by_mistake` ou `other`.
   * Vocabulário fechado: o motivo fica na lápide para sempre.
   */
  reason: SignDiscardReason;
}

/**
 * A lápide de um envelope descartado: o comprovante da exclusão. Só hashes
 * e datas, sem nome, e-mail, CPF, IP, título nem mensagem.
 */
export interface SignDiscardDto {
  /** Quem pediu, como `user:<id>`. */
  actor: string;
  /** Fechamento sem conclusão (RFC 3339). `null` quando não fechou. */
  closed_at: string | null;
  /** Conclusão (RFC 3339). `null` quando não concluiu. */
  completed_at: string | null;
  /** Quando (RFC 3339). */
  discarded_at: string;
  /** SHA-256 do documento, em hex. */
  document_sha256: string;
  /** ID do envelope que existiu (Snowflake). */
  envelope_id: string;
  /** O Files já confirmou a exclusão do original. */
  file_discarded: boolean;
  /** SHA-256 do manifesto selado, em hex. Vazio sem selo. */
  manifest_sha256: string;
  /** O motivo. */
  reason: SignDiscardReason;
  /** Chave que selou. Vazio sem selo. */
  seal_kid: string;
  /**
   * O estado em que estava: `completed`, `declined`, `expired` ou
   * `cancelled`.
   */
  status: SignDiscardedStatus;
  /** Código do verificador, que segue respondendo "descartado". */
  verify_code: string;
}

/** Motivo do descarte, gravado na lápide: só documenta os valores, o fio é texto. */
export type SignDiscardReason = "retention_ended" | "holder_request" | "sent_by_mistake" | "other";

/** Estado em que o envelope descartado estava (só os de fim): só documenta os valores, o fio é texto. */
export type SignDiscardedStatus = "completed" | "declined" | "expired" | "cancelled";

/** O envelope aberto: dados, signatários e a cadeia de eventos. */
export interface SignEnvelopeDetailDto {
  /** O envelope. */
  envelope: SignEnvelopeDto;
  /** A cadeia de eventos, do primeiro ao último. */
  events: SignEventDto[];
  /** Quem assina, na ordem. */
  signers: SignSignerDto[];
}

/** O envelope, sem signatários nem eventos. */
export interface SignEnvelopeDto {
  /** Altura do bloco da âncora confirmada. Zero antes disso. */
  anchor_height: number;
  /** Âncora de hora: `none`, `queued`, `pending`, `confirmed` ou `dead`. */
  anchor_state: SignAnchorState;
  /** O motivo do fechamento, quando houve. */
  close_reason: string;
  /**
   * Fechamento sem conclusão (RFC 3339): recusa, vencimento ou cancelamento.
   * `null` quando não fechou.
   */
  closed_at: string | null;
  /**
   * SHA-256 em hex do documento completo: o assinado seguido
   * das páginas do certificado. Vazio sem ele (política ICP-Brasil ou
   * envelope selado antes dele).
   */
  complete_sha256: string;
  /** Tamanho do documento completo em bytes. Zero sem ele. */
  complete_size: number;
  /** Conclusão (RFC 3339). `null` se não concluiu. */
  completed_at: string | null;
  /** Criação (RFC 3339). */
  created_at: string;
  /** Usuário que criou (Snowflake). */
  created_by: string;
  /**
   * A partir de quando quem administra pode descartar o envelope (RFC
   * 3339). `null` enquanto ele está aberto ou concluído sem selo.
   */
  discardable_at: string | null;
  /** Nome do arquivo recebido. */
  document_name: string;
  /** SHA-256 do PDF, em hex: o primeiro elo da cadeia. */
  document_sha256: string;
  /** Tamanho do PDF em bytes. */
  document_size: number;
  /** Vencimento (RFC 3339). `null` no rascunho. */
  expires_at: string | null;
  /** Dias de validade pedidos na criação. */
  expires_in_days: number;
  /** Id do envelope (Snowflake). */
  id: string;
  /**
   * `platform` (o e-mail da Ferrazio) ou `own` (o da organização): o
   * remetente que o envelope guardou ao nascer.
   */
  mail_sender: SignMailSender;
  /** Mensagem do convite. */
  message: string;
  /** `parallel` ou `sequential`. */
  order: SignSigningOrder;
  /**
   * Nome com que a organização que enviou está cadastrada. Vem do cadastro,
   * não do pedido, e aparece ao lado de `sender_name`. Vazio em envelope
   * criado antes de o nome ser guardado.
   */
  organization_name: string;
  /** Módulo que pediu a assinatura, quando houve. */
  origin_kind: string;
  /** Registro de origem naquele módulo. */
  origin_ref: string;
  /** `fz-link-v1`, `fz-email-otp-v1`, `fz-passkey-v1` ou `fz-icp-v1`. */
  policy: SignAuthPolicy;
  /** O plano de lembretes que o envelope guardou ao nascer. */
  reminders: SignReminderPlanDto;
  /** `true` quando o pacote de evidências já pode ser baixado. */
  sealed: boolean;
  /** Quem pede a assinatura. */
  sender_name: string;
  /** Envio (RFC 3339). `null` no rascunho. */
  sent_at: string | null;
  /** Quantos já assinaram. */
  signed_count: number;
  /**
   * SHA-256 em hex do documento assinado (o original seguido dos selos
   * visuais). Vazio quando o selo saiu sem desenho ou ainda não saiu.
   */
  signed_sha256: string;
  /** Tamanho do documento assinado em bytes. Zero sem ele. */
  signed_size: number;
  /** Quantos precisam assinar. */
  signer_count: number;
  /** `draft`, `sent`, `completed`, `declined`, `expired` ou `cancelled`. */
  status: SignEnvelopeStatus;
  /** Título. */
  title: string;
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id: string;
  /** Código do verificador (`XXXX-XXXX-XXXX-XXXX`). */
  verify_code: string;
  /**
   * `true` quando o convite e os lembretes saem também por WhatsApp a
   * quem tem telefone. Congelado ao nascer.
   */
  whatsapp: boolean;
}

/**
 * O campo `meta` do multipart de `POST /v1/sign/envelopes`: tudo do envelope
 * menos os bytes do PDF.
 */
export interface SignEnvelopeMeta {
  /**
   * Tamanho do PDF em bytes, como o cliente o tem. É o que torna um
   * arquivo cortado no caminho detectável.
   */
  document_size: number;
  /** Dias até vencer, de 1 a 90. Zero usa o dos ajustes. */
  expires_in_days?: number;
  /**
   * Por qual e-mail saem convite, lembrete, código e cópia final:
   * `platform` (o da Ferrazio) ou `own` (o remetente da organização no
   * Mailer). Vazio usa o dos ajustes. `own` sem remetente cadastrado é
   * `412` com `sign_mail_sender_not_configured`.
   */
  mail_sender?: SignMailSender;
  /** Mensagem que vai no convite. Opcional. */
  message?: string;
  /** `parallel` (padrão) ou `sequential`. */
  order?: SignSigningOrder;
  /** Módulo que pediu a assinatura (`hr`, `sales`). Opcional. */
  origin_kind?: string;
  /** Registro de origem naquele módulo. Opcional. */
  origin_ref?: string;
  /**
   * `fz-link-v1`, `fz-email-otp-v1`, `fz-passkey-v1` ou `fz-icp-v1`.
   * Vazio usa a dos ajustes.
   */
  policy?: SignAuthPolicy;
  reminders?: SignReminderPlanDto | null;
  /**
   * Quem cria declara que o documento não é dos tipos que o serviço não
   * cobre. Sem isto o serviço recusa (`sign_scope_not_confirmed`).
   */
  scope_confirmed?: boolean;
  /** `true` envia na mesma chamada; `false` deixa em rascunho. */
  send?: boolean;
  /** Quem pede a assinatura. Vazio usa o dos ajustes da organização. */
  sender_name?: string;
  /** Quem assina, na ordem (a posição conta quando `order = sequential`). */
  signers: SignSignerInput[];
  /** Título do envelope, como aparece no convite e no relatório. */
  title: string;
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id?: string;
  /**
   * `true` manda o convite e os lembretes só por e-mail.
   * Por padrão saem também por WhatsApp a quem tem telefone.
   */
  whatsapp_off?: boolean;
}

/** Estado do envelope: só documenta os valores, o fio é texto. */
export type SignEnvelopeStatus = "draft" | "sent" | "completed" | "declined" | "expired" | "cancelled";

/** Página de envelopes. */
export interface SignEnvelopesPageDto {
  /** Os envelopes da página. */
  envelopes: SignEnvelopeDto[];
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
}

/** Um elo da cadeia de eventos do envelope. */
export interface SignEventDto {
  /** O evento em JSON canônico, como entrou no hash. */
  canonical: string;
  /** Hash do elo, em hex. */
  hash: string;
  /**
   * `created`, `sent`, `invite_sent`, `viewed`, `otp_sent`, `otp_failed`,
   * `passkey_requested`, `icp_prepared`, `cpf_failed`, `marks_accepted`,
   * `signed`, `declined`, `expired`, `cancelled`, `completed`, `sealed`,
   * `anchored`, `copy_reissued` ou `copy_requested` (os 19 do
   * `EventKind::as_str` do serviço).
   */
  kind: SignEventKind;
  /** Quando aconteceu (RFC 3339). */
  occurred_at: string;
  /** Posição na cadeia, a partir de 1. */
  seq: number;
  /** Signatário a que o evento se refere. Vazio em evento do envelope. */
  signer_id: string;
}

/** Elo da cadeia de evidências do envelope: só documenta os valores, o fio é texto. */
export type SignEventKind = "created" | "sent" | "invite_sent" | "invite_bounced" | "email_opened" | "viewed" | "whatsapp_sent" | "whatsapp_failed" | "whatsapp_read" | "otp_sent" | "otp_failed" | "passkey_requested" | "icp_prepared" | "cpf_failed" | "marks_accepted" | "signed" | "declined" | "expired" | "extended" | "cancelled" | "completed" | "sealed" | "anchored" | "copy_reissued" | "copy_requested";

/** Corpo de `POST /v1/sign/envelopes/{id}/extend`. */
export interface SignExtendBody {
  /**
   * Dias, a contar de agora, até o novo prazo, de 1 a 90. O novo prazo
   * tem de cair depois do atual.
   */
  days: number;
}

/** O conteúdo de um campo de formulário (`POST /v1/sign/fields`). */
export interface SignFieldBody {
  /** Descrição, até 500 caracteres. Aceita várias linhas. */
  description?: string;
  /**
   * `text`, `multiline`, `name`, `date`, `number`, `document`, `email`,
   * `phone`, `postal_code`, `country`, `state`, `city` ou `address`.
   */
  kind: SignFormFieldKind;
  /** Limite de caracteres, de 1 a 2000. Zero usa o padrão do tipo. */
  max_len?: number;
  /** Nome, único entre os campos ativos da organização. Uma linha. */
  name: string;
  /**
   * O dado do cadastro de pessoas que preenche o campo: vazio ou `none`,
   * ou um dado da própria parte (`document`), de quem representa a
   * empresa da parte (`representative.document`) ou de um sócio dela
   * (`partner.document`).
   */
  profile?: SignFormProfileKey;
  /** Sem valor, o envelope não é criado. */
  required?: boolean;
  /** Tudo em maiúsculas. */
  uppercase?: boolean;
}

/** Um campo de formulário, na versão em vigor. */
export interface SignFieldDto {
  /** Quando foi arquivado. `null` enquanto ativo. */
  archived_at: string | null;
  /** Quando (RFC 3339). */
  created_at: string;
  /** Quem criou. */
  created_by: string;
  /** Descrição. */
  description: string;
  /** ID (Snowflake). */
  id: string;
  /** Tipo. */
  kind: SignFormFieldKind;
  /** Limite de caracteres. */
  max_len: number;
  /** Nome. */
  name: string;
  /** O dado do cadastro que preenche o campo (`none` quando nenhum). */
  profile: SignFormProfileKey;
  /** Obrigatório. */
  required: boolean;
  /** Quando (RFC 3339). */
  updated_at: string;
  /** Quem mudou por último. */
  updated_by: string;
  /** Tudo em maiúsculas. */
  uppercase: boolean;
  /** Versão em vigor. */
  version: number;
}

/** Corpo de `PUT /v1/sign/fields/{id}`. */
export interface SignFieldUpdateBody {
  /**
   * A versão que a pessoa editou. Outra em vigor é `409` com
   * `sign_field_changed`.
   */
  expected_version: number;
  /** O conteúdo novo. */
  field: SignFieldBody;
}

/** O valor que quem assina deu a um campo dele. */
export interface SignFieldValueDto {
  /** O número do campo no convite. */
  number: number;
  /** O texto digitado. O serviço confere pelo tipo do campo. */
  value: string;
}

/** Página de campos. */
export interface SignFieldsPageDto {
  /** Os campos da página, do mais novo para o mais antigo. */
  fields: SignFieldDto[];
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
}

/** O conteúdo de um formulário: partes, caixas e valores padrão. */
export interface SignFormBody {
  /** Valores padrão, só da parte `own` e de campo com caixa nela. */
  defaults?: SignFormValueDto[];
  /** Nome, único entre os formulários ativos da organização. */
  name: string;
  /** As partes, de 1 a 6. */
  parties: SignFormPartyDto[];
  /** As caixas, até 300. Um campo pode ter várias. */
  slots?: SignFormSlotDto[];
}

/**
 * O quadro de uma caixa, nas unidades do selo: décimos de milésimo da
 * página, a partir do canto de cima à esquerda. Menor que o do selo: a
 * caixa é uma linha em branco do documento.
 */
export interface SignFormBoxDto {
  /** Altura. */
  h: number;
  /** A página, a partir de 1. */
  page: number;
  /** Largura. */
  w: number;
  /** Distância da borda esquerda. */
  x: number;
  /** Distância da borda de cima. */
  y: number;
}

/** Um formulário com os campos que as caixas dele usam. */
export interface SignFormDetailDto {
  /** Os campos das caixas, arquivados inclusive. */
  fields: SignFieldDto[];
  /** O formulário. */
  form: SignFormDto;
}

/** Um formulário, na versão em vigor. */
export interface SignFormDto {
  /** Quando foi arquivado. `null` enquanto ativo. */
  archived_at: string | null;
  /** Quando (RFC 3339). */
  created_at: string;
  /** Quem criou. */
  created_by: string;
  /** Os valores padrão da parte `own`. */
  defaults: SignFormValueDto[];
  /** Nome do PDF em branco. */
  document_name: string;
  /** SHA-256 (hex) do PDF em branco. */
  document_sha256: string;
  /** Tamanho do PDF em branco. */
  document_size: number;
  /** ID (Snowflake). */
  id: string;
  /** Nome. */
  name: string;
  /** Páginas. */
  page_count: number;
  /** As partes. */
  parties: SignFormPartyDto[];
  /** As caixas. */
  slots: SignFormSlotDto[];
  /** Quando (RFC 3339). */
  updated_at: string;
  /** Quem mudou por último. */
  updated_by: string;
  /** Versão em vigor. */
  version: number;
}

/** Tipo de um campo do catálogo de formulários: só documenta os valores, o fio é texto. */
export type SignFormFieldKind = "text" | "multiline" | "name" | "date" | "number" | "document" | "email" | "phone" | "postal_code" | "country" | "state" | "city" | "address";

/**
 * O campo `meta` do multipart de `POST /v1/sign/forms`: o conteúdo e o
 * tamanho do PDF em branco.
 */
export interface SignFormMeta {
  /** Tamanho do PDF em bytes, como o cliente o tem. */
  document_size: number;
  /** O conteúdo. */
  form: SignFormBody;
}

/** Uma parte do formulário ("Contratada", "Contratante"). */
export interface SignFormPartyDto {
  /**
   * `own` (a própria organização, no máximo uma) ou `person` (uma pessoa
   * do cadastro, escolhida no envio).
   */
  kind: SignFormPartyKind;
  /** Nome, até 60 caracteres, único no formulário. */
  name: string;
}

/** Parte de um formulário: só documenta os valores, o fio é texto. */
export type SignFormPartyKind = "own" | "person";

/** Quem assina por uma parte `person`. */
export interface SignFormPartySignerDto {
  /** A parte, pela posição em `parties`. */
  party: number;
  /** A posição em `signers`, a partir de 0. Cópia não preenche. */
  signer: number;
}

/** A pessoa do cadastro escolhida para uma parte `person`. */
export interface SignFormPickDto {
  /** A parte, pela posição em `parties`. */
  party: number;
  /** A pessoa (Snowflake). */
  person_id: string;
}

/**
 * Dado do cadastro de pessoas que preenche um campo: só documenta os valores, o fio é texto.
 * Sem prefixo é da própria parte; `representative.` é de quem representa a empresa da parte e `partner.`
 * de um sócio dela.
 */
export type SignFormProfileKey = "none" | "name" | "legal_name" | "trade_name" | "document" | "birth_date" | "marital_status" | "email" | "phone" | "postal_code" | "street" | "number" | "complement" | "neighborhood" | "city" | "state" | "country" | "address" | "representative.name" | "representative.legal_name" | "representative.trade_name" | "representative.document" | "representative.birth_date" | "representative.marital_status" | "representative.email" | "representative.phone" | "representative.postal_code" | "representative.street" | "representative.number" | "representative.complement" | "representative.neighborhood" | "representative.city" | "representative.state" | "representative.country" | "representative.address" | "partner.name" | "partner.legal_name" | "partner.trade_name" | "partner.document" | "partner.birth_date" | "partner.marital_status" | "partner.email" | "partner.phone" | "partner.postal_code" | "partner.street" | "partner.number" | "partner.complement" | "partner.neighborhood" | "partner.city" | "partner.state" | "partner.country" | "partner.address";

/** Uma caixa: onde um campo de uma parte é escrito. */
export interface SignFormSlotDto {
  /** Onde. */
  area: SignFormBoxDto;
  /** O campo (Snowflake). */
  field_id: string;
  /** A parte, pela posição em `parties` (a partir de 0). */
  party: number;
}

/** Corpo de `PUT /v1/sign/forms/{id}`. O PDF em branco não muda. */
export interface SignFormUpdateBody {
  /**
   * A versão que a pessoa editou. Outra em vigor é `409` com
   * `sign_form_changed`.
   */
  expected_version: number;
  /** O conteúdo novo. */
  form: SignFormBody;
}

/** Um valor de um campo numa parte. */
export interface SignFormValueDto {
  /** O campo (Snowflake). */
  field_id: string;
  /**
   * `profile` (veio do cadastro), `typed` (digitado) ou vazio. Só vai à
   * cadeia do envelope.
   */
  origin?: string;
  /** A parte, pela posição em `parties`. */
  party: number;
  /** O valor, até 2000 caracteres. */
  value: string;
}

/** Página de formulários. */
export interface SignFormsPageDto {
  /** Os formulários da página, do mais novo para o mais antigo. */
  forms: SignFormDto[];
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
}

/**
 * Corpo de `POST /v1/sign/forms/{id}/envelopes`: o envelope sem o PDF, a
 * pessoa de cada parte e os valores.
 */
export interface SignFromFormBody {
  /** Nome do arquivo. Vazio usa o do PDF em branco. */
  document_name?: string;
  /** Dias até vencer, de 1 a 90. Zero usa o dos ajustes. */
  expires_in_days?: number;
  /**
   * A versão que a pessoa viu. Outra em vigor é `409` com
   * `sign_form_changed`. Ausente aceita a versão em vigor.
   */
  form_version?: number | null;
  /** `platform` ou `own`. Vazio usa o dos ajustes. */
  mail_sender?: SignMailSender;
  /** Mensagem que vai no convite. Opcional. */
  message?: string;
  /** `parallel` (padrão) ou `sequential`. */
  order?: SignSigningOrder;
  /** Módulo que pediu a assinatura (`hr`, `sales`). Opcional. */
  origin_kind?: string;
  /** Registro de origem naquele módulo. Opcional. */
  origin_ref?: string;
  /**
   * Quem assina por cada parte `person`. O campo da parte
   * deixado sem valor fica para esta pessoa preencher ao assinar; o
   * obrigatório vazio só é recusado quando a parte não tem quem assine.
   */
  party_signers?: SignFormPartySignerDto[];
  /** A pessoa de cada parte `person`. */
  picks?: SignFormPickDto[];
  /**
   * `fz-link-v1`, `fz-email-otp-v1`, `fz-passkey-v1` ou `fz-icp-v1`.
   * Vazio usa a dos ajustes.
   */
  policy?: SignAuthPolicy;
  reminders?: SignReminderPlanDto | null;
  /**
   * Quem cria declara que o documento não é dos tipos que o serviço não
   * cobre. Sem isto o serviço recusa (`sign_scope_not_confirmed`).
   */
  scope_confirmed?: boolean;
  /** `true` envia na mesma chamada; `false` deixa em rascunho. */
  send?: boolean;
  /** Quem pede a assinatura. Vazio usa o dos ajustes da organização. */
  sender_name?: string;
  /** Quem assina, na ordem, com o quadro do selo de cada um. */
  signers: SignSignerInput[];
  /** Título do envelope. Vazio usa o nome do formulário. */
  title?: string;
  /** Um valor por parte e campo. Vazio na parte `own` usa o padrão. */
  values?: SignFormValueDto[];
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id?: string;
  /**
   * `true` manda o convite e os lembretes só por e-mail.
   * Por padrão saem também por WhatsApp a quem tem telefone.
   */
  whatsapp_off?: boolean;
}

/**
 * Corpo de `POST /v1/sign/envelopes/from-template`: o envelope sem o PDF,
 * o modelo e os valores.
 */
export interface SignFromTemplateBody {
  /** Nome do arquivo. Vazio usa o nome do modelo. */
  document_name?: string;
  /** Dias até vencer, de 1 a 90. Zero usa o dos ajustes. */
  expires_in_days?: number;
  /**
   * Por qual e-mail saem convite, lembrete, código e cópia final:
   * `platform` (o da Ferrazio) ou `own` (o remetente da organização no
   * Mailer). Vazio usa o dos ajustes. `own` sem remetente cadastrado é
   * `412` com `sign_mail_sender_not_configured`.
   */
  mail_sender?: SignMailSender;
  /** Mensagem que vai no convite. Opcional. */
  message?: string;
  /** `parallel` (padrão) ou `sequential`. */
  order?: SignSigningOrder;
  /** Módulo que pediu a assinatura (`hr`, `sales`). Opcional. */
  origin_kind?: string;
  /** Registro de origem naquele módulo. Opcional. */
  origin_ref?: string;
  /**
   * `fz-link-v1`, `fz-email-otp-v1`, `fz-passkey-v1` ou `fz-icp-v1`.
   * Vazio usa a dos ajustes.
   */
  policy?: SignAuthPolicy;
  reminders?: SignReminderPlanDto | null;
  /**
   * Quem cria declara que o documento não é dos tipos que o serviço não
   * cobre. Sem isto o serviço recusa (`sign_scope_not_confirmed`).
   */
  scope_confirmed?: boolean;
  /** `true` envia na mesma chamada; `false` deixa em rascunho. */
  send?: boolean;
  /** Quem pede a assinatura. Vazio usa o dos ajustes da organização. */
  sender_name?: string;
  /**
   * Quem assina, na ordem. O quadro do selo de quem não trouxe um vai na
   * vaga de assinatura da pessoa, no fim do documento.
   */
  signers: SignSignerInput[];
  /** O modelo (Snowflake). */
  template_id: string;
  /**
   * A versão que a pessoa viu. Outra em vigor é `409` com
   * `sign_template_changed`. Ausente aceita a versão em vigor.
   */
  template_version?: number | null;
  /** Título do envelope. Vazio usa o título preenchido do modelo. */
  title?: string;
  /** Valor de cada campo, pela chave. */
  values?: Record<string, string>;
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id?: string;
  /**
   * `true` manda o convite e os lembretes só por e-mail.
   * Por padrão saem também por WhatsApp a quem tem telefone.
   */
  whatsapp_off?: boolean;
}

/** O pareamento com o agente local aberto. */
export interface SignIcpAgentBegunDto {
  /** O código que a pessoa digita no agente (`XXXX-XXXX-XXXX`). */
  code: string;
  /** Quanto tempo o código serve para o agente entrar. */
  code_expires_in_seconds: number;
  /** Quanto tempo o pareamento vive. */
  expires_in_seconds: number;
  /** O pareamento, a mandar em `status` e `request`. */
  pairing_id: string;
}

/**
 * Um certificado que o agente ofereceu, com o que a pessoa precisa para
 * escolher.
 */
export interface SignIcpAgentCertificateDto {
  /** O certificado, em DER, em base64: vai em `certificate` ao preparar. */
  certificate: string;
  /** As ACs que vieram com ele, em DER, em base64: vão em `chain`. */
  chain: string[];
  /** O CPF, mascarado. */
  cpf_masked: string;
  /** `e-cpf` ou `e-cnpj`. */
  holder: SignIcpHolder;
  /** A AC que emitiu. */
  issuer: string;
  /** O nome que o certificado afirma. */
  name: string;
  /** Fim da validade, RFC 3339. */
  not_after: string;
}

/** Corpo de `POST /v1/sign/public/invite/icp/agent/request`. */
export interface SignIcpAgentRequestBody {
  /** O `pairing_id` que a abertura devolveu. */
  pairing_id: string;
  /** A preparação feita com um dos certificados que o agente ofereceu. */
  preparation_id: string;
}

/** O pareamento como a página acompanha. */
export interface SignIcpAgentStateDto {
  /** O que o agente diz de si, depois de entrar. */
  agent: string;
  /** Os certificados oferecidos. */
  certificates: SignIcpAgentCertificateDto[];
  /** Quanto tempo resta ao pareamento. */
  expires_in_seconds: number;
  /** A preparação cuja assinatura foi pedida. */
  preparation_id: string;
  /**
   * A assinatura em base64, no passo `signed`: vai em `icp.signature`
   * ao assinar.
   */
  signature: string;
  /** `waiting`, `paired`, `requested`, `signed` ou `closed`. */
  state: SignIcpAgentStep;
}

/** Corpo de `POST /v1/sign/public/invite/icp/agent/status`. */
export interface SignIcpAgentStatusBody {
  /** O `pairing_id` que a abertura devolveu. */
  pairing_id: string;
}

/** Passo do pareamento com o agente local da ICP-Brasil: só documenta os valores, o fio é texto. */
export type SignIcpAgentStep = "waiting" | "paired" | "requested" | "signed" | "closed";

/** Como a chave do certificado ICP-Brasil assina: só documenta os valores, o fio é texto. */
export type SignIcpAlgorithm = "rsa-pkcs1-sha256" | "ecdsa-p256-sha256";

/** Titular do certificado ICP-Brasil: só documenta os valores, o fio é texto. */
export type SignIcpHolder = "e-cpf" | "e-cnpj";

/** Corpo de `POST /v1/sign/public/invite/icp/prepare`. */
export interface SignIcpPrepareBody {
  /** O certificado de quem assina, em DER, em base64. */
  certificate: string;
  /**
   * As ACs que o navegador tem (do PFX), em DER, em base64, em qualquer
   * ordem. Até seis; as que faltarem o serviço completa pelas que conhece.
   */
  chain?: string[];
  stamp?: SignStampDto | null;
}

/** A preparação da assinatura ICP-Brasil. */
export interface SignIcpPreparedDto {
  /** `rsa-pkcs1-sha256` ou `ecdsa-p256-sha256`. */
  algorithm: SignIcpAlgorithm;
  /** O CPF do certificado, mascarado. */
  cpf_masked: string;
  /** Quanto tempo a preparação vale. */
  expires_in_seconds: number;
  /** `e-cpf` ou `e-cnpj`. */
  holder: SignIcpHolder;
  /** A AC que emitiu o certificado. */
  issuer: string;
  /** O nome que o certificado afirma (o responsável, no e-CNPJ). */
  name: string;
  /** A devolver em `icp.preparation_id` ao assinar. */
  preparation_id: string;
  /**
   * O SET dos atributos assinados, em DER, em base64: é o que a chave
   * privada assina.
   */
  signed_attrs: string;
}

/** A assinatura ICP-Brasil ao assinar. */
export interface SignIcpSignatureDto {
  /** O `preparation_id` que a preparação devolveu. */
  preparation_id: string;
  /**
   * A assinatura dos `signed_attrs` em base64: PKCS#1 v1.5 com SHA-256
   * (RSA) ou ECDSA P-256 com SHA-256 em DER, conforme o `algorithm`.
   */
  signature: string;
}

/**
 * Um documento importado: o contrato assinado fora da Ferrazio, guardado
 * num cofre. Partes, data e observação são o que quem importou declarou; o
 * que a plataforma garante é que o arquivo é o mesmo desde a entrada.
 */
export interface SignImportDto {
  /** Quando (RFC 3339). */
  created_at: string;
  /** Quem importou (`user:<id>`). */
  created_by: string;
  /** Nome do arquivo. */
  document_name: string;
  /** SHA-256 gravado na entrada (hex), conferido a cada download. */
  document_sha256: string;
  /** Bytes. */
  document_size: number;
  /** ID (Snowflake). */
  id: string;
  /** Observação. */
  note: string;
  /** Páginas. */
  pages: number;
  /** As partes. */
  parties: SignImportPartyDto[];
  /** O dia da assinatura (`AAAA-MM-DD`). `null`: não informado. */
  signed_on: string | null;
  /** Título. */
  title: string;
  /** O cofre em que mora. */
  vault_id: string;
}

/**
 * O campo `meta` do multipart de `POST /v1/sign/imports`: tudo do documento
 * importado menos os bytes do PDF.
 */
export interface SignImportMeta {
  /** Tamanho do PDF em bytes, como o cliente o tem. */
  document_size: number;
  /** Observação, até 1000 caracteres. Opcional. */
  note?: string;
  /** As partes, até 20, sem repetir o mesmo CPF ou CNPJ. Opcional. */
  parties?: SignImportPartyInput[];
  /**
   * O dia em que foi assinado (`AAAA-MM-DD`), nunca depois de hoje.
   * Opcional.
   */
  signed_on?: string;
  /** Título, como aparece na lista do cofre. */
  title: string;
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id?: string;
}

/** Uma parte de um documento importado. */
export interface SignImportPartyDto {
  /** CPF ou CNPJ só com os caracteres que contam. Vazio: não informado. */
  document: string;
  /** Nome. */
  name: string;
}

/** Uma parte de um documento importado, como quem importa declara. */
export interface SignImportPartyInput {
  /** CPF ou CNPJ, com ou sem máscara. Opcional. */
  document?: string;
  /** Nome da pessoa ou da empresa. */
  name: string;
}

/** Uma página de documentos importados. */
export interface SignImportsPageDto {
  /** Os documentos da página. */
  imports: SignImportDto[];
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
}

/** O que o signatário vê ao abrir o link. */
export interface SignInviteDto {
  /** `true` quando esta pessoa pode assinar agora. */
  can_sign: boolean;
  /**
   * `true` quando o documento completo (o assinado com o certificado no
   * fim) já pode ser baixado por este link (`?complete=true`).
   */
  complete_ready: boolean;
  /** `true` quando o remetente informou o CPF esperado. */
  cpf_expected: boolean;
  /** Nome do arquivo. */
  document_name: string;
  /** SHA-256 do PDF, em hex. */
  document_sha256: string;
  /** Tamanho do PDF em bytes. */
  document_size: number;
  /** O e-mail que recebe o código, mascarado (`a***@dominio.com`). */
  email_masked: string;
  /** Id do envelope (Snowflake). */
  envelope_id: string;
  /** Estado do envelope. */
  envelope_status: SignEnvelopeStatus;
  /** Vencimento (RFC 3339). */
  expires_at: string | null;
  /**
   * Os campos que esta pessoa preenche ao assinar. Os
   * valores vão em `fields` no `POST /v1/sign/public/invite/sign`; com um
   * obrigatório sem valor, assinar responde `sign_fields_pending`.
   */
  fields: SignSignerFieldDto[];
  /**
   * As rubricas desta pessoa. Com alguma pendente, assinar
   * responde `sign_marks_pending`: aceite todas juntas
   * (`POST /v1/sign/public/invite/marks` com `group: "initials"`).
   */
  marks: SignMarkDto[];
  /** Mensagem do remetente. */
  message: string;
  /**
   * Nome com que a organização que enviou está cadastrada. Vem do cadastro,
   * não do pedido, e aparece ao lado de `sender_name`. Vazio em envelope
   * criado antes de o nome ser guardado.
   */
  organization_name: string;
  /** `true` quando o pacote já pode ser baixado por este link. */
  package_ready: boolean;
  /** Os outros signatários. */
  peers: SignInvitePeerDto[];
  /** Política de autenticação do envelope. */
  policy: SignAuthPolicy;
  /** `true` quando a política pede o código e o CPF. */
  requires_code: boolean;
  /**
   * `true` quando a política pede o certificado ICP-Brasil do signatário
   * (`fz-icp-v1`): a página prepara em `.../icp/prepare` e assina com a
   * chave do certificado.
   */
  requires_icp: boolean;
  /**
   * `true` quando a política pede a passkey da conta do e-mail
   * (`fz-passkey-v1`).
   */
  requires_passkey: boolean;
  /** Quem pede a assinatura. */
  sender_name: string;
  /** Quando esta pessoa assinou (RFC 3339). `null` se ainda não. */
  signed_at: string | null;
  /**
   * `true` quando o documento assinado já pode ser baixado por este link
   * (`GET /v1/sign/public/invite/document?signed=true`).
   */
  signed_ready: boolean;
  /** Nome do signatário dono deste link. */
  signer_name: string;
  /** Papel dele. */
  signer_role: SignSignerRole;
  /** `pending`, `signed` ou `declined`. */
  signer_status: SignSignerStatus;
  stamp: SignStampDto | null;
  /** Texto do termo. */
  terms_text: string;
  /** Versão do termo que a pessoa aceita ao assinar. */
  terms_version: string;
  /** Título. */
  title: string;
  /** Código do verificador. */
  verify_code: string;
}

/**
 * Outro signatário do mesmo envelope, como a página do convite o mostra: sem
 * e-mail nem CPF.
 */
export interface SignInvitePeerDto {
  /** Nome. */
  name: string;
  /** Papel. */
  role: SignSignerRole;
  /** `pending`, `signed` ou `declined`. */
  status: SignSignerStatus;
}

/** Corpo de `POST /v1/sign/public/mail/opened`. */
export interface SignMailOpenBody {
  /** A marca da imagem do e-mail (64 hex). Não abre o convite. */
  mark?: string;
}

/** Remetente dos e-mails do envelope: só documenta os valores, o fio é texto. */
export type SignMailSender = "platform" | "own";

/** Um quadro extra de quem assina, com o aceite quando houve. */
export interface SignMarkDto {
  /** Quando a pessoa aceitou (RFC 3339). `null` enquanto não. */
  accepted_at: string | null;
  /**
   * `initials` (todas as rubricas) ou, só em aceite gravado antes de
   * 15/10/2026, `each`, `signatures` ou `all`. Vazio enquanto não.
   */
  accepted_mode: string;
  box: SignStampDto | null;
  /** `initials`, ou `signature` em quadro gravado antes de 15/10/2026. */
  kind: SignStoredMarkKind;
  /** Número na pessoa, a partir de 1. */
  number: number;
}

/** Um quadro extra de quem assina, como quem cria o informa. */
export interface SignMarkInputDto {
  /** O quadro, nas mesmas regras do selo. */
  box: SignStampDto;
  /** `initials` (rubrica), o único tipo. */
  kind: SignMarkKind;
}

/**
 * O tipo de um quadro extra. Só a rubrica: a assinatura extra saiu em
 * 15/10/2026 (uma assinatura por pessoa).
 */
export type SignMarkKind = "initials";

/**
 * O grupo de quadros aceito num clique só. Só as rubricas: a assinatura
 * extra, que se aceitava uma a uma ou em grupo, saiu em 15/10/2026.
 */
export type SignMarksGroup = "initials";

/** Corpo de `POST /v1/sign/envelopes/{id}/move`. */
export interface SignMoveBody {
  /** O cofre de destino (Snowflake). */
  vault_id: string;
}

/** Uma página do documento. */
export interface SignPageDto {
  /** Altura como aparece, em pontos. */
  height: number;
  image: SignPageImageDto | null;
  /** Número da página (base 1). */
  page: number;
  /** Largura como aparece (girada pelo `Rotate`), em pontos. */
  width: number;
}

/** A imagem de uma página. */
export interface SignPageImageDto {
  /** `image/png`. */
  content_type: string;
  /** Os bytes da imagem, em base64. */
  data: string;
  /** Altura em pixels. */
  height_px: number;
  /** Largura em pixels (o lado maior tem até 1024). */
  width_px: number;
}

/** Resposta de `POST /v1/sign/pages`. */
export interface SignPagesDto {
  /** Total de páginas do documento. */
  page_count: number;
  /** Todas as páginas, na ordem, com tamanho; imagem só nas pedidas. */
  pages: SignPageDto[];
}

/** Campo `meta` de `POST /v1/sign/pages`. */
export interface SignPagesMeta {
  /**
   * Tamanho do PDF no campo `file`, em bytes. Com `template_id`, `0` (e o
   * `file` vazio).
   */
  document_size?: number;
  /** Primeira página com imagem (base 1). Padrão 1. */
  first_page?: number | null;
  /** Quantas páginas desenhar a partir de `first_page`, até 10. Padrão 10. */
  page_limit?: number | null;
  /** Com `template_id`: quem ganha vaga de assinatura, na ordem. */
  signers?: SignPreviewSignerDto[];
  /** Desenhar o PDF que este modelo gera, em vez do `file`. */
  template_id?: string | null;
  /** Com `template_id`: o valor de cada campo, pela chave. */
  values?: Record<string, string>;
}

/** A asserção da passkey ao assinar. */
export interface SignPasskeyAssertionDto {
  /** O `ceremony_id` que a abertura devolveu. */
  ceremony_id: string;
  /**
   * O `PublicKeyCredential` de `navigator.credentials.get`, em JSON
   * (`toJSON`), com os campos binários em base64url.
   */
  credential: Record<string, unknown>;
  /** O `nonce` que a abertura devolveu (64 caracteres hex). */
  nonce: string;
}

/** Resposta da abertura da cerimônia de passkey. */
export interface SignPasskeyStartedDto {
  /** A cerimônia, a devolver ao assinar. */
  ceremony_id: string;
  /** O sorteio do desafio, a devolver ao assinar. */
  nonce: string;
  /**
   * As opções para `navigator.credentials.get` (`publicKey`), com os
   * campos binários em base64url.
   */
  options: Record<string, unknown>;
}

/** Uma pessoa na prévia: só nome e papel contam. */
export interface SignPreviewSignerDto {
  /** Nome. Vazio vira "Signatário N". */
  name?: string;
  /** `signer` (padrão), `witness`, `approver` ou `copy` (não ganha vaga). */
  role?: SignSignerRole;
}

/**
 * Um documento recebido de outra organização: a cópia de
 * leitura do envelope de quem enviou, vista por quem assinou nesta
 * organização.
 */
export interface SignReceivedDto {
  /**
   * O documento completo (o assinado com o certificado no fim) pode ser
   * baixado (`?complete=true`).
   */
  complete_ready: boolean;
  /** Quando o envelope foi concluído (RFC 3339). */
  completed_at: string | null;
  /** Nome do PDF original. */
  document_name: string;
  /** SHA-256 do PDF original, em hex. */
  document_sha256: string;
  /** Tamanho do PDF original, em bytes. */
  document_size: number;
  /** Id do envelope de quem enviou. */
  envelope_id: string;
  /** Estado do envelope (`completed`). */
  envelope_status: SignEnvelopeStatus;
  /** Id da cópia (Snowflake). É o id das rotas `/v1/sign/received/{id}`. */
  id: string;
  /** Quando a cópia foi guardada (RFC 3339). */
  kept_at: string;
  /** Quem guardou (`user:<id>`). */
  kept_by: string;
  /** Nome com que a organização que enviou está cadastrada. */
  organization_name: string;
  /** O pacote de evidências já pode ser baixado. */
  package_ready: boolean;
  /** Os outros participantes, sem e-mail nem CPF. */
  peers: SignInvitePeerDto[];
  /** Política de autenticação de quem assinou. */
  policy: SignAuthPolicy;
  /** Quem pediu a assinatura. */
  sender_name: string;
  /** Quando ela assinou (RFC 3339; `null` para quem só recebeu cópia). */
  signed_at: string | null;
  /** O documento assinado (com os selos visuais) pode ser baixado. */
  signed_ready: boolean;
  /** O e-mail do convite dessa pessoa. */
  signer_email: string;
  /** Quem desta organização assinou. */
  signer_name: string;
  /** O papel dela. */
  signer_role: SignSignerRole;
  /** O estado dela. */
  signer_status: SignSignerStatus;
  /** Título. */
  title: string;
  /** O cofre. Vazio é o cofre padrão da organização. */
  vault_id: string;
  /** Código do verificador público. */
  verify_code: string;
}

/** Página de documentos recebidos. */
export interface SignReceivedPageDto {
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
  /** As cópias da página, da mais nova para a mais antiga. */
  received: SignReceivedDto[];
}

/**
 * Que lembrete automático sai a seguir: só documenta os
 * valores, o fio é texto.
 */
export type SignReminderKind = "step" | "deadline";

/**
 * O plano dos lembretes automáticos de um envelope. O
 * envelope congela o plano ao nascer: mudar os ajustes não mexe em envelope
 * já criado.
 */
export interface SignReminderPlanDto {
  /**
   * Horas antes do vencimento em que sai o aviso de que o prazo está
   * acabando, para quem ainda não assinou (abrir não o cancela). Zero
   * desliga.
   */
  before_deadline_hours?: number;
  /**
   * Horas depois do convite (ou da prorrogação) em que o convite sai de
   * novo para quem não abriu: até 5, em ordem crescente, de 1 a 2160.
   * Vazio desliga o reenvio.
   */
  hours?: number[];
}

/** Uma chave de selo, em forma de JWK (`OKP`, `Ed25519`). */
export interface SignSealKeyDto {
  /**
   * Quando a declaração foi feita (RFC 3339). `null` junto com
   * `compromised_at`.
   */
  compromise_declared_at: string | null;
  /**
   * A partir de quando a chave foi declarada comprometida (RFC 3339).
   * `null` nas chaves de `keys`; preenchido nas de `compromised`.
   */
  compromised_at: string | null;
  /** Quando a chave passou a selar (RFC 3339). */
  created_at: string;
  /** Sempre `Ed25519`. */
  crv: string;
  /** SHA-256 da chave pública, em hex. */
  fingerprint: string;
  /** Identificador da chave, o mesmo do manifesto. */
  kid: string;
  /** Sempre `OKP`. */
  kty: string;
  /** Quando foi aposentada (RFC 3339). `null` na chave que sela agora. */
  retired_at: string | null;
  /** A chave pública: 32 bytes em base64url sem preenchimento. */
  x: string;
}

/** As chaves de selo, em forma de JWKS. */
export interface SignSealKeysDto {
  /**
   * As chaves declaradas comprometidas. Ficam fora de `keys` de propósito:
   * quem lê só `keys` deixa de confiar nelas sem conhecer este campo. Um
   * pacote selado por uma delas não prova a origem sozinho; quem responde
   * por ele é o verificador por código.
   */
  compromised: SignSealKeyDto[];
  /**
   * As chaves em que se confia, inclusive as aposentadas: um pacote antigo
   * confere contra a chave que o selou.
   */
  keys: SignSealKeyDto[];
}

/** Ajustes do Assinador da organização (`PUT /v1/sign/settings`). */
export interface SignSettingsBody {
  /** Dias até o envelope vencer, de 1 a 90. */
  default_expiry_days: number;
  /**
   * Política que vale quando o envelope não escolhe: `fz-link-v1`,
   * `fz-email-otp-v1`, `fz-passkey-v1` ou `fz-icp-v1`.
   */
  default_policy: SignAuthPolicy;
  /**
   * Remetente padrão dos e-mails do envelope novo: `platform` (o da
   * Ferrazio, padrão quando vazio) ou `own` (o da organização no Mailer).
   * `own` sem remetente cadastrado é `412` com
   * `sign_mail_sender_not_configured`.
   */
  mail_sender?: SignMailSender;
  reminders?: SignReminderPlanDto | null;
  /** Anos de guarda do envelope concluído, de 1 a 20. */
  retention_years: number;
  /** Nome de quem envia, como aparece no convite. */
  sender_name?: string;
}

/** Ajustes do Assinador da organização. */
export interface SignSettingsDto {
  /** Dias até vencer, por padrão. */
  default_expiry_days: number;
  /** Política padrão. */
  default_policy: SignAuthPolicy;
  /** Remetente padrão dos e-mails: `platform` ou `own`. */
  mail_sender: SignMailSender;
  /** O plano de lembretes que o envelope novo herda. */
  reminders: SignReminderPlanDto;
  /** Anos de guarda do envelope concluído. */
  retention_years: number;
  /** Nome de quem envia. */
  sender_name: string;
}

/** Corpo de `POST /v1/sign/public/invite/sign`. */
export interface SignSignatureBody {
  /**
   * Aceite do termo de assinatura. Sem ele o serviço recusa
   * (`sign_terms_not_accepted`).
   */
  accept_terms: boolean;
  /** O código de 6 dígitos recebido por e-mail, na política com código. */
  code?: string;
  /** CPF de quem assina. Exigido na política com código. */
  cpf?: string;
  /**
   * Os valores dos campos desta pessoa, um por `number`
   * de `fields` do convite. Opcional em branco pode faltar.
   */
  fields?: SignFieldValueDto[];
  icp?: SignIcpSignatureDto | null;
  /** O nome que a pessoa digita ao assinar. */
  name: string;
  passkey?: SignPasskeyAssertionDto | null;
  stamp?: SignStampDto | null;
  /** Versão do termo que a página mostrou. */
  terms_version: string;
}

/** Um signatário do envelope, como o remetente o vê. */
export interface SignSignerDto {
  /** Quantos passos do plano de lembretes já saíram (até 5). */
  auto_reminders: number;
  /** `true` quando é a vez desta pessoa. */
  can_sign_now: boolean;
  /**
   * Quando o link de cópia em vigor saiu (RFC 3339): no selo, ou na última
   * reemissão. `null` enquanto o envelope não foi selado.
   */
  copy_issued_at: string | null;
  /** Quantas vezes quem enviou reemitiu a cópia. */
  copy_reissues: number;
  /** CPF mascarado de quem assinou (`***.982.247-**`). Vazio antes disso. */
  cpf_masked: string;
  /**
   * O vencimento para o qual o aviso de prazo já saiu (RFC 3339). `null`
   * quando não saiu para nenhum.
   */
  deadline_reminder_for: string | null;
  /** O motivo da recusa, quando houve. */
  decline_reason: string;
  /** Quando recusou (RFC 3339). `null` se não recusou. */
  declined_at: string | null;
  /** E-mail que recebe o convite. */
  email: string;
  /**
   * Quando a imagem de um e-mail desta pessoa carregou pela primeira vez
   * (RFC 3339). Indício, não prova: há cliente de e-mail
   * que baixa a imagem sozinho. `null` quando nenhuma carregou.
   */
  email_opened_at: string | null;
  /**
   * Os campos que esta pessoa preenche ao assinar, com o
   * valor depois que assinou.
   */
  fields: SignSignerFieldDto[];
  /** Id do signatário (Snowflake). */
  id: string;
  /**
   * O motivo da devolução, como o servidor do destinatário escreveu.
   * `null` quando não voltou.
   */
  invite_bounce_reason: string | null;
  /**
   * Quando o servidor de e-mail do destinatário devolveu o convite em vigor
   * (RFC 3339). `null` quando não voltou; o "Lembrar" sai na hora
   * enquanto estiver preenchido.
   */
  invite_bounced_at: string | null;
  /** Quantos convites e lembretes já saíram. */
  invite_count: number;
  /** Último convite ou lembrete enviado (RFC 3339). `null` se nenhum saiu. */
  last_invite_at: string | null;
  /** Os outros quadros da pessoa, com o aceite de cada um. */
  marks: SignMarkDto[];
  /** Nome informado por quem criou o envelope. */
  name: string;
  /**
   * Quando sai o próximo lembrete automático, passo do plano ou aviso de
   * prazo (RFC 3339). `null` quando não sai mais nenhum.
   */
  next_auto_reminder_at: string | null;
  next_auto_reminder_kind: SignReminderKind | null;
  /**
   * O WhatsApp da pessoa em E.164 (`+5511988887777`).
   * `null` sem telefone.
   */
  phone: string | null;
  /** Posição na ordem de assinatura, a partir de 1. */
  position: number;
  /** `signer`, `witness`, `approver` ou `copy`. */
  role: SignSignerRole;
  /** Quando assinou (RFC 3339). `null` se ainda não. */
  signed_at: string | null;
  stamp: SignStampDto | null;
  /** `pending`, `signed` ou `declined`. */
  status: SignSignerStatus;
  /** Primeira abertura do link (RFC 3339). `null` se nunca abriu. */
  viewed_at: string | null;
  viewed_channel: SignViewChannel | null;
  /**
   * As mensagens de WhatsApp desta pessoa, da mais antiga para a mais
   * nova. Vazio na listagem: só o detalhe traz.
   */
  whatsapp: SignWhatsappSendDto[];
}

/**
 * Um campo do formulário que ficou para esta pessoa preencher ao assinar
 * : quem enviou deixou vazio na parte dela.
 */
export interface SignSignerFieldDto {
  /** Onde o valor é escrito, uma caixa por lugar do campo no documento. */
  boxes: SignStampDto[];
  /** Quando preencheu (RFC 3339). `null` enquanto não. */
  filled_at: string | null;
  /** O tipo, que confere o valor. */
  kind: SignFormFieldKind;
  /** Limite de caracteres. */
  max_len: number;
  /** O nome do campo, como no cadastro. */
  name: string;
  /** Número na pessoa, a partir de 1. É o que vai em `fields` ao assinar. */
  number: number;
  /** Sem valor a pessoa não assina (`sign_fields_pending`). */
  required: boolean;
  /** O valor vai em maiúsculas. */
  uppercase: boolean;
  /** O valor já conferido. `null` enquanto não preenchido. */
  value: string | null;
}

/** Um signatário do envelope, como quem cria o informa. */
export interface SignSignerInput {
  /** E-mail que recebe o convite e o código. */
  email: string;
  /** Opcional. Quando vem, quem assina precisa digitar o mesmo CPF. */
  expected_cpf?: string;
  /**
   * Opcional: as rubricas da mesma pessoa, numeradas a
   * partir de 1 nesta ordem. Fixas: quem assina aceita todas juntas e não
   * move. Até 200 por pessoa e 600 por envelope; só para quem assina, e
   * nunca na política ICP-Brasil. Uma assinatura por pessoa: a assinatura
   * extra saiu em 15/10/2026.
   */
  marks?: SignMarkInputDto[];
  /** Nome de quem assina, como aparece no convite. */
  name: string;
  /**
   * Opcional: celular com DDI, ou com DDD para o Brasil.
   * Com ele o convite e os lembretes saem também por WhatsApp.
   */
  phone?: string;
  /** `signer` (padrão), `witness`, `approver` ou `copy` (só acompanha). */
  role?: SignSignerRole;
  stamp?: SignStampDto | null;
}

/** Papel de quem está no envelope: só documenta os valores, o fio é texto. */
export type SignSignerRole = "signer" | "witness" | "approver" | "copy";

/** Estado de quem assina: só documenta os valores, o fio é texto. */
export type SignSignerStatus = "pending" | "signed" | "declined";

/** Ordem de assinatura: só documenta os valores, o fio é texto. */
export type SignSigningOrder = "parallel" | "sequential";

/**
 * O quadro do selo visual, em décimos de milésimo da página como ela aparece
 * (a área visível, já girada), com a origem no canto superior esquerdo.
 * Largura mínima 1200, altura mínima 400, e o quadro inteiro dentro da
 * página: o serviço confere, e confere a página contra o documento.
 */
export interface SignStampDto {
  /** Altura. */
  h: number;
  /** A página, a partir de 1. */
  page: number;
  /** Largura. */
  w: number;
  /** Distância da borda esquerda. */
  x: number;
  /** Distância da borda de cima. */
  y: number;
}

/** Tipo de um quadro gravado (`signature` só antes de 15/10/2026): só documenta os valores, o fio é texto. */
export type SignStoredMarkKind = "signature" | "initials";

/**
 * O conteúdo de um modelo (`POST /v1/sign/templates` e a prévia do editor).
 *
 * `{{hoje}}` e `{{organizacao}}` o serviço preenche sozinho; linha que
 * começa com `# ` é cabeçalho. O texto volta normalizado: aspas curvas,
 * travessões, reticências e espaço duro viram os simples, e caractere que o
 * PDF não grava é recusado com o campo apontado.
 */
export interface SignTemplateBody {
  /** O texto, com lacunas. */
  body: string;
  /** Os campos, na ordem em que a tela os pede. */
  fields?: SignTemplateFieldDto[];
  /** Nome, único entre os modelos ativos da organização. */
  name: string;
  /** Título do documento, com lacunas. */
  title: string;
}

/** Corpo de `POST /v1/sign/templates/preview`: o que está no editor. */
export interface SignTemplateDraftPreviewBody {
  /** Quem ganha vaga de assinatura, na ordem. */
  signers?: SignPreviewSignerDto[];
  /** O conteúdo, sem gravar. */
  template: SignTemplateBody;
  /** Valores e pessoas, como na prévia de um modelo gravado. */
  values?: Record<string, string>;
}

/** Um modelo de documento, na versão em vigor. */
export interface SignTemplateDto {
  /** Quando foi arquivado. `null` enquanto ativo. */
  archived_at: string | null;
  /** O texto, com lacunas, já normalizado. */
  body: string;
  /** Quando (RFC 3339). */
  created_at: string;
  /** Quem criou. */
  created_by: string;
  /** Os campos. */
  fields: SignTemplateFieldDto[];
  /** ID (Snowflake). */
  id: string;
  /** Nome. */
  name: string;
  /** SHA-256 (hex) do conteúdo: o que a cadeia do envelope guarda. */
  sha256: string;
  /** Título do documento, com lacunas. */
  title: string;
  /** Quando (RFC 3339). */
  updated_at: string;
  /** Quem mudou por último. */
  updated_by: string;
  /** Versão em vigor: começa em 1 e sobe a cada mudança de conteúdo. */
  version: number;
}

/** Um campo de modelo de documento: o que preenche a lacuna `{{key}}`. */
export interface SignTemplateFieldDto {
  /** `[a-z][a-z0-9_]{0,39}`: o que vai entre as chaves no texto. */
  key: string;
  /** Nome do campo na tela. */
  label: string;
  /** Aceita várias linhas (não pode ir no título). */
  multiline?: boolean;
  /** Sem valor, o envelope não é criado. */
  required?: boolean;
}

/** Corpo de `POST /v1/sign/templates/{id}/preview`. */
export interface SignTemplatePreviewBody {
  /** Quem ganha vaga de assinatura, na ordem. */
  signers?: SignPreviewSignerDto[];
  /**
   * Valor de cada campo, pela chave. Lacuna sem valor aparece como
   * `[rótulo]`.
   */
  values?: Record<string, string>;
}

/** Corpo de `PUT /v1/sign/templates/{id}`: o conteúdo e a versão editada. */
export interface SignTemplateUpdateBody {
  /**
   * A versão que a pessoa editou. Se outra pessoa gravou no meio, `409`
   * com `sign_template_changed`, e nada se perde em silêncio.
   */
  expected_version: number;
  /** O conteúdo novo. */
  template: SignTemplateBody;
}

/** Página de modelos. */
export interface SignTemplatesPageDto {
  /** Cursor da próxima página. Vazio na última. */
  next_page_token: string;
  /** Os modelos da página, do mais novo para o mais antigo. */
  templates: SignTemplateDto[];
}

/** Quem entra num cofre: só documenta os valores, o fio é texto. */
export type SignVaultAudience = "organization" | "members";

/** Uma unidade, grupo ou time da organização. */
export interface SignVaultAudienceDto {
  /** O id (Snowflake). */
  id: string;
  /** `group`, `team` ou `unit`. */
  kind: SignVaultCircleKind;
  /** Quantas pessoas ativas alcança. */
  member_count: number;
  /** O nome. */
  name: string;
}

/** Os públicos achados. */
export interface SignVaultAudiencesDto {
  /** Até 20. */
  items: SignVaultAudienceDto[];
}

/** Corpo de `POST /v1/sign/vaults` e `PUT /v1/sign/vaults/{id}`. */
export interface SignVaultBody {
  /** `organization` (padrão) ou `members`. */
  audience?: SignVaultAudience;
  /** Os 6 dígitos do autenticador, quando `require_mfa` está sendo ligado. */
  code?: string;
  /** Descrição. Opcional. */
  description?: string;
  /** Nome, único na organização sem diferença de caixa. */
  name: string;
  /** Abrir pede o código do autenticador. */
  require_mfa?: boolean;
}

/** Tipo de círculo da organização que um cofre pode listar: só documenta os valores, o fio é texto. */
export type SignVaultCircleKind = "group" | "team" | "unit";

/** O cofre com a lista e o rastro (só para quem o administra). */
export interface SignVaultDetailDto {
  /** O rastro, do mais novo ao mais velho. Vazio para quem não administra. */
  events: SignVaultEventDto[];
  /** A lista. Vazia para quem não administra. */
  members: SignVaultMemberDto[];
  /** O cofre. */
  vault: SignVaultDto;
}

/** Um cofre do Assinador, como a pessoa o vê. */
export interface SignVaultDto {
  /**
   * `organization` (a organização entra; quem não está na lista vê só o
   * que criou) ou `members` (só a lista).
   */
  audience: SignVaultAudience;
  /** Criação (RFC 3339). */
  created_at: string;
  /** Quem criou (`user:<id>`). */
  created_by: string;
  /** Descrição. */
  description: string;
  /**
   * Quantos envelopes guarda; -1 para quem não vê todos ou com ele
   * trancado.
   */
  envelope_count: number;
  /** ID (Snowflake). */
  id: string;
  /** Quantos documentos importados guarda; -1 nas mesmas condições. */
  import_count: number;
  /**
   * O cofre padrão ("Contratos"): guarda o que veio sem cofre, nunca se
   * apaga.
   */
  is_default: boolean;
  /** Pede o código e não há abertura em vigor para a pessoa. */
  locked: boolean;
  /** Nome. */
  name: string;
  /** `all` (vê tudo do cofre) ou `own` (só o que criou). */
  reach: SignVaultReach;
  /** Abrir pede o código do autenticador. */
  require_mfa: boolean;
  /** Com `reach = all`: `reader`, `editor` ou `admin`; vazio com `own`. */
  role: SignVaultRoleOrEmpty;
  /** Até quando a abertura vale (RFC 3339). `null` sem abertura. */
  unlocked_until: string | null;
  /** Última mudança (RFC 3339). */
  updated_at: string;
}

/** Uma linha do rastro de um cofre. */
export interface SignVaultEventDto {
  /** Quem (`user:<id>`). */
  actor: string;
  /** Quando (RFC 3339). */
  at: string;
  /** O que mudou, em JSON. */
  detail: string;
  /** ID. */
  id: string;
  /**
   * `created`, `updated`, `deleted`, `member_put`, `member_removed`,
   * `unlocked`, `unlock_refused`, `locked`, `envelope_in`,
   * `envelope_out`, `document_imported`, `document_deleted`,
   * `document_in` ou `document_out`.
   */
  kind: SignVaultEventKind;
}

/** Linha do rastro de um cofre: só documenta os valores, o fio é texto. */
export type SignVaultEventKind = "created" | "updated" | "deleted" | "member_put" | "member_removed" | "unlocked" | "unlock_refused" | "locked" | "envelope_in" | "envelope_out" | "document_imported" | "document_deleted" | "document_in" | "document_out";

/** Corpo de `PUT /v1/sign/vaults/{id}/members`. */
export interface SignVaultMemberBody {
  /** `member`, `group`, `team` ou `unit`. */
  kind: SignVaultSubjectKind;
  /** `reader`, `editor` ou `admin`. */
  role: SignVaultRole;
  /** O id do sujeito (Snowflake). */
  subject_id: string;
}

/** Uma linha da lista de um cofre. */
export interface SignVaultMemberDto {
  /** Quando (RFC 3339). */
  granted_at: string;
  /** Quem incluiu (`user:<id>`). */
  granted_by: string;
  /** `member`, `group`, `team` ou `unit`. */
  kind: SignVaultSubjectKind;
  /** O nome quando entrou na lista. */
  label: string;
  /** `reader`, `editor` ou `admin`. */
  role: SignVaultRole;
  /** O id do sujeito (Snowflake). */
  subject_id: string;
}

/**
 * Uma abertura: o bilhete que o front guarda no cookie e mande de volta no
 * cabeçalho `X-Sign-Vault-Ticket`.
 */
export interface SignVaultOpeningDto {
  /** O bilhete. Sai só aqui, uma vez. */
  ticket: string;
  /** Até quando vale (RFC 3339). */
  until: string;
}

/** O que a pessoa alcança dos envelopes de um cofre: só documenta os valores, o fio é texto. */
export type SignVaultReach = "all" | "own";

/** Papel na lista de um cofre: só documenta os valores, o fio é texto. */
export type SignVaultRole = "reader" | "editor" | "admin";

/**
 * Papel de quem vê o cofre: só documenta os valores, o fio é
 * texto. Vazio quando o alcance é `own`.
 */
export type SignVaultRoleOrEmpty = "reader" | "editor" | "admin" | "";

/**
 * O cofre criado ou ajustado e, quando o segundo fator acaba de ser ligado
 * com um código, a abertura que ele deu.
 */
export type SignVaultSavedDto = SignVaultDetailDto & ({
  opening: SignVaultOpeningDto | null;
});

/** Tipo de sujeito na lista de um cofre: só documenta os valores, o fio é texto. */
export type SignVaultSubjectKind = "member" | "group" | "team" | "unit";

/** Corpo de `POST /v1/sign/vaults/{id}/unlock`. */
export interface SignVaultUnlockBody {
  /** Os 6 dígitos do autenticador. */
  code: string;
}

/** Os cofres que a pessoa vê. */
export interface SignVaultsDto {
  /** O padrão primeiro, depois por nome. */
  vaults: SignVaultDto[];
}

/**
 * Por onde a pessoa abriu a página: só documenta os valores,
 * o fio é texto.
 */
export type SignViewChannel = "email" | "whatsapp";

/** Por que a mensagem de WhatsApp saiu: só documenta os valores. */
export type SignWhatsappKind = "start" | "manual" | "auto" | "deadline";

/** O desfecho no Social: só documenta os valores. */
export type SignWhatsappOutcome = "pending" | "accepted" | "unknown" | "rejected";

/** Por que a mensagem de WhatsApp não saiu: só documenta os valores. */
export type SignWhatsappRejection = "recipient_unavailable" | "invalid_recipient" | "suppressed" | "quota_exhausted" | "connection_not_ready" | "connection_blocked" | "no_sender" | "unavailable" | "other";

/** Uma mensagem de WhatsApp do convite ou de um lembrete. */
export interface SignWhatsappSendDto {
  /** Tentativas feitas. */
  attempts: number;
  /** Quando entrou na fila (RFC 3339). */
  created_at: string;
  /** O tique de entrega (RFC 3339). `null` sem ele. */
  delivered_at: string | null;
  /** Id da mensagem na fila (Snowflake). */
  id: string;
  /** Por que saiu. */
  kind: SignWhatsappKind;
  outcome: SignWhatsappOutcome | null;
  /**
   * O tique de leitura (RFC 3339). Depende da privacidade de quem
   * recebe; `null` sem ele. Não para os lembretes.
   */
  read_at: string | null;
  rejection: SignWhatsappRejection | null;
  /** Quando o Social aceitou (RFC 3339). `null` antes. */
  sent_at: string | null;
  /** Onde está. */
  state: SignWhatsappState;
}

/** Onde a mensagem de WhatsApp está: só documenta os valores. */
export type SignWhatsappState = "pending" | "sent" | "rejected" | "dead" | "skipped";

/** Simulação do mês: Simples puro contra Simples com CBS pelo regime regular. */
export interface SimplesHybridSimulationDto {
  /** Anexo usado. */
  anexo: PaySimplesAnexo;
  /** Alíquota efetiva do DAS, em %. */
  das_rate: DecimalText;
  /** `true` acima do teto do Simples. */
  exceeds_limit: boolean;
  /** Crédito a mais que o cliente empresa toma no híbrido. */
  extra_b2b_credit: DecimalText;
  /** Imposto a mais no híbrido (negativo quando sai mais barato). */
  extra_tax: DecimalText;
  /** Faixa. */
  faixa: number;
  /** Simples com CBS por fora. */
  hybrid: SimplesRegimeOutcomeDto;
  /** Crédito de compras que sobra para o mês seguinte no híbrido. */
  hybrid_credit_carry: DecimalText;
  /** Parte de PIS e Cofins dentro do DAS, em % (tabela estimada). */
  pis_cofins_share: DecimalText;
  /** Simples puro. */
  pure: SimplesRegimeOutcomeDto;
  /** RBT12 usado. */
  rbt12: DecimalText;
}

/** Receita de um mês da janela. */
export interface SimplesMonthRevenueDto {
  /** Receita do mês (decimal). */
  amount: DecimalText;
  /** Primeiro dia do mês (`YYYY-MM-DD`). */
  month: string;
}

/** Faixa + alíquota efetiva do Simples Nacional (DTO de resposta). */
export interface SimplesRateDto {
  /** Anexo usado (`i`..`v`). */
  anexo: PaySimplesAnexo;
  /** Parcela a deduzir (R$). */
  deduction: DecimalText;
  /** Alíquota efetiva calculada (%). */
  effective_rate: DecimalText;
  /** `true` se RBT12 excede o sublimite do Simples (R$ 4.800.000). */
  exceeds_limit: boolean;
  /** Faixa (1..=6). */
  faixa: number;
  /** Alíquota nominal da faixa (%). */
  nominal_rate: DecimalText;
  /** RBT12 informado. */
  rbt12: DecimalText;
}

/** Resultado de um modo do simulador. */
export interface SimplesRegimeOutcomeDto {
  /** Crédito de CBS que o cliente empresa toma. */
  b2b_credit: DecimalText;
  /** CBS a recolher por fora (só no híbrido). */
  cbs_due: DecimalText;
  /** DAS do mês. */
  das: DecimalText;
  /** Total sobre a receita, em %. */
  effective_rate: DecimalText;
  /** Total de impostos do mês. */
  total: DecimalText;
}

/** Vigia do Simples de uma organização. */
export interface SimplesWatchDto {
  /** Faixa já avisada. */
  alerted_faixa: number | null;
  alerted_level: PaySimplesLevel | null;
  /** Dia da avaliação (`YYYY-MM-DD`). */
  as_of: string;
  /** Teto do Simples (R$ 4.800.000). */
  ceiling: DecimalText;
  /** Mês previsto do cruzamento do próximo limite (`YYYY-MM-DD`). */
  crossing_month: string | null;
  /** Faixa (1..=6; 7 acima do teto). */
  faixa: number;
  /**
   * `ok`, `approaching_sublimit`, `sublimit_exceeded`, `sublimit_exceeded_over_20`,
   * `approaching_ceiling`, `ceiling_exceeded` ou `ceiling_exceeded_over_20`.
   */
  level: PaySimplesLevel;
  /** Média dos 3 últimos meses fechados. */
  monthly_average: DecimalText;
  /** Os 13 meses da janela. */
  months: SimplesMonthRevenueDto[];
  next_limit: PaySimplesLimit | null;
  next_limit_amount: DecimalText | null;
  /** Organização vigiada. */
  organization_id: string;
  /** Projeção da receita do ano. */
  projected_year_revenue: DecimalText;
  rate: SimplesRateDto | null;
  /** Receita bruta dos 12 meses anteriores ao corrente. */
  rbt12: DecimalText;
  /** Dia da última conferência gravada pela varredura diária (`YYYY-MM-DD`). */
  refreshed_on: string | null;
  regime: PayTaxRegime | null;
  /** Sublimite estadual (R$ 3.600.000). */
  sublimit: DecimalText;
  /** `true` só no Simples: é o único regime avisado. */
  watched: boolean;
  /** Receita de janeiro até hoje. */
  year_revenue: DecimalText;
}

/** `[DEV-ONLY]` Corpo de `POST /v1/pay/charges/{id}/simulate-outcome`. */
export interface SimulateOutcomeRequest {
  /**
   * Desfecho pretendido: `failed` (recusada) ou `expired` (venceu sem
   * pagamento). Validado no backend - conjunto fechado.
   */
  outcome: PaySimulatedOutcome;
}

/**
 * Corpo de `POST /v1/pay/recurrence/plans/simulate`: a agenda de cobrança de
 * uma adesão, para um plano existente ou para um rascunho.
 *
 * Exatamente um de `plan_id` e `plan`. Os dois juntos seria perguntar sobre
 * dois planos e responder sobre um só, calado.
 */
export interface SimulatePlanScheduleBody {
  /** Quantos ciclos devolver (1..=24; ausente = 6). */
  cycles?: number | null;
  /**
   * Pagador contra quem o teto por documento do cupom é conferido. Ausente:
   * o teto não é conferido e a resposta diz `document_cap_checked: false`.
   */
  iam_person_id?: string | null;
  /** Organização (vazio = a da sessão). */
  organization_id?: string | null;
  plan?: CreateRecurrencePlanBody | null;
  /** Plano existente (Snowflake decimal). */
  plan_id?: string | null;
  /** Dia da adesão simulada (`YYYY-MM-DD`; ausente = hoje). */
  started_on?: string | null;
  /**
   * Cupom de dias grátis a simular. Nada é consumido, e
   * as recusas são as mesmas da adesão.
   */
  trial_coupon_code?: string | null;
}

/** Entrada do simulador do regime híbrido. */
export interface SimulateSimplesHybridBody {
  /** Anexo (`i`..`v`). */
  anexo: PaySimplesAnexo;
  b2b_share?: DecimalTextOrEmpty | null;
  /** Alíquota da CBS, em % (0-100). */
  cbs_rate: string;
  monthly_purchases_with_credit?: DecimalTextOrEmpty | null;
  /** Receita do mês (decimal). */
  monthly_revenue: string;
  /** Organização; vazio usa a da sessão. */
  organization_id?: string | null;
  rbt12?: DecimalTextOrEmpty | null;
}

/** Um ciclo da agenda simulada. */
export interface SimulatedCycleDto {
  /** Total do título (mensalidade + taxa). */
  amount: DecimalText;
  /** Início do período coberto (`YYYY-MM-DD`). `null` quando a cobrança é só a taxa. */
  covers_from: string | null;
  /** Fim do período coberto, inclusivo (`YYYY-MM-DD`). `null` quando a cobrança é só a taxa. */
  covers_until: string | null;
  /** Só a mensalidade. */
  cycle_amount: DecimalText;
  /** Vencimento efetivo (`YYYY-MM-DD`), com a política de dia útil aplicada. */
  due_on: string;
  /** `full` | `prorated` | `fixed` | `setup_fee_only` | `regular`. */
  kind: PaySimulatedCycleKind;
  /** Posição, a partir de 1. */
  number: number;
  /** Faturamento: dia em que o título nasce (`YYYY-MM-DD`). */
  period: string;
  /** Taxa de adesão (`"0"` fora da primeira cobrança). */
  setup_fee: DecimalText;
}

/** Efeito do cupom de dias na simulação. */
export interface SimulatedTrialCouponDto {
  /** Código normalizado. */
  code: string;
  /**
   * Falso quando não havia pagador para conferir o teto por documento: ele
   * será conferido na adesão.
   */
  document_cap_checked: boolean;
  /** Dias que o cupom concede. */
  free_days: number;
  /** `add` (soma ao teste do plano) | `max` (vale o maior). */
  trial_stacking: PayTrialStacking;
}

/**
 * Regra da legenda de um formato: só documenta os valores, o
 * fio é texto.
 */
export type SocialCaptionRule = "forbidden" | "optional" | "required";

/** Ação de moderação sobre um comentário: só documenta os valores, o fio é texto. */
export type SocialCommentAction = "hide" | "unhide" | "delete" | "handle" | "unhandle";

/** Estado de uma conexão, do desafio de vínculo e das transições: só documenta os valores, o fio é texto. */
export type SocialConnectionStatus = "pending" | "linking" | "connected" | "paused" | "tripped" | "disconnected" | "reauth_required";

/** Uso de uma conexão: só documenta os valores, o fio é texto. */
export type SocialConnectionUsage = "capture" | "campaign" | "ai_attendance" | "chatbot" | "inbox";

/** Tipo de contato: só documenta os valores, o fio é texto. */
export type SocialContactKind = "person" | "group";

/** Caixa do inbox: só documenta os valores, o fio é texto. */
export type SocialConversationBox = "inbox" | "archived";

/** Estado de trabalho de uma conversa: só documenta os valores, o fio é texto. */
export type SocialConversationStatus = "open" | "resolved";

/**
 * Corpo da criação de post.
 *
 * A forma que o provider aceita (arquivos por formato, imagem ou vídeo,
 * legenda) é conferida no serviço, não aqui; a tela a lê de
 * `GET /v1/social/connections/{id}/post-formats`. Os tetos daqui só limitam o
 * tamanho do pedido.
 */
export interface SocialCreatePostBody {
  /**
   * Os arquivos no `archive`, na ordem do carrossel. Imagem JPEG, PNG
   * ou WebP (convertida para JPEG no serviço) e vídeo MP4 ou MOV, conforme
   * o formato. Vazio em `text`.
   */
  archive_file_ids?: string[];
  /** Legenda. Ausente em Story; obrigatória em `text`. */
  caption?: string | null;
  /**
   * As conexões (Instagram ou Página do Facebook) por onde o post sai, de 1
   * a 20, sem repetir. Cada uma vira um destino com fila e
   * estado próprios; se alguma não publica o formato, o post inteiro é
   * recusado.
   */
  connection_ids: string[];
  /**
   * Chave de idempotência da criação (1 a 128 caracteres ASCII visíveis). Repetir com a mesma chave e o mesmo pedido devolve o post
   * já criado, sem criar outro; a mesma chave com outro pedido é 409. O
   * cabeçalho `Idempotency-Key` vale o mesmo, e os dois juntos têm de ser
   * iguais. Sem chave nenhuma, cada pedido é um post novo.
   */
  idempotency_key?: string | null;
  /** `image`, `carousel`, `story`, `reel` ou `text`. */
  kind: SocialPostKind;
  /** A hora, RFC3339. Ausente = rascunho. */
  scheduled_at?: string | null;
}

/**
 * Corpo do cadastro de template.
 *
 * A forma que a Meta aceita (nome, idioma, parâmetros sem buraco, um exemplo
 * por parâmetro) é conferida no serviço, não aqui.
 */
export interface SocialCreateTemplateBody {
  /** Corpo com `{{1}}`..`{{n}}`. */
  body: string;
  /** `marketing` ou `utility`. */
  category: SocialTemplateCategory;
  /** Um exemplo por parâmetro, na ordem: a Meta analisa o template com eles. */
  examples?: string[];
  /** Rodapé, opcional. */
  footer?: string | null;
  /** Cabeçalho de texto, opcional. */
  header?: string | null;
  /** Idioma, como `pt_BR`. */
  language: string;
  /** Nome em `[a-z0-9_]`, único por conexão e idioma. */
  name: string;
}

/** Por que o login do Instagram terminou sem sessão: só documenta os valores, o fio é texto. */
export type SocialInstagramLoginFailure = "no_browser" | "browser_lost" | "browser_error" | "expired" | "canceled" | "abandoned" | "login_required" | "unavailable";

/** Tipo de uma ação sobre a tela do navegador: só documenta os valores, o fio é texto. */
export type SocialInstagramLoginInputKind = "click" | "text" | "key" | "scroll";

/** Estado do login do Instagram pelo navegador da casa: só documenta os valores, o fio é texto. */
export type SocialInstagramLoginStatus = "waiting" | "running" | "saving" | "done" | "failed";

/** Último problema da sessão do Instagram: só documenta os valores, o fio é texto. */
export type SocialInstagramSessionProblem = "login_required" | "checkpoint_required" | "rate_limited";

/** Estado da sessão do Instagram da captação: só documenta os valores, o fio é texto. */
export type SocialInstagramSessionStatus = "missing" | "active" | "paused" | "reauth_required";

/** Tipo de uma interação com o conteúdo publicado: só documenta os valores, o fio é texto. */
export type SocialInteractionKind = "comment" | "poll_reply" | "direct_message" | "mention";

/** Direção de uma mensagem: só documenta os valores, o fio é texto. */
export type SocialMessageDirection = "inbound" | "outbound";

/** O quadro de citação de uma resposta. */
export interface SocialMessageQuoteDto {
  /** Quem escreveu, em grupo. `null` quando não se sabe. */
  author_display_name: string | null;
  /** O começo do texto (até 200 caracteres). Vazio quando era só anexo. */
  body: string;
  /** `inbound` | `outbound`. */
  direction: SocialMessageDirection;
  /**
   * O tipo do anexo da citada, para o quadro dizer "foto", "áudio". `null`
   * sem anexo.
   */
  media_mime_type: string | null;
  /** Id da mensagem citada. */
  message_id: string;
}

/** Por que um "Entrar com Facebook" não deu certo: só documenta os valores, o fio é texto. */
export type SocialMetaLoginFailure = "canceled" | "missing_permissions" | "no_pages" | "provider_refused" | "expired";

/** Estado de um "Entrar com Facebook": só documenta os valores, o fio é texto. */
export type SocialMetaLoginStatus = "pending" | "authorized" | "linked" | "failed" | "expired";

/** Tipo da pessoa criada a partir do contato: só documenta os valores, o fio é texto. */
export type SocialPersonType = "individual" | "legal";

/** Um arquivo do post. */
export interface SocialPostAssetDto {
  /** A cópia gerenciada no cofre. */
  archive_file_id: string;
  /** Tipo. */
  mime_type: string;
  /** Ordem no carrossel, a partir de 0. */
  position: number;
}

/** Post agendado, com um destino por conexão. */
export interface SocialPostDto {
  /** Os arquivos, na ordem. */
  assets: SocialPostAssetDto[];
  /** Legenda; vazia em Story. */
  caption: string;
  /** Criação, RFC3339. */
  created_at: string;
  /** Id. */
  id: string;
  /** `image`, `carousel`, `story`, `reel` ou `text`. */
  kind: SocialPostKind;
  /** A próxima hora entre os destinos na fila, RFC3339; `null` em rascunho. */
  scheduled_at: string | null;
  /**
   * O resumo dos destinos: `publishing` se algum sai agora, senão
   * `scheduled` se algum espera, `draft`, `failed`, `published` e, por fim,
   * `cancelled`.
   */
  status: SocialPostStatus;
  /** Os destinos, um por conexão. */
  targets: SocialPostTargetDto[];
  /** Última mudança, RFC3339. */
  updated_at: string;
}

/** Um formato que a conexão publica. */
export interface SocialPostFormatDto {
  /** `forbidden`, `optional` ou `required`. */
  caption: SocialCaptionRule;
  /** Aceita imagem (JPEG, PNG ou WebP). */
  images: boolean;
  /** `image`, `carousel`, `story`, `reel` ou `text`. */
  kind: SocialPostKind;
  /** Maior quantidade de arquivos. */
  max_assets: number;
  /** Tamanho máximo da legenda, em caracteres. */
  max_caption_len: number;
  /**
   * Os tipos de arquivo aceitos (`image/png`, `video/mp4`...); vazio no
   * formato sem arquivo.
   */
  mime_types: string[];
  /** Menor quantidade de arquivos. */
  min_assets: number;
  /** Aceita vídeo (MP4 ou MOV). */
  videos: boolean;
}

/** Os formatos de uma conexão. */
export interface SocialPostFormatsDto {
  /** Na ordem da tela; vazio quando a conexão não publica. */
  items: SocialPostFormatDto[];
}

/** Formato de um post: só documenta os valores, o fio é texto. */
export type SocialPostKind = "image" | "carousel" | "story" | "reel" | "text";

/** Estado de um post: só documenta os valores, o fio é texto. */
export type SocialPostStatus = "draft" | "scheduled" | "publishing" | "published" | "failed" | "cancelled";

/**
 * Um destino do post: a conexão por onde ele sai, com fila e estado
 * próprios.
 */
export interface SocialPostTargetDto {
  /** Tentativas que falharam. */
  attempts: number;
  /** A conexão. */
  connection_id: string;
  /** O motivo da última falha. */
  failure_reason: string;
  /** Id do destino; é o `resource_id` do evento `social.post.published`. */
  id: string;
  /** Quando a varredura tenta de novo, RFC3339; `null` fora da fila. */
  next_attempt_at: string | null;
  /** Endereço público do post; vazio até sair. */
  permalink: string;
  /**
   * A mídia no provider; pode ficar vazia num post publicado cuja
   * confirmação veio depois de uma queda.
   */
  provider_media_id: string;
  /** Quando saiu, RFC3339; `null` até sair. */
  published_at: string | null;
  /** A hora pedida, RFC3339; `null` em rascunho. */
  scheduled_at: string | null;
  /**
   * `draft`, `scheduled`, `publishing`, `published`, `failed` ou
   * `cancelled`.
   */
  status: SocialPostStatus;
  /** Última mudança, RFC3339. */
  updated_at: string;
}

/** Página de posts. */
export interface SocialPostsPageDto {
  /** Posts, mais novos primeiro. */
  items: SocialPostDto[];
  /** Token da próxima página; vazio no fim. */
  next_page_token: string;
}

/** Tipo de um pedido de privacidade da Meta: só documenta os valores, o fio é texto. */
export type SocialPrivacyRequestKind = "deauthorize" | "data_deletion";

/** Estado de um pedido de privacidade da Meta: só documenta os valores, o fio é texto. */
export type SocialPrivacyRequestStatus = "received" | "needs_operator" | "nothing_to_erase" | "completed";

/** Provider de uma conexão, contato, interação ou bloqueio: só documenta os valores, o fio é texto. */
export type SocialProvider = "whatsapp_cloud" | "whatsapp_baileys" | "instagram" | "facebook_page" | "instagram_session" | "telegram";

/** Corpo do agendamento. */
export interface SocialSchedulePostBody {
  /**
   * Só o destino desta conexão. Ausente = todos os destinos
   * que ainda podem mudar (rascunho, agendado ou falho).
   */
  connection_id?: string | null;
  /** A hora, RFC3339. No passado = publicar na próxima varredura. */
  scheduled_at: string;
}

/** Desfecho de um envio: só documenta os valores, o fio é texto. */
export type SocialSendOutcome = "pending" | "accepted" | "rejected" | "unknown";

/** Uma conexão por onde dá para falar com o número. */
export interface SocialSendRouteDto {
  /** A conexão pode enviar agora (conectada e fora de pausa). */
  can_send: boolean;
  /** A conexão. */
  connection: ConnectionDto;
  conversation: ConversationDto | null;
  /** É a conexão que a regra recomenda. */
  recommended: boolean;
  /** Só template sai por aqui agora: a janela do provider está fechada. */
  requires_template: boolean;
}

/** As rotas para um número. */
export interface SocialSendRoutesDto {
  /**
   * A recomendada. Vazio = nenhuma (primeiro toque: a escolha é de quem
   * atende).
   */
  recommended_connection_id: string;
  /** Uma por conexão de WhatsApp do escopo que não foi desvinculada. */
  routes: SocialSendRouteDto[];
}

/** Modo de atendimento de uma conexão: só documenta os valores, o fio é texto. */
export type SocialServiceMode = "simple" | "attendance";

/** Motivo de um bloqueio: só documenta os valores, o fio é texto. */
export type SocialSuppressionReason = "opt_out" | "manual" | "unreachable" | "complaint";

/** Categoria de um template de mensagem: só documenta os valores, o fio é texto. */
export type SocialTemplateCategory = "marketing" | "utility";

/** Template de mensagem. */
export interface SocialTemplateDto {
  /** Corpo com `{{1}}`..`{{n}}`. */
  body: string;
  /** `marketing` ou `utility`. */
  category: SocialTemplateCategory;
  /** Conexão por onde ele sai. */
  connection_id: string;
  /** Criação, RFC3339. */
  created_at: string;
  /** Os exemplos submetidos à análise. */
  examples: string[];
  /** Rodapé; vazio quando não há. */
  footer: string;
  /** Cabeçalho; vazio quando não há. */
  header: string;
  /** Id. */
  id: string;
  /** Idioma. */
  language: string;
  /** Nome. */
  name: string;
  /** Id no provider; vazio enquanto não foi submetido. */
  provider_template_id: string;
  /**
   * `draft`, `pending`, `approved`, `rejected`, `paused` ou `disabled`. Só
   * `approved` envia.
   */
  status: SocialTemplateStatus;
  /** O motivo, na recusa do provider ou na submissão que não chegou lá. */
  status_reason: string;
  /** Última mudança, RFC3339. */
  updated_at: string;
}

/** Estado de um template de mensagem: só documenta os valores, o fio é texto. */
export type SocialTemplateStatus = "draft" | "pending" | "approved" | "rejected" | "paused" | "disabled";

/** Página de templates. */
export interface SocialTemplatesPageDto {
  /** Templates, mais novos primeiro. */
  items: SocialTemplateDto[];
  /** Token da próxima página; vazio no fim. */
  next_page_token: string;
}

/** Decisão diária do aquecimento: só documenta os valores, o fio é texto. */
export type SocialWarmupDecision = "promoted" | "held" | "demoted" | "no_data";

/**
 * O que uma entrega produziu. A Meta ignora o corpo; ele existe para quem
 * depura a integração.
 */
export interface SocialWebhookReceiptDto {
  /** Fatos gravados agora. */
  accepted: number;
  /** Reentregas do que já estava gravado. */
  duplicates: number;
  /** O que não era para nós: número sem conexão, tipo que o inbox não mostra. */
  ignored: number;
}

/** Pagamento a sócio (DTO de resposta). */
export interface SocioPaymentDto {
  /** Valor (decimal string). */
  amount: DecimalText;
  /** Competência (`YYYY-MM-DD`). */
  competence_date: string;
  /** Criação (RFC3339). */
  created_at: string;
  /** Snowflake. */
  id: string;
  /** Incide INSS (derivado, read-only). */
  incurs_inss: boolean;
  /** Incide IRRF (derivado, read-only). */
  incurs_irrf: boolean;
  /** É pró-labore (derivado, read-only). */
  is_pro_labore: boolean;
  /** Observação (vazio = sem). */
  note: string;
  /** Organização dona (vazio = escopo tenant). */
  organization_id: string;
  /** Natureza do parceiro: `individual` | `holding` | `legal_entity` | `other`. */
  partner_kind: PaySocioPartnerKind;
  /** Nome do sócio/holding que recebe. */
  partner_name: string;
  /** Natureza fiscal: `pro_labore` | `profit_distribution` | `remessa` | `other`. */
  payment_kind: PaySocioPaymentKind;
  /** Última atualização (`null` = nunca). */
  updated_at: string | null;
}

/** Lista paginada de pagamentos a sócio (envelope keyset). */
export interface SocioPaymentsListDto {
  /** Pagamentos a sócio da página atual. */
  items: SocioPaymentDto[];
  /** Cursor opaco da próxima página (`next_page_token`). Vazio = última página. */
  next_page_token: string;
}

/** Uma linha no corpo da requisição ou da cotação. */
export interface SourcingLineBody {
  /** Quantidade (decimal em string). */
  quantity: string;
  /** Unidade da quantidade. Ausente, a unidade base. */
  uom_id?: string | null;
  /** SKU. */
  variant_id: string;
}

/** Uma coluna do relatório. */
export interface SpecColumnDto {
  /** Agregação (`sum`, `count`, `min`, `max`, `avg`); vazio ou ausente = sem. */
  agg?: string;
  /** Coluna do dataset. */
  column: string;
  /** Rótulo de exibição; vazio usa o nome da coluna. */
  label?: string;
}

/** Uma ordenação. */
export interface SpecSortDto {
  /** Coluna do dataset. Nas formas agrupadas, precisa estar no agrupamento. */
  column: string;
  /**
   * `asc` ou `desc`; vazio ou ausente no pedido vale `asc`, e a resposta
   * sempre traz o valor.
   */
  direction?: ReportsSortDirection;
}

/** Perfil de split versionado (resposta). Campos vazios = ausente. */
export interface SplitProfileDto {
  /** Criação (RFC3339). */
  created_at: string;
  /** Moeda ISO 4217. */
  currency: string;
  /** Casas decimais da moeda. */
  currency_scale: number;
  /** Snowflake do perfil (estável entre versões). */
  id: string;
  /** Se esta versão está ativa para novas emissões. */
  is_active: boolean;
  /**
   * Método de acquiring do perfil (`pix`|`boleto`|`card`|`crypto`; vazio =
   * qualquer).
   */
  method: PaySplitProfileMethod;
  /** Nome de exibição. */
  name: string;
  /** Organização dona (vazio = escopo tenant). */
  organization_id: string;
  /** Estratégia do primário (`charge_beneficiary` | `explicit_wallet`). */
  primary_strategy: PaySplitPrimaryStrategy;
  /** Wallet primária fixa (vazio se `charge_beneficiary`). */
  primary_wallet_id: string;
  /** Regras de divisão. */
  rules: SplitProfileRuleDto[];
  /** Versão (imutável; cresce a cada `bump`). */
  version: number;
}

/**
 * Campos comuns de criação/edição de um perfil (sem id/version - atribuídos
 * pelo serviço).
 */
export interface SplitProfileInputBody {
  /** Moeda ISO 4217. */
  currency: string;
  /** Casas decimais da moeda (`0..=28`; o serviço valida o teto). */
  currency_scale: number;
  method?: PayAcquiringMethod | null;
  /** Nome de exibição do template. */
  name: string;
  /** Organização dona (vazio = escopo tenant). */
  organization_id?: string | null;
  /** Estratégia do primário: `charge_beneficiary` | `explicit_wallet`. */
  primary_strategy: PaySplitPrimaryStrategy;
  /** Wallet primária fixa - obrigatória sse `primary_strategy = explicit_wallet`. */
  primary_wallet_id?: string | null;
  /** Regras de divisão (≥ 1). */
  rules: SplitProfileRuleBody[];
}

/**
 * Uma regra de divisão (linha filha de um perfil). Enums em SCREAMING_SNAKE,
 * o mesmo contrato de wire do `split_engine` - o gateway não
 * traduz, repassa cru ao serviço, que valida.
 */
export interface SplitProfileRuleBody {
  /** Categoria: `GATEWAY_FEE` | `PLATFORM_FEE` | `COMMISSION` | `TAX` | `RESERVE` | `ROYALTY`. */
  category: PaySplitCategory;
  /** Ordem na cadeia (obrigatória/única em `NET_CHAIN`; ausente nas demais fases). */
  chain_order?: number | null;
  /** Fase: `GROSS` | `NET_CHAIN` | `NET_FINAL`. */
  phase: string;
  /** Wallet a creditar (Snowflake decimal). */
  recipient_wallet_id: string;
  /** Tipo: `FIXED` | `PERCENTAGE`. */
  rule_type: PaySplitRuleType;
  /** Valor decimal (`> 0`; `<= 100` se `PERCENTAGE`). */
  value: string;
}

/** Regra de divisão (resposta). */
export interface SplitProfileRuleDto {
  /** Categoria. */
  category: PaySplitCategory;
  /** Ordem na cadeia (ausente fora de `NET_CHAIN`). */
  chain_order: number | null;
  /** Fase (`GROSS` | `NET_CHAIN` | `NET_FINAL`). */
  phase: string;
  /** Wallet creditada. */
  recipient_wallet_id: string;
  /** Tipo (`FIXED` | `PERCENTAGE`). */
  rule_type: PaySplitRuleType;
  /** Valor decimal. */
  value: DecimalText;
}

/** Histórico de versões de um perfil (ordem decrescente de versão). */
export interface SplitProfileVersionsDto {
  /** Versões, mais nova primeiro. */
  items: SplitProfileDto[];
}

/** Lista paginada de perfis (versão ativa de cada um). */
export interface SplitProfilesListDto {
  /** Perfis. */
  items: SplitProfileDto[];
  /** Cursor opaco da próxima página (vazio = última página). */
  next_page_token: string;
}

/** Resultado da descoberta. */
export interface SsoDiscoverDto {
  /** IdPs que atendem o e-mail. Vazio quando nenhum (a tela segue com senha). */
  items: SsoDiscoveredIdpDto[];
}

/** IdP oferecido na tela de entrada. */
export interface SsoDiscoveredIdpDto {
  /** Nome no botão. */
  display_name: string;
  /** Valor de `provider` para `POST /v1/auth/oauth/initiate`. */
  provider: string;
  /** Tenant dono do IdP, para o `tenant_id` do initiate. */
  tenant_id: string;
}

/** Body de `PUT /v1/iam/sso-policy`. */
export interface SsoPolicyBody {
  /**
   * Cargo dado a quem entra pelo IdP sem conta no tenant (Snowflake, em
   * string). Vazio desliga a criação na hora.
   */
  jit_role_id?: string;
  /**
   * `true` desliga senha, passkey e login social para a equipe: só o IdP do
   * tenant abre sessão. Quem liga vira a conta de recuperação, que segue
   * entrando com senha.
   */
  sso_only: boolean;
}

/** Corpo de abrir o login pelo navegador da casa. */
export interface StartInstagramLoginBody {
  /**
   * A pessoa aceita que o Instagram (Meta) pode pedir verificação,
   * bloquear ou restringir a conta. Sem `true`, 422.
   */
  accept_meta_risk?: boolean;
  /** A conta a reconectar. Ausente = conta nova. */
  account_id?: string | null;
}

/** Corpo do início de vínculo. */
export interface StartLinkBody {
  /**
   * Só no WhatsApp oficial: a conta comercial (WABA) do número, exigida
   * para cadastrar template. Conferida na Meta: a conta precisa listar o
   * número vinculado.
   */
  business_account_id?: string | null;
  /** Só nos oficiais: a credencial obtida na Meta. */
  credential?: string | null;
  /** Só no provider não oficial: pedir código de pareamento em vez de QR. */
  pairing_phone?: string | null;
  /**
   * Só nos oficiais: a conta no provider, o `phone_number_id` que a Meta
   * mostra no app. É conferida na Meta com a credencial antes de a conexão
   * ligar; vazio num revínculo reaproveita a conta já vinculada.
   */
  provider_account_id?: string | null;
}

/** Corpo do início do login com Google ou Microsoft. */
export interface StartMailOAuthBody {
  /** Reconectar esta caixa (vazio = caixa nova). */
  mailbox_id?: string | null;
  /** `google` ou `microsoft`. */
  provider: CommunityMailOAuthProvider;
}

/** A URL do provedor para onde o navegador vai. */
export interface StartMailOAuthDto {
  /** URL de autorização do provedor. */
  authorize_url: string;
}

/** Corpo opcional de `/authorize`. */
export interface StartMarketplaceAuthorizationBody {
  /**
   * Destino do app ao fim do OAuth (ex. `ferrazio://marketplace/return`).
   * Precisa estar, idêntico, na allowlist do ambiente; fora dela, 422
   * `return_url_not_allowed`.
   */
  return_url?: string | null;
}

/** O que o cliente manda para começar o teste. */
export interface StartTrialBody {
  /**
   * Quem vai pagar quando o cliente comprar. O documento dele é o que
   * limita o teste a um por CPF/CNPJ.
   */
  payer: PurchasePayerBody;
}

/** Resultado da importação por arquivo (ou só a prévia, com `dry_run`). */
export interface StatementFileImportDto {
  /** `match` | `mismatch` | `unknown`. */
  account_check: PayStatementAccountCheck;
  closing_balance: DecimalText | null;
  /** Moeda declarada no arquivo. */
  currency: string | null;
  /** Eco do pedido. */
  dry_run: boolean;
  /** Conta segundo o arquivo. */
  file_account: string | null;
  /** Banco segundo o arquivo. */
  file_bank_code: string | null;
  /** Agência segundo o arquivo. */
  file_branch: string | null;
  /** `ofx` | `cnab240`. */
  format: PayStatementFileFormat;
  /** Linhas inseridas (0 no `dry_run`). */
  inserted: number;
  /** Linhas normalizadas (só no `dry_run`). */
  lines: StatementFileLineDto[];
  opening_balance: DecimalText | null;
  /** Último dia do extrato (`YYYY-MM-DD`). */
  period_end: string | null;
  /** Primeiro dia do extrato (`YYYY-MM-DD`). */
  period_start: string | null;
  /** Linhas que já existiam (0 no `dry_run`). */
  skipped: number;
  /** Origem gravada nas linhas: `ofx` | `cnab`. */
  source: PayStatementSource;
  /** Avisos de leitura. */
  warnings: StatementFileWarningDto[];
}

/** Linha normalizada da prévia. */
export interface StatementFileLineDto {
  /** Valor com sinal (positivo = crédito), string decimal. */
  amount: DecimalText;
  /** Histórico do banco. */
  description: string | null;
  /** Número do documento. */
  document_number: string | null;
  /** Id do lançamento: o FITID do banco ou um id estável gerado do conteúdo. */
  external_id: string;
  /** `YYYY-MM-DD`. */
  posted_on: string;
}

/** Aviso de leitura: o arquivo foi aceito, mas algo merece o olho do operador. */
export interface StatementFileWarningDto {
  /**
   * `zero_amount_skipped` | `balance_line_skipped` | `fitid_reused` |
   * `fitid_missing` | `debit_sign_fixed` | `totals_mismatch` |
   * `segment_ignored` | `currency_mismatch`.
   */
  code: PayStatementWarningCode;
  /** Detalhe técnico. */
  detail: string;
  /** Posição da transação no arquivo (1 = primeira). */
  entry: number | null;
}

/** Linha de extrato com saldo corrente. */
export interface StatementLineDto {
  /** Valor com sinal (`+` crédito, `−` débito). */
  amount: DecimalText;
  /** Conta contábil opcional (vazio = sem dimensão). */
  chart_of_account_id: string;
  /** Centro de custo opcional. */
  cost_center_id: string;
  /** Criação (RFC3339). */
  created_at: string;
  /** Moeda ISO 4217. */
  currency: string;
  /** Descrição livre do lançamento. */
  description: string;
  /** Snowflake do lançamento. */
  entry_id: string;
  /** Tipo (`debit`/`credit`) - redundante com o sinal de `amount`. */
  entry_type: PayEntryType;
  /** ID da operação dona. */
  operation_id: string;
  /** Tipo da operação dona. */
  operation_type: PayOperationType;
  /**
   * ID da entidade de origem, Snowflake decimal em texto; `null` = sem
   * origem. Texto porque passa de 2^53 e o `JSON.parse` comum arredondaria.
   */
  reference_id: string | null;
  /** Origem da operação dona. */
  reference_kind: string;
  /**
   * Descrição legível do documento de origem (vazio = não resolvido).
   *
   * : sem isto a tela só tinha o par kind/id para escrever, e saía
   * `Conta a receber #45165719855562752` para quem só quer ler o extrato.
   */
  reference_label: string;
  /** Saldo acumulado até esta linha (window function). */
  running_balance: DecimalText;
  /** Wallet afetada. */
  wallet_id: string;
}

/** Lista paginada de linhas. */
export interface StatementLinesListDto {
  /** Linhas. */
  items: BankStatementLineDto[];
  /** Cursor opaco da próxima página (vazio = última página). */
  next_page_token: string;
}

/** Resposta do extrato (envelope cursor). */
export interface StatementResponseDto {
  /** Linhas mais recentes primeiro (ORDER BY id DESC). */
  lines: StatementLineDto[];
  /** Cursor opaco da próxima página (vazio = última página). */
  next_page_token: string;
}

/** Classe da curva ABC: só documenta os valores, o fio é texto. */
export type StockAbcClass = "A" | "B" | "C";

/** Critério da curva ABC: só documenta os valores, o fio é texto. */
export type StockAbcCriterion = "consumed_value" | "quantity" | "margin";

/** Curva ABC apurada para um depósito numa janela de tempo. */
export interface StockAbcCurveDto {
  /** Quando o cálculo foi feito (RFC 3339). */
  computed_at: string;
  /**
   * Critério que ordenou os itens.
   *
   * Valores: `quantity`, `margin`, `consumed_value`.
   */
  criterion: StockAbcCriterion;
  /** Corte da classe A, em fração acumulada (string decimal). */
  cut_a: DecimalText;
  /** Corte da classe B, em fração acumulada (string decimal). */
  cut_b: DecimalText;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Quantas variantes entraram na curva. */
  item_count: number;
  /** Linhas do documento. */
  items: StockAbcEntryDto[];
  /** Soma da métrica de todas as variantes (string decimal). */
  total_metric: DecimalText;
  /** Depósito. */
  warehouse_id: string | null;
  /** Fim da janela apurada (AAAA-MM-DD). */
  window_end: string;
  /** Início da janela apurada (AAAA-MM-DD). */
  window_start: string;
}

/** Uma variante na curva ABC, com a classe e o número que a classificou. */
export interface StockAbcEntryDto {
  /** "A", "B" ou "C". */
  class: StockAbcClass;
  /** Participação acumulada até esta variante (fração, string decimal). */
  cumulative_share: DecimalText;
  /** O número que classificou - guardado porque é ele que explica a classe. */
  metric: DecimalText;
  /** Posição na ordenação, a partir de 1. */
  rank: number;
  /** Participação da variante no total (fração, string decimal). */
  share: DecimalText;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
}

/** Integração do estoque com a contabilidade da organização: as contas do plano para onde vão as pernas de cada movimento. */
export interface StockAccountingConfigDto {
  /**
   * Variação de custo de aquisição: contrapartida da parte do
   * documento de custo posterior cuja mercadoria já tinha saído. OPCIONAL.
   */
  acquisition_variance_account_id: string | null;
  /** Conta de ajuste de inventário; `null` enquanto não configurada. */
  adjustment_account_id: string | null;
  /** Conta de custo da mercadoria vendida (CMV); `null` enquanto não configurada. */
  cogs_account_id: string | null;
  /** Quando o recurso foi ligado (RFC 3339); `null` se nunca foi. */
  enabled_at: string | null;
  /**
   * Conta-corrente entre empresas do grupo: a contrapartida da remessa
   * interempresa (P12). OPCIONAL - quem tem uma organização só nunca remete
   * para irmã, e exigi-la aqui obrigaria toda empresa a mapear uma conta que
   * ela não usa. Faltando, a remessa fica visível na fila da E8.
   */
  interco_account_id: string | null;
  /**
   * As quatro contas do plano do `pay`. Ligar sem todas → FailedPrecondition
   * (fail-closed): não dá para ligar a contabilidade pela metade.
   */
  inventory_account_id: string | null;
  /** Recurso ligado para a organização. */
  is_enabled: boolean;
  /** Conta de perdas; `null` enquanto não configurada. */
  loss_account_id: string | null;
  /**
   * Contrapartida da devolução ao fornecedor. OPCIONAL pelo mesmo
   * motivo da `interco_account_id`: sem ela a devolução nasce not_applicable e
   * nada chega ao razão. Nenhuma das outras cinco serve - cogs diria que a
   * mercadoria foi vendida, loss que a empresa a perdeu, adjustment que houve
   * erro de contagem, e as três jogariam o valor no RESULTADO do mês.
   */
  supplier_return_account_id: string | null;
  /**
   * A wallet do `pay` onde as duas pernas do lançamento se anulam.
   *
   * Existe porque `pay_ledger_entries.wallet_id` é obrigatório e o movimento de
   * estoque NÃO mexe em caixa: ele reclassifica valor entre contas do plano. As
   * duas pernas vão para a MESMA wallet com sinais opostos, o que satisfaz a
   * soma-zero do `pay` (I2) e deixa o saldo dela intacto.
   */
  wallet_id: string | null;
}

/** Situação do lançamento contábil: só documenta os valores, o fio é texto. */
export type StockAccountingStatus = "not_applicable" | "pending" | "posted" | "failed";

/** Política de aquisição da organização: regime de crédito de imposto e critério padrão de rateio das despesas da nota. */
export interface StockAcquisitionConfigDto {
  /**
   * Critério padrão de rateio de frete, seguro e outras despesas entre as linhas da nota.
   *
   * Valores: `by_quantity`, `manual`, `by_value`.
   */
  default_expense_allocation: StockExpenseAllocation;
  /**
   * Regime de crédito do imposto recuperável na entrada.
   *
   * Valores: `credit`, `no_credit`.
   */
  tax_credit_mode: StockTaxCreditMode;
}

/** Endereçamento do depósito: só documenta os valores, o fio é texto. */
export type StockAddressingMode = "none" | "bins";

/** Critério de rateio do custo entre as saídas da transformação ou da produção: só documenta os valores, o fio é texto. */
export type StockAllocationCriterion = "market_value" | "declared_share";

/** Divergência entre as camadas de custo e a trilha de movimentos de um item. */
export interface StockBalanceDiscrepancyDto {
  /**
   * `on_hand - net_movements`. Positivo = camada a mais; negativo =
   * movimento sem camada (string decimal).
   */
  difference: DecimalText;
  /**
   * `Σ (quantidade × direção)` dos movimentos: o que a trilha justifica
   * (string decimal).
   */
  net_movements: DecimalText;
  /**
   * `Σ remaining_quantity` das camadas abertas: o que o estoque diz que
   * existe (string decimal).
   */
  on_hand: DecimalText;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
  /** Depósito. */
  warehouse_id: string;
}

/**
 * Saldo de uma variante num depósito. DERIVADO das camadas abertas - nunca lido
 * de uma coluna de saldo.
 */
export interface StockBalanceDto {
  /** quantity menos as reservas ativas. É o que o PDV pode vender. */
  available: DecimalText;
  average_unit_cost: DecimalText | null;
  /** Lote; `null` quando o item não é controlado por lote. */
  lot_id: string | null;
  /** Soma das quantidades restantes das camadas abertas, na unidade base. */
  quantity: DecimalText;
  total_value: DecimalText | null;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
  /**
   * `null` = linha **consolidada** da organização (o cliente pediu o saldo
   * sem escolher depósito). String vazia diria "depósito de id vazio", que
   * é o tipo de valor que o front acaba imprimindo na tela.
   */
  warehouse_id: string | null;
  zero_cost_ratio: DecimalText | null;
}

/** Página de `StockBalanceDto`, em ordem estável, com o cursor da próxima. */
export interface StockBalancePageDto {
  /** Os itens desta página. */
  items: StockBalanceDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Saldo de uma variante (e lote) numa posição endereçada. */
export interface StockBinBalanceDto {
  /** Posição. */
  bin_id: string;
  /** Lote; `null` quando o item não é controlado por lote. */
  lot_id: string | null;
  /** Caminho materializado da posição (`/A/01/03/B`). */
  path: string;
  /** Quantidade, em string decimal (nunca float). */
  quantity: DecimalText;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
}

/** Página de `StockBinBalanceDto`; o cursor vem sempre vazio. */
export interface StockBinBalancePageDto {
  /** Os itens desta página. */
  items: StockBinBalanceDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Resultado da conferência entre posições e saldo do depósito. */
export interface StockBinConsistencyDto {
  /** `true` quando `items` está vazio. */
  is_consistent: boolean;
  /** As divergências encontradas. */
  items: StockBinDivergenceDto[];
}

/** Divergência entre o saldo do depósito e a soma das posições (E13). */
export interface StockBinDivergenceDto {
  /** O que a soma das posições diz (string decimal). */
  binned_quantity: DecimalText;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
  /** Depósito. */
  warehouse_id: string;
  /** O que o saldo do depósito diz (string decimal). */
  warehouse_quantity: DecimalText;
}

/** Posição endereçada de um depósito (rua, prateleira, nível, vão), em árvore. */
export interface StockBinDto {
  /**
   * Tipo da posição.
   *
   * Valores: `storage` (o padrão), `picking`, `bulk`, `receiving`, `shipping`, `quarantine`, `damaged`, `production`, `transit`.
   */
  bin_type: StockBinType;
  /** Motivo do bloqueio operacional; `null` quando a posição não está bloqueada. */
  block_reason: string | null;
  /**
   * Bloqueio operacional COM motivo. Os dois andam juntos: bloqueio sem motivo
   * é bloqueio que ninguém sabe desfazer.
   */
  blocked_at: string | null;
  /** O segmento DESTE nível (`A`, `01`, `03`, `B`), nunca o caminho inteiro. */
  code: string;
  /** Profundidade na árvore; o topo é 1. */
  depth: number;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** `false` = inativado; some das listas, mas o histórico fica. */
  is_active: boolean;
  max_units: DecimalText | null;
  /** Nome de exibição. */
  name: string | null;
  /** O nível acima. Vazio no topo da árvore. */
  parent_id: string | null;
  /**
   * Caminho materializado (`/A/01/03/B`), DERIVADO. ⚠️ Nunca digitado: caminho
   * digitado é caminho que um dia discorda do pai, e a busca por prefixo passa
   * a mentir sem dar erro.
   */
  path: string;
  /**
   * Ordem de percurso da separação: a lista sai na ordem do galpão, não na
   * ordem em que o pedido foi digitado. Vazio = sem preferência.
   */
  pick_sequence: number | null;
  /** A posição só aceita um lote por vez. */
  single_lot: boolean;
  /** A posição só aceita uma variante por vez. */
  single_variant: boolean;
  /** Depósito. */
  warehouse_id: string;
}

/** O nome de um nível da árvore de posições ("Rua", "Prateleira"). */
export interface StockBinLevelDto {
  /** Profundidade a que o nome se aplica; o topo é 1. */
  depth: number;
  /** Nome do nível. */
  label: string;
}

/** Página de `StockBinLevelDto`; o vocabulário cabe numa resposta e o cursor vem sempre vazio. */
export interface StockBinLevelPageDto {
  /** Os itens desta página. */
  items: StockBinLevelDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Entrada ou saída de quantidade numa posição endereçada. */
export interface StockBinMovementDto {
  /** Posição movimentada. */
  bin_id: string;
  /** Quando foi registrado (RFC 3339). */
  created_at: string;
  /** `1` entrou na posição, `-1` saiu. */
  direction: number;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Lote; `null` quando o item não é controlado por lote. */
  lot_id: string | null;
  /**
   * O movimento de estoque que originou. Vazio na MUDANÇA DE POSIÇÃO, que não
   * move valor e por isso não é movimento de estoque.
   */
  movement_id: string | null;
  /** Quando o fato aconteceu (RFC 3339), que pode ser antes do registro. */
  occurred_at: string;
  /** Quantidade, em string decimal (nunca float). */
  quantity: DecimalText;
  /** As duas pernas de uma mudança de posição. */
  relocation_pair_id: string | null;
  /** Número de série; `null` quando o item não é serializado. */
  serial_id: string | null;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
  /** Depósito. */
  warehouse_id: string;
}

/** Página de `StockBinMovementDto`; o cursor vem sempre vazio. */
export interface StockBinMovementPageDto {
  /** Os itens desta página. */
  items: StockBinMovementDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Página de `StockBinDto`; a árvore cabe numa resposta e o cursor vem sempre vazio. */
export interface StockBinPageDto {
  /** Os itens desta página. */
  items: StockBinDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Tipo da posição endereçada: só documenta os valores, o fio é texto. */
export type StockBinType = "storage" | "picking" | "bulk" | "receiving" | "shipping" | "quarantine" | "damaged" | "production" | "transit";

/** Resultado da conferência entre camadas de custo e movimentos. */
export interface StockConsistencyDto {
  /**
   * `true` quando `items` está vazio. Redundante de propósito: uma lista
   * vazia não distingue "conferi e fecha" de "não consegui conferir".
   */
  is_consistent: boolean;
  /** As divergências encontradas. */
  items: StockBalanceDiscrepancyDto[];
  /**
   * `true` quando o teto de linhas foi atingido e há mais divergência do
   * que a resposta cabe.
   */
  truncated: boolean;
}

/**
 * Documento de custo posterior e como ele se dividiu entre o que
 * ainda estava em estoque e o que já tinha saído.
 */
export interface StockCostAdjustmentDto {
  /**
   * Lançamento da parte do resultado: `not_applicable`, `pending`,
   * `posted` ou `failed`.
   */
  accounting_status: StockAccountingStatus;
  /** Critério de rateio entre as linhas. */
  allocation: StockExpenseAllocation;
  amount: DecimalText | null;
  /** Transportador ou seguradora. */
  carrier_person_id: string | null;
  /** Quando foi lançado (RFC 3339). */
  created_at: string;
  /** Quem lançou. */
  created_by: string | null;
  /** Moeda do recebimento. */
  currency: string;
  /** Chave do CT-e, número do documento ou referência do acordo. */
  document_ref: string;
  /** Id do documento. */
  id: string;
  /** `freight`, `insurance`, `other` ou `discount`. */
  kind: StockCostAdjustmentKind;
  /** Referência do lançamento no razão, quando lançado. */
  ledger_entry_ref: string | null;
  /** A parte de cada linha do recebimento. */
  lines: StockCostAdjustmentLineDto[];
  /** Observação. */
  note: string | null;
  /** Data do documento (`AAAA-MM-DD`). */
  occurred_on: string;
  /**
   * Título a pagar sugerido ao `pay` para este documento:
   * nulo enquanto ninguém pediu, e sempre nulo no abatimento, que não é
   * dívida.
   */
  payable_id: string | null;
  /** Recebimento a que o documento pertence. */
  receipt_id: string;
  to_inventory: DecimalText | null;
  to_result: DecimalText | null;
}

/** Tipo do documento de ajuste de custo: só documenta os valores, o fio é texto. */
export type StockCostAdjustmentKind = "freight" | "insurance" | "other" | "discount";

/** Uma camada de custo que o documento posterior mudou. */
export interface StockCostAdjustmentLayerDto {
  /** Camada. */
  cost_layer_id: string;
  /** Quantidade que ainda estava na camada. */
  remaining_quantity: DecimalText;
  to_inventory: DecimalText | null;
  unit_cost_after: DecimalText | null;
  unit_cost_before: DecimalText | null;
}

/** A parte de uma linha do recebimento num documento de custo posterior. */
export interface StockCostAdjustmentLineDto {
  amount: DecimalText | null;
  /** As camadas que mudaram de custo. */
  layers: StockCostAdjustmentLayerDto[];
  /** Linha do recebimento. */
  receipt_item_id: string;
  to_inventory: DecimalText | null;
  to_result: DecimalText | null;
}

/** Os documentos de custo posterior de um recebimento, do mais antigo ao mais novo. */
export interface StockCostAdjustmentListDto {
  /** No máximo 50 por recebimento. */
  items: StockCostAdjustmentDto[];
}

/** Método de custeio de um produto (a família, não a variante). */
export interface StockCostingConfigDto {
  /**
   * `false` = já existe movimento, e a **E6** trava a troca. O front usa
   * isto para desabilitar o campo com explicação, em vez de deixar o
   * usuário salvar e levar erro.
   */
  is_changeable: boolean;
  /**
   * Método de custeio.
   *
   * Valores: `fifo`, `average`.
   */
  method: StockCostingMethod;
  /** Vazio = o default do tenant. */
  product_id: string | null;
}

/** Método de custeio: só documenta os valores, o fio é texto. */
export type StockCostingMethod = "average" | "fifo";

/**
 * O valor de um campo personalizado, na forma que o `data_type` anuncia.
 *
 * Texto para `text`, `number` (string decimal), `date` (AAAA-MM-DD) e
 * `select` (id da opção); booleano só para `bool`.
 */
export type StockCustomValue = string | boolean;

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * Entrada automática por DF-e (F7)
 * ─────────────────────────────────────────────────────────────────────────────
 * A adesão de UMA organização ao recebimento automático.
 */
export interface StockDfeIngestionConfigDto {
  /** Desde quando está ligada (RFC 3339); `null` quando desligada. */
  enabled_at: string | null;
  /** Recurso ligado para a organização. */
  is_enabled: boolean;
  /**
   * Telemetria de atraso: e o que distingue "nao chegou nota" de "a
   * varredura parou de rodar", duas telas identicas e dois problemas
   * opostos.
   */
  last_document_id: string | null;
  /** Última varredura (RFC 3339); `null` quando nunca rodou. */
  last_run_at: string | null;
  /**
   * CNPJ interessado na distribuição DF-e do `fiscal` (14 dígitos).
   *
   * É ele que amarra os dois lados: `fsc_dfe_documents` não tem
   * `organization_id`, e é o CNPJ do destinatário que diz de qual empresa do
   * grupo é a nota. Sem ele, a matriz abriria o recebimento da nota da filial.
   */
  recipient_cnpj: string | null;
  /** Depósito de destino. Vazio = o Principal da organização, resolvido na hora. */
  warehouse_id: string | null;
}

/** Critério de rateio de despesa entre as linhas: só documenta os valores, o fio é texto. */
export type StockExpenseAllocation = "by_value" | "by_quantity" | "manual";

/** Obrigação de documento fiscal: só documenta os valores, o fio é texto. */
export type StockFiscalStatus = "not_applicable" | "pending" | "issued" | "waived";

/** Inventário (contagem física) de um depósito, com as linhas contadas. */
export interface StockInventoryDto {
  /** Rua contada; `null` = o depósito inteiro. */
  bin_path_prefix: string | null;
  /**
   * Contado por posição (depósito endereçado): cada linha traz a posição,
   * e o ajuste mexe no depósito e na prateleira juntos.
   */
  by_bin: boolean;
  /** Por que a contagem foi abandonada. Vazio quando nao houve cancelamento. */
  cancel_reason: string | null;
  /**
   * Contar e efetivar são autoridades separadas: o intervalo entre estas
   * duas datas é a janela de conferência.
   */
  counted_at: string | null;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Linhas do documento. */
  items: StockInventoryItemDto[];
  /** Observacao de quem abriu a contagem. */
  note: string | null;
  /** Quando foi efetivado (RFC 3339); `null` enquanto não efetivado. */
  posted_at: string | null;
  /**
   * Abrangência da contagem.
   *
   * Valores: `full`, `partial`.
   */
  scope: StockInventoryScope;
  /** Abertura do inventário (RFC 3339): é quando as quantidades do sistema foram congeladas. */
  started_at: string;
  /**
   * Estado do registro.
   *
   * Valores: `open`, `counted`, `posted`, `cancelled`.
   */
  status: StockInventoryStatus;
  /** Depósito. */
  warehouse_id: string;
}

/** Uma linha do inventário: o saldo congelado na abertura e o que foi contado. */
export interface StockInventoryItemDto {
  /** Movimento de ajuste gerado ao efetivar. */
  adjustment_movement_id: string | null;
  /**
   * Posição contada, em inventário por posição (depósito endereçado);
   * `null` fora do endereçamento.
   */
  bin_id: string | null;
  /** Caminho da posição (`/A/01/03`), para a equipe achar a prateleira. */
  bin_path: string | null;
  counted_quantity: DecimalText | null;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Lote; `null` quando o item não é controlado por lote. */
  lot_id: string | null;
  /**
   * A explicação da divergência mora aqui e em nenhum outro lugar: sem
   * ela a tela mostra uma diferença de quantidade sem causa.
   */
  note: string | null;
  /**
   * Congelado na abertura: é contra ESTE número que a contagem diverge, e
   * não contra o saldo de agora, que se mexeu enquanto se contava.
   */
  system_quantity: DecimalText;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
}

/** Página de `StockInventoryDto`, em ordem estável, com o cursor da próxima. */
export interface StockInventoryPageDto {
  /** Os itens desta página. */
  items: StockInventoryDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Abrangência do inventário: só documenta os valores, o fio é texto. */
export type StockInventoryScope = "full" | "partial";

/** Situação do inventário: só documenta os valores, o fio é texto. */
export type StockInventoryStatus = "open" | "counted" | "posted" | "cancelled";

/** Um valor de campo personalizado de lote preenchido. */
export interface StockLotCustomValueDto {
  /** `text`, `number`, `date`, `bool` ou `select`: diz a forma de `value`. */
  data_type: StockLotFieldType;
  /**
   * Código do campo; `null` quando o catálogo não define mais o campo, e a
   * linha fica para não esconder um valor gravado.
   */
  field_code: string | null;
  /** Campo (definição do catálogo). */
  field_id: string;
  /** O valor, na forma que `data_type` anuncia. */
  value: StockCustomValue;
}

/** Os valores de campos personalizados de um lote, como ficaram gravados. */
export interface StockLotCustomValuesDto {
  /** Os valores preenchidos. */
  values: StockLotCustomValueDto[];
}

/** Lote de uma variante, com datas, saldo e campos personalizados. */
export interface StockLotDto {
  /** Código curto, único no escopo. */
  code: string;
  /**
   * O formulário personalizado do lote. A definição é do
   * catálogo; aqui vem só o que foi preenchido.
   */
  custom_values: StockLotCustomValueDto[];
  /** Data de validade (AAAA-MM-DD); `null` quando não há. */
  expires_on: string | null;
  /** Identificador (Snowflake, em string). */
  id: string;
  /**
   * Vencido não sai por venda (E5), só por perda. O front usa isto para
   * separar as duas coisas na tela em vez de deixar o usuário tentar.
   */
  is_expired: boolean;
  /** Data de fabricação (AAAA-MM-DD); `null` quando não há. */
  manufactured_on: string | null;
  /** Recebimento que criou o lote; `null` quando nasceu por outro caminho. */
  origin_receipt_id: string | null;
  /** Data de compra (AAAA-MM-DD); `null` quando não há. */
  purchased_on: string | null;
  /** Saldo remanescente deste lote, na unidade base. */
  quantity_on_hand: DecimalText;
  /** Fornecedor (pessoa do cadastro). */
  supplier_person_id: string | null;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
}

/** Forma do valor de um campo personalizado do lote: só documenta os valores, o fio é texto. */
export type StockLotFieldType = "text" | "number" | "date" | "bool" | "select";

/** Página de `StockLotDto`, em ordem estável, com o cursor da próxima. */
export interface StockLotPageDto {
  /** Os itens desta página. */
  items: StockLotDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Rastreio de um lote: o lote e todo movimento que o tocou. */
export interface StockLotTraceDto {
  lot: StockLotDto | null;
  /**
   * Todo movimento que tocou o lote, do recebimento à saída. É o que
   * responde "quem comprou o lote X" numa vigilância sanitária.
   */
  movements: StockMovementDto[];
}

/** Consumo de uma camada de custo por um movimento de saída. */
export interface StockMovementAllocationDto {
  /** Camada de custo consumida. */
  cost_layer_id: string;
  /** RFC 3339. Quando a camada consumida entrou no estoque (a chave do PEPS). */
  layer_entered_at: string | null;
  /** Do lote de onde saiu, quando houver. Serve o rastreio de recall. */
  lot_id: string | null;
  /** Quantidade consumida da camada, em string decimal. */
  quantity: DecimalText;
  unit_cost: DecimalText | null;
}

/** Movimento de estoque: o fato append-only que muda saldo e custo. */
export interface StockMovementDto {
  /**
   * Situação do lançamento contábil do movimento.
   *
   * Valores: `not_applicable`, `pending`, `posted`, `failed`.
   */
  accounting_status: StockAccountingStatus;
  /**
   * De quais camadas saiu e a que custo - é o que torna o CMV auditável
   * (invariante E4). Vazio numa entrada.
   */
  allocations: StockMovementAllocationDto[];
  /**
   * ⚠️: `true` quer dizer "não sei", não "nenhuma". A lista vem
   * de uma releitura feita DEPOIS de o movimento estar gravado; quando
   * ela falha, a lista vazia seria idêntica à de uma entrada, que não
   * consome camada. Quem exibe o CMV precisa reconsultar em vez de
   * mostrar "sem custo".
   */
  allocations_unavailable: boolean;
  /**
   * Cópia CONGELADA do centro de custo do depósito no instante do
   * movimento: é com ele que as duas pernas do lançamento foram ao razão.
   * Reapontar o depósito hoje não muda este campo em movimento nenhum.
   */
  cost_center_id: string | null;
  /** Quando foi registrado (RFC 3339). */
  created_at: string;
  /** Usuário que registrou; `null` quando foi o sistema. */
  created_by: string | null;
  /**
   * `1` entra, `-1` sai. O sinal mora AQUI e nunca na quantidade - uma
   * quantidade negativa espalhada pelo dado transforma todo `SUM` numa
   * armadilha.
   */
  direction: number;
  /** Id do documento no `fiscal`, quando `fiscal_status = issued`. */
  fiscal_document_id: string | null;
  fiscal_status: StockFiscalStatus | null;
  /** Motivo, quando `fiscal_status = waived`. */
  fiscal_waiver_reason: string | null;
  /** Identificador (Snowflake, em string). */
  id: string;
  /** Id do lançamento no `pay`, quando contabilizado. */
  ledger_entry_ref: string | null;
  /** Lote; `null` quando o item não é controlado por lote. */
  lot_id: string | null;
  /**
   * Tipo do movimento.
   *
   * Valores: `entry`, `exit`, `transfer_out`, `transfer_in`, `adjustment`, `loss`, `write_off`, `supplier_return`, `transform_out`, `transform_in`, `sale_return`.
   */
  movement_type: StockMovementType;
  /** Observação livre; `null` quando não há. */
  note: string | null;
  /**
   * ⚠️ Duas datas, duas perguntas. `occurred_at` é quando o fato
   * aconteceu (competência, demanda, fila do PEPS); `created_at` é quando
   * foi registrado. É a diferença entre as duas que prova um lançamento
   * feito depois do fechamento do mês.
   */
  occurred_at: string;
  /** Referência do documento de origem; `null` quando não há. */
  origin_ref: string | null;
  /**
   * Tipo do documento que originou o movimento.
   *
   * Valores: `manual`, `receipt`, `sale`, `pdv`, `inventory`, `transfer`, `reversal`, `supplier_return`, `transformation`, `external_sync`, `transfer_order`.
   */
  origin_type: StockOriginType;
  /** Sempre positiva, SEMPRE na unidade base (o servidor já converteu). */
  quantity: DecimalText;
  /** Preenchido quando este movimento estorna outro (E3). */
  reverses_movement_id: string | null;
  /** Número de série; `null` quando o item não é serializado. */
  serial_id: string | null;
  /** As duas pernas de uma transferência compartilham este id. */
  transfer_pair_id: string | null;
  unit_cost: DecimalText | null;
  /** Variante (SKU) do catálogo. */
  variant_id: string;
  /** Depósito. */
  warehouse_id: string;
}

/** Página de `StockMovementDto`, em ordem estável, com o cursor da próxima. */
export interface StockMovementPageDto {
  /** Os itens desta página. */
  items: StockMovementDto[];
  /** Cursor opaco da próxima página; vazio na última. */
  next_page_token: string;
}

/** Tipo do movimento de estoque: só documenta os valores, o fio é texto. */
export type StockMovementType = "entry" | "exit" | "transfer_out" | "transfer_in" | "adjustment" | "loss" | "write_off" | "supplier_return" | "transform_out" | "transform_in" | "sale_return";

/** Documento que originou o movimento ou a reserva: só documenta os valores, o fio é texto. */
export type StockOriginType = "manual" | "receipt" | "sale" | "pdv" | "inventory" | "transfer" | "reversal" | "supplier_return" | "transformation" | "external_sync" | "transfer_order";

/** Uma nota recebida que ainda não virou recebimento, com o motivo. */
