  /** Quem abriu. */
  created_by_member_id: string;
  /** Para quem. */
  customer_label: string;
  /** O cliente do cadastro. */
  customer_person_id: string | null;
  /** O pedido em detalhe. */
  description: string;
  /** Quando concluiu. */
  done_at: string | null;
  /** Os executantes; o primeiro é o responsável. */
  executors: WorkServiceOrderExecutor[];
  /** Id (Snowflake). */
  id: string;
  /** Minutos apontados, recusados fora. */
  logged_minutes: number;
  /** Número sequencial na organização. */
  number: number;
  /** O código do projeto. */
